import { Book } from "@/lib/types";

export const isaiah: Book = {
  id: "isaiah",
  name: "Jesaja",
  shortName: "Jes",
  testament: "old",
  introduction: `Der Erlöser wird kommen!\nJesaja ist der \"König\" der alttestamentlichen Propheten, wenn wir die gewaltige Schau von Gott, die Macht der Sprache, die Schönheit des Ausdrucks und die geistliche Tiefe seines Buches berücksichtigen. Gleichzeitig ist er aber auch der \"Evangelist\" unter ihnen. Das Buch des Propheten Jesaja wird deshalb von vielen als das bedeutendste Buch des Alten Testaments angesehen. Jesaja lebte in einer turbulenten Zeit, sah Reiche kommen und gehen, erlebte das Getöse eines weltweiten Umbruchs und hielt in einfachem Glauben fest an seinem Gott. Von allen prophetischen Büchern weist dieses Buch wohl am deutlichsten auf Jesus Christus als den Welterlöser hin. Der Prophet wirkte etwa von 750 v.Chr. an bis in die Zeit des Königs Hiskija. Nach jüdischer Überlieferung soll er unter Manasse den Märtyrertod gestorben sein. Demnach verkündigte er mehr als 60 Jahre lang Gottes Gerechtigkeit, warnte vor seinem Gericht und tröstete sein Volk.\n**Jesajas Buch** ist kunstvoll in Chiasmen (sich spiegelnden Strukturen) aufgebaut, die sich im ersten Teil von Kapitel 1-35 um bestimmte Erzähltexte (Narrative) gruppieren. Der zweite Teil des Buches von Kapitel 40-66 enthält keine Erzähltexte, ist aber ebenso wie der erste chiastisch aufgebaut. Die Kapitel 36-39 bilden als zentrale Erzähltexte das Scharnier zwischen beiden Hauptteilen des Buches. Jesajas Verkündigung kann folgendermaßen eingeteilt werden: die Botschaft an das damalige Volk (Kapitel 1-39), die Botschaft vom kommenden Messias (Kapitel 40-66). Wir gehen davon aus, dass alle Teile des Buches von Jesaja selbst stammen.\n****Das Buch zeigt, wie Jesaja in einer turbulenten Zeit immer wieder auf den Retter Israels und der ganzen Welt hingewiesen hat.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Dies ist die Offenbarung, die Jesaja Ben-Amoz über Juda und Jerusalem empfangen hat, als die Könige Usija, Jotam, Ahas und Hiskija* dort regierten.", heading: "1-35: Assyrien im Hintergrund\nJesajas Botschaft kompakt (1)", footnotes: ["... Hiskija. Die vier Könige regierten von 790 bis 686 v.Chr. über das Südreich Juda."] },
      { number: 2, text: "Hört zu, ihr Himmel! / Du Erde, horch auf! / Hört, was Jahwe euch sagt! / \"Kinder zog ich groß, / ich päppelte sie hoch, / doch sie lehnten sich gegen mich auf.", heading: "Ein rebellisches Volk" },
      { number: 3, text: "Jeder Ochse kennt seinen Besitzer, / jeder Esel den Fresstrog seines Herrn. / Doch Israel begreift nicht, wem es gehört. / Mein Volk hat keinen Verstand.\"" },
      { number: 4, text: "Weh dem sündigen Volk, / der Sippschaft voller Schuld, / der Brut von Verbrechern, / dem verdorbenen Geschlecht. / Sie haben sich von Jahwe getrennt, / den Heiligen Israels verschmäht / und ihm den Rücken gekehrt." },
      { number: 5, text: "Wurdet ihr noch nicht genug bestraft, / dass ihr immer noch aufsässig seid? Das ganze Haupt ist wund, / das ganze Herz ist krank:" },
      { number: 6, text: "Von Kopf bis Fuß ist keine heile Stelle mehr, / nur Beulen, Striemen, frische Wunden, / nicht gereinigt, nicht verbunden, / und keine Salbe ist darauf." },
      { number: 7, text: "Euer Land ist verwüstet, / eure Städte verbrannt. Und euer Ackerland? / Fremde verzehren seinen Ertrag, / und ihr seht ohnmächtig zu. / Es ist alles zerstört, / als hätten fremde Horden gehaust." },
      { number: 8, text: "Nur die Tochter Zion* steht noch da / wie eine Hütte im Weinberg, / ein Schutzdach im Gurkenfeld, / eine Stadt, die man behüten muss.", footnotes: ["Tochter Zion. Synonym für die Stadt Jerusalem und seine Einwohner."] },
      { number: 9, text: "Hätte Jahwe, der allmächtige Gott,* nicht einen Rest von uns übrig gelassen, / es wäre uns wie Sodom gegangen, / und wie Gomorra* wären wir jetzt*.", footnotes: ["der allmächtige Gott. Hebräisch: Zebaoth, das heißt \"Heere\" oder \"Kriege\". In der LXX wird der Begriff immer mit \"pantokrator\" = \"Allherrscher\" oder \"Allmächtiger\" wiedergegeben.", "Sodom ... Gomorra. Städte, die Gott durch Feuer vernichtet hat, siehe 1. Mose 19,24-25.", "Wird im Neuen Testament von Paulus sinngemäß nach der LXX zitiert: Römer 9,29"] },
      { number: 10, text: "Hört das Wort Jahwes, ihr Mächtigen von Sodom! / Vernimm die Weisung unseres Gottes, Volk von Gomorra!" },
      { number: 11, text: "\"Was soll ich mit der Menge eurer Opfer?\", spricht Jahwe. / \"Ich habe es satt, dass ihr mir Schafböcke und das Fett von Mastkälbern verbrennt! / Das Blut von Stieren, Lämmern, Böcken mag ich nicht!" },
      { number: 12, text: "Wenn ihr in den Tempel kommt, / um vor mir zu erscheinen, / meine Vorhöfe zertrampelt – wer hat das von euch verlangt?" },
      { number: 13, text: "Lasst eure nutzlosen Opfer! / Euer Weihrauch ist mir ein Gräuel!" },
      { number: 14, text: "Neumond, Sabbat und andere Feste: / sündige Feiern ertrage ich nicht!" },
      { number: 15, text: "Und wenn ihr betet mit ausgebreiteten Händen, / verhülle ich meine Augen vor euch. / Auch wenn ihr mich noch so mit Bitten bestürmt, höre ich nicht, / denn eure Hände sind voll Blut." },
      { number: 16, text: "Wascht und reinigt euch! / Schafft mir eure bösen Taten aus dem Weg! / Hört auf, vor meinen Augen Böses zu tun!" },
      { number: 17, text: "Lernt Gutes zu tun / und fragt nach dem, was richtig ist! / Weist die Unterdrücker zurück! / Verhelft Waisen und Witwen zu ihrem Recht!\"" },
      { number: 18, text: "\"Kommt her, wir wollen sehen, wer im Recht ist!\", / spricht Jahwe. / \"Wenn eure Sünden rot sind wie das Blut, / werden sie doch weiß wie Schnee; / und wenn sie rot wie Purpur sind, / werden sie wie weiße Wolle sein." },
      { number: 19, text: "Wenn ihr willig auf mich hört, / dürft ihr die Früchte des Landes genießen." },
      { number: 20, text: "Doch wenn ihr euch weigert und widerspenstig seid, / sollt ihr vom Schwert gefressen werden.\" / Ja, der Mund Jahwes hat dies gesagt!" },
      { number: 21, text: "Wie ist zur Hure geworden die treue Stadt! / Sie war voller Recht, / Gerechtigkeit wohnte in ihr, / und jetzt hausen Mörder darin." },
      { number: 22, text: "Dein Silber ist Schlacke geworden, / dein Wein mit Wasser gepanscht!" },
      { number: 23, text: "Deine Führer – Aufrührer sind sie, / mit Dieben vereint. / Sie mögen Bestechung / und gieren nach einem Geschenk. / Den Waisen verhelfen sie nicht zum Recht, / und Witwen hören sie gar nicht erst an." },
      { number: 24, text: "Darum spricht Jahwe, der Herr, / der allmächtige Gott, / der Starke Israels: / \"Weh euch! / Ich werde mir Genugtuung verschaffen! / Ja, ich werde euch eure Feindschaft vergelten!" },
      { number: 25, text: "Meine Hand wird gegen euch sein! / Deine Schlacken werde ich ausschmelzen wie mit Laugensalz / und ausscheiden dein unedles Metall." },
      { number: 26, text: "Dann werde ich dir Richter geben wie früher / und Ratgeber wie zum Beginn. Dann wird man dich nennen: 'Stadt des Rechts' und 'treue Stadt'." },
      { number: 27, text: "Zion wird durchs Recht erlöst, / und wer dort umkehrt, durch Gerechtigkeit." },
      { number: 28, text: "Doch Rebellen und Sünder trifft der Zerbruch, / wer Jahwe verlässt, kommt um!" },
      { number: 29, text: "Wer heilige Bäume verehrt, wird beschämt, – schamrot, wer den Göttern Gärten pflegt." },
      { number: 30, text: "Wie eine verwelkte Eiche werdet ihr stehen, / wie ein Garten, der kein Wasser bekommt." },
      { number: 31, text: "Der Starke wird dann wie Zunder sein / und zum zündenden Funken sein Werk. / In Flammen gehen sie alle auf, / und es gibt niemand, der löscht." },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Diese Botschaft wurde Jesaja Ben-Amoz über Juda und Jerusalem offenbart.", heading: "Gericht und Heil für Juda (2-12)\nDas Friedensreich" },
      { number: 2, text: "Am Ende der von Gott bestimmten Zeit wird folgendes geschehen:Festgegründet an der Spitze der Berge / steht der Berg mit dem Haus Jahwes, / erhaben über alle Hügel, / und alle Völker strömen ihm zu." },
      { number: 3, text: "Die Menschen sagen überall: / \"Kommt, wir ziehen zum Berg Jahwes, / zum Haus, das dem Gott Jakobs* gehört. / Er soll uns lehren, was recht ist; / was er sagt, wollen wir tun. / Denn von Zion geht die Weisung aus, / von Jerusalem das Wort Jahwes.\"", footnotes: ["Jakob, der von Gott den Namen Israel erhielt, war der Stammvater des Volkes Israel."] },
      { number: 4, text: "Er spricht Recht im Streit der Völker; / er weist viele Nationen zurecht. / Dann schmieden sie die Schwerter zu Pflugscharen um, / die Speere zu Messern für Winzer. / Kein Volk greift mehr das andere an, / und niemand lernt mehr für den Krieg." },
      { number: 5, text: "Auf, ihr Nachkommen Jakobs, / lasst uns leben im Licht von Jahwe." },
      { number: 6, text: "Ja, du hast verstoßen die Nachkommen Jakobs, / dein Volk, / denn ihr Land ist mit östlichen Bräuchen* gefüllt. / Wie die Philister deuten sie Zeichen, / zaubern mit Fremden / und klatschen in die Hand.", heading: "Der Tag Jahwes", footnotes: ["östliche Bräuche. Abergläubische Praktiken aus Syrien und Mesopotamien."] },
      { number: 7, text: "Ihr Land ist voll von Silber und Gold, / sie haben Schätze ohne Ende. / Ihr Land ist voll von Pferden / und unzähligen Streitwagen zum Kampf." },
      { number: 8, text: "Und ihr Land ist voll von Götzen. / Sie beten ihre Bildwerke an, / die doch von Menschenhänden gemacht sind." },
      { number: 9, text: "Ja, da bückt sich der Mensch, / da erniedrigt sich der Mann. / \"Vergib ihnen das nicht, Jahwe!\"" },
      { number: 10, text: "Verkriech dich zwischen Felsen, / versteck dich in der Erde / vor dem Schrecken Jahwes, / vor der Pracht seiner Majestät!" },
      { number: 11, text: "Da werden stolze Augen gesenkt / und hochmütige Männer geduckt. / Jahwe allein ist groß an jenem Tag." },
      { number: 12, text: "Denn Jahwe, der allmächtige Gott, hat einen Tag vorgesehen, / an dem er alles erniedrigen wird, / alles, was groß, stolz und überheblich ist," },
      { number: 13, text: "alle Zedern auf dem Libanon, / wie stolz und hoch sie auch sind, / und alle Eichen auf dem Baschan*,", footnotes: ["Baschan. Hochebene von sprichwörtlicher Fruchtbarkeit, nordöstlich vom See Gennesaret."] },
      { number: 14, text: "alle hohen Berge und alle stattlichen Hügel," },
      { number: 15, text: "jeden hohen Turm und jede steile Mauer," },
      { number: 16, text: "alle Hochseeschiffe* und jedes prunkende Boot.", footnotes: ["Hochseeschiffe. Wörtlich: Tarschisch-Schiffe. Hochseetaugliche Schiffe, die bis nach Tarschisch (vermutlich in Südspanien) fuhren."] },
      { number: 17, text: "Dann wird der Stolz der Menschen gebeugt, / die hochmütigen Männer geduckt. / Jahwe allein ist groß an jenem Tag," },
      { number: 18, text: "und mit den Götzen ist es aus und vorbei." },
      { number: 19, text: "Dann wird man sich in Felshöhlen verkriechen vor dem Schrecken Jahwes / und in Erdlöchern verstecken vor der Pracht seiner Majestät, / wenn er aufsteht und die Erde in Schrecken versetzt." },
      { number: 20, text: "An jenem Tag werfen sie ihre Götzen weg. / Wo Ratten und Fledermäuse hausen, / liegen jetzt die Götter aus Silber und Gold, / die sie sich zur Anbetung machten." },
      { number: 21, text: "Und sie verkriechen sich im Fels, / in Höhlen und Spalten, / vor dem Schrecken Jahwes, / vor der Pracht seiner Majestät, / wenn er aufsteht und die Erde in Schrecken versetzt." },
      { number: 22, text: "Zählt nicht auf Menschen, / sie sind nur ein Hauch. / Ein Mensch, was bedeutet er schon?" },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Denn seht, der Herr, Jahwe, der allmächtige Gott, / nimmt weg, worauf sich Jerusalem stützt – jeden Vorrat an Wasser und Brot,", heading: "Gericht durch Verfall" },
      { number: 2, text: "jeden Helden und Krieger, / Richter und Propheten, / Wahrsager und Ältesten," },
      { number: 3, text: "jeden Offizier und jeden Angesehenen, / jeden Ratgeber, Zauberer und Beschwörer." },
      { number: 4, text: "\"Unreife Burschen lasse ich herrschen, / Willkür regiert in der Stadt.\"" },
      { number: 5, text: "Dann fällt einer über den anderen her, / jeder gegen jedermann; / der Junge wird frech gegen den Alten, / der Nichtsnutz gegen den geachteten Mann." },
      { number: 6, text: "Dann packt einer seinen Verwandten am Arm: / \"Du hast noch einen Mantel\", sagt er, / \"du sollst unser Anführer sein! / Diese Trümmer seien in deiner Gewalt!\"" },
      { number: 7, text: "Doch der wird rufen: / \"Nein, ich will nicht euer Notarzt sein. / Auch ich habe weder Mantel noch Brot! / Ich will nicht euer Anführer sein!\"" },
      { number: 8, text: "Jerusalem stürzt und Juda fällt, / denn sie kränken Jahwe mit Wort und mit Tat / und trotzen seiner Hoheit und Macht." },
      { number: 9, text: "Die Frechheit ihrer Gesichter klagt sie an. / Wie Sodomiter* prahlen sie mit ihrem bösen Tun / und verhehlen ihre Sünden nicht. / Weh ihrer Seele! / Denn sich selber tun sie Böses an!", footnotes: ["Sodomiter. Menschen aus der Stadt Sodom, die für ihre schweren Sünden berüchtigt waren, siehe 1. Mose 18,16-19,29."] },
      { number: 10, text: "Sagt denen, die Gott lieben, dass es gut mit ihnen wird, / denn sie werden sich freuen an der Frucht ihres Tuns." },
      { number: 11, text: "Doch weh den Gottverächtern, / denn ihre bösen Taten kommen über sie selbst." },
      { number: 12, text: "Ach, mein armes Volk! / Ausbeuter sind bei dir an der Macht, / und Frauen herrschen über dich. / O mein Volk, / deine Führer sind Verführer, / sie zeigen dir den falschen Weg." },
      { number: 13, text: "Da erhebt sich Jahwe zum Gericht, / um Recht zu schaffen seinem Volk." },
      { number: 14, text: "Ihre Ältesten und Führer lädt er sich vor: / \"Ihr habt den Weinberg ruiniert! / In euren Häusern stapelt sich das von Armen geraubte Gut!" },
      { number: 15, text: "Was tretet ihr mein Volk nieder, / zermalmt, die ohne Hilfe sind?\", / spricht Jahwe, der allmächtige Gott." },
      { number: 16, text: "Das hat Jahwe gesagt: \"Weil die Töchter Zions hochmütig sind, weil sie mit hochgereckten Hälsen dahergehen und aufreizende Blicke um sich werfen, weil sie mit trippelnden Schritten herumstolzieren, damit man das Klirren der Fußspangen hört," },
      { number: 17, text: "wird der Herr ihren Scheitel kahl und schorfig werden lassen und Jahwe ihre Scham entblößen." },
      { number: 18, text: "An diesem Tag wird der Herr ihnen den Schmuck wegnehmen: das Knöchelgeklirr, die Sönnchen und Halbmonde am Hals," },
      { number: 19, text: "Ohrgehänge und Armspangen, Flatterschleier" },
      { number: 20, text: "und Kopfbunde, Schrittkettchen und Brustbänder, Parfümfläschchen und Amulette," },
      { number: 21, text: "Fingerringe und Nasenringe," },
      { number: 22, text: "Festkleider und Mäntel, Umschlagtücher, Täschchen" },
      { number: 23, text: "und Spiegel, feinste Unterwäsche, Kopftücher und weite Schleier.\"" },
      { number: 24, text: "Dann gibt es statt des Wohlgeruchs Gestank, / statt des Gürtels einen Strick, / statt Lockengeringel eine Glatze, / statt des Festgewandes einen umgürteten Sack, / statt der Schönheit ein Brandmal." },
      { number: 25, text: "Deine Männer fallen durchs Schwert, / deine Helden durch den Krieg." },
      { number: 26, text: "Von Totenklage hallen deine Tore wider. / Sie ist am Ende. / Leer und einsam sitzt sie da." },
    ] },
    { number: 4, verses: [
      { number: 1, text: "An dem Tag klammern sich sieben Frauen an einen Mann. \"Wir sorgen selbst für unser Essen, wir kümmern uns selbst um unsere Kleidung, wir wollen nur deine Frauen sein. Lass uns deinen Namen tragen und nimm die Schande von uns, dass wir keinen Mann und keine Kinder haben.\"" },
      { number: 2, text: "An dem Tag wird der Spross* Jahwes zur Zierde und zur Ehre sein; ja alles, was Gott wachsen lässt, wird zur Freude und zum Stolz für die sein, die dem Untergang entkommen sind.", heading: "Hoffnung für den Rest", footnotes: ["Spross. Das meint hier alles, was Jahwe sprossen und wachsen lässt, deutet aber auch schon auf den kommenden Messias hin."] },
      { number: 3, text: "Die Überlebenden in Jerusalem, alle, die in Zion übrig geblieben sind, werden als Gottgeweihte betrachtet werden, alle, deren Namen zum Leben aufgeschrieben sind." },
      { number: 4, text: "Wenn der Herr durch den Sturm von Gericht und Läuterung den Kot der Töchter Zions abgewaschen und die Blutschuld Jerusalems aus der Stadt weggespült hat," },
      { number: 5, text: "wird Jahwe über dem Zionsberg und über allen, die sich dort versammeln, tagsüber eine Wolke erscheinen lassen und Rauch – und in der Nacht ein flammendes Feuer. Wie ein Schutzdach breitet er seine Herrlichkeit über diesem Ort aus." },
      { number: 6, text: "Wie eine Laubhütte wird sie euch vor der Sonne schützen und eine Zuflucht vor Regen und Sturm sein." },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Ich will singen von dem, den ich liebe, / ein Lied vom Weinberg meines Freundes*: / Mein Freund hatte einen Weinberg auf einer fruchtbaren Höhe.", heading: "Das Weinberglied", footnotes: ["Freund. Damit meint Jesaja Gott, seinen Herrn."] },
      { number: 2, text: "Er grub ihn um und entfernte die Steine / und bepflanzte ihn mit edelsten Reben. / Einen Turm baute er mitten darin / und hieb auch eine Kelter aus. / Dann wartete er auf die süße Frucht. / Doch die Trauben waren sauer und schlecht." },
      { number: 3, text: "Nun, ihr Bürger von Jerusalem, Männer von Juda: / Wie denkt ihr über meinen Weinberg und mich?" },
      { number: 4, text: "Habe ich nicht alles an meinem Weinberg getan? / Warum hoffte ich auf süße Trauben / und er brachte saure Frucht?" },
      { number: 5, text: "Jetzt sage ich euch, was ich ihm tue: / Ich reiße seine Hecke aus, / damit er von Herden abgeweidet wird, / ich breche seine Mauer ab, / dass er von allen zertrampelt wird." },
      { number: 6, text: "Zu einer Wüste soll er werden, / nicht mehr beschnitten und behackt – und von Dornen und Disteln bedeckt. / Und den Wolken will ich befehlen, / dass kein Regen mehr auf ihn fällt." },
      { number: 7, text: "Denn der Weinberg von Jahwe, dem allmächtigen Gott, ist das Volk Israel. / Und die Männer von Juda sind die Pflanzung seiner Lust. / Er hoffte auf Rechtsspruch / und erntete Rechtsbruch, / er hoffte auf Gerechtigkeit / und hörte Geschrei über Schlechtigkeit." },
      { number: 8, text: "Weh denen, die sich ein Haus neben das andere stellen, / ein Feld nach dem anderen kaufen, / bis kein Grundstück mehr da ist / und ihnen alles gehört.", heading: "Sechs Wehrufe über das trotzige Volk" },
      { number: 9, text: "Da hörte ich den Schwur Jahwes: / \"Die vielen Häuser werden öde und leer, / so groß und schön sie auch sind: / Sie werden ohne Bewohner sein." },
      { number: 10, text: "Denn zehn Joch* Rebland geben einen Eimer* Saft / und zehn Sack* Getreide nur einen Zentner* Ertrag.", footnotes: ["Ein Joch ist die Fläche, die von einem Joch Ochsen an einem Tag gepflügt werden konnte, etwa 1600 Quadratmeter; 10 Joch waren also etwa anderthalb Hektar.", "ein Eimer. Wörtlich: ein Bat = 22 Liter.", "zehn Sack. Wörtlich: ein Homer = 220 Liter.", "ein Zentner. Wörtlich: ein Efa = ein Bat = 22 Liter, also ein Zehntel des Gesäten."] },
      { number: 11, text: "Weh denen, die schon am frühen Morgen hinterm Bier her sind / und sich erhitzen am Wein bis spät in die Nacht." },
      { number: 12, text: "Zither und Harfe, Pauke und Flöte / und Wein gehören zu ihrem Gelage, / doch was Jahwe tut, beachten sie nicht, / vor seinem Wirken haben sie keinen Respekt." },
      { number: 13, text: "Weil mein Volk keine Einsicht hat, wird es gefangen weggeschleppt. / Seine Edelleute werden Hungerleider sein, / und seine lärmende Menge verschmachtet vor Durst." },
      { number: 14, text: "Das Totenreich reißt seinen Schlund weit auf, / und hinab fährt seine ganze Pracht, das ganze johlende und lärmende Gewühl." },
      { number: 15, text: "Da werden Menschen gebeugt und Männer geduckt, / da werden stolze Augen gesenkt." },
      { number: 16, text: "Und Jahwe, der allmächtige Gott, wird durch sein Urteil erhöht. / Der heilige Gott zeigt sich heilig im gerechten Gericht." },
      { number: 17, text: "Zwischen den Trümmern der Stadt weiden die Schafe, / und Ziegen nähren sich in den Ruinen der Vertriebenen." },
      { number: 18, text: "Weh denen, die die Strafe für ihre Schuld / herbeiziehen an Stricken des Wahns. / Das Gericht über ihre Sünde schleppen sie mit Wagenseilen herbei," },
      { number: 19, text: "und sagen dazu: \"Er soll sich beeilen, der heilige Gott Israels, / wir wollen endlich sehen, was er mit uns tut!\"" },
      { number: 20, text: "Weh denen, die Böses gut und Gutes böse nennen, / die Finsternis zum Licht erklären und Licht zur Finsternis, / die das Bittere süß und das Süße bitter machen." },
      { number: 21, text: "Weh denen, die sich selbst für weise halten / und meinen, dass sie verständig sind." },
      { number: 22, text: "Weh denen, die Helden im Weintrinken sind / und tapfer im Mischen von starkem Getränk." },
      { number: 23, text: "Sie sprechen den Gottlosen gerecht durch ein Bestechungsgeschenk, / und den Gerechten nehmen sie ihr Recht." },
      { number: 24, text: "Darum: Wie eine Feuerzunge Stoppeln verzehrt, / wie dürres Gras in der Flamme zusammensinkt, / wird ihre Wurzel wie Asche sein, / ihre Blüte auffliegen wie Staub. / Denn sie haben das Gesetz Jahwes, des Allmächtigen, verworfen, / das Wort des Heiligen Israels verschmäht." },
      { number: 25, text: "Darum entflammte der Zorn Jahwes gegen sein Volk, / er hob seine Hand und schlug zu, / dass die Berge erbebten / und Leichen wie Abfall auf den Straßen lagen. / Und immer noch hat sich sein Zorn nicht gelegt, / seine Hand bleibt drohend ausgestreckt." },
      { number: 26, text: "Er stellt ein Feldzeichen auf für ein Volk in der Ferne, / er pfeift es herbei vom Ende der Welt, / und schon kommen sie eilig heran.", heading: "Drohung durch ein fremdes Heer" },
      { number: 27, text: "Keiner ist erschöpft, und keiner schleppt die Füße nach; / keiner nickt ein, sie sind alle hellwach; / keinem geht der Hüftgurt auf, und keinem löst sich ein Riemen vom Schuh." },
      { number: 28, text: "Ihre Pfeile sind scharf, ihre Bogen gespannt. / Die Hufe ihrer Pferde sind hart wie Stein, / die Räder sausen dahin wie der Sturm." },
      { number: 29, text: "Ihr Kriegsschrei ist wie Löwengebrüll. / Wie junge Löwen brüllen sie auf. / Sie knurren, packen die Beute und schleppen sie fort, / und niemand reißt sie ihnen weg." },
      { number: 30, text: "An dem Tag wird es dröhnen über dem Land, / es wird tosen wie die Brandung am Meer. / Wohin man dann auf der Erde auch blickt: / nur Finsternis und bedrückende Angst. / Dichte Wolken verdunkeln das Licht." },
    ] },
    { number: 6, verses: [
      { number: 1, text: "In dem Jahr als König Usija starb,* sah ich den Herrn. Er saß auf einem hoch aufragenden Thron. Die Säume seines Gewandes füllten den ganzen Tempel aus.", heading: "Jesajas Gottesoffenbarung", footnotes: ["Das Jahr, in dem Usija starb, war 740 v.Chr."] },
      { number: 2, text: "Umgeben war er von Serafim.* Jeder von ihnen hatte sechs Flügel. Mit zweien bedeckte er sein Gesicht, mit zweien seine Beine, und mit zweien flog er.", footnotes: ["Serafim. Die Feurigen. In 4. Mose 21,6.8 war das eine Bezeichnung für die Schlangen. Hier sind die geflügelten Geschöpfe menschenähnlich zu denken (Gesicht, Vers 2, Hand, Vers 6)."] },
      { number: 3, text: "Einer rief dem anderen zu: \"Heilig, heilig, heilig ist Jahwe, der allmächtige Gott. Die ganze Erde bezeugt seine Macht!\"" },
      { number: 4, text: "Von ihrem Rufen erbebten die Fundamente der Tempeltore und das ganze Haus wurde mit Rauch erfüllt." },
      { number: 5, text: "Da rief ich: \"Weh mir! Ich bin verloren! Ich habe den König gesehen, Jahwe, den allmächtigen Gott! Und ich habe doch besudelte Lippen und wohne in einem Volk, das durch seine Worte genauso besudelt ist!\"" },
      { number: 6, text: "Da kam einer der Serafim zu mir geflogen. Er hatte mit einer Zange in der Hand eine glühende Kohle vom Altar genommen" },
      { number: 7, text: "und berührte damit meinen Mund. Er sagte: \"Die Glut hat deine Lippen berührt. Jetzt bist du von deiner Schuld befreit, deine Sünde ist gesühnt.\"" },
      { number: 8, text: "Dann hörte ich die Stimme des Herrn. Er fragte: \"Wen soll ich senden? Wer ist bereit, unser Bote zu sein?\" Da sagte ich: \"Ich bin bereit, sende mich!\"" },
      { number: 9, text: "Und er sprach zu mir:\"Geh, und sage diesem Volk: / 'Hören sollt ihr, hören, aber nichts verstehen! / Sehen sollt ihr, sehen, aber nichts erkennen!'" },
      { number: 10, text: "Verstocke das Herz dieses Volkes / und verstopfe seine Ohren! / Verkleb ihm die Augen, / damit es mit seinen Augen nicht sieht / und mit seinen Ohren nicht hört, / damit sein Herz nicht einsichtig wird, / sich nicht bekehrt und sich so Heilung verschafft!\" *", footnotes: ["Wird im Neuen Testament von Jesus Christus, Paulus und Johannes zitiert: Matthäus 13,14-15; Markus 4,12; Lukas 8,10; Apostelgeschichte 28,26-27; Johannes 12,40."] },
      { number: 11, text: "Da fragte ich: \"Wie lange soll das gehen, Herr?\" / \"Bis die Städte öde und unbewohnt sind\", erwiderte er. / \"Bis die Häuser ohne Menschen und die Felder zur Wüste geworden sind.\"" },
      { number: 12, text: "Jahwe treibt die Menschen weit weg; / das Land wird leer und verlassen sein." },
      { number: 13, text: "Und wenn noch ein Zehntel darin übrig ist, / wird auch das noch niedergebrannt. / Es wird sein wie bei einer Eiche / oder einer Terebinthe*, / wo beim Fällen ein Stumpf übrig bleibt. / Ein heiliger Same ist dieser Stumpf.", footnotes: ["Terebinthe. Belaubter Baum mit breitem Wipfel, der nicht mehr als 7 m hoch wird und als Schattenspender geschätzt ist."] },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Als Ahas Ben-Jotam, der Enkel von Usija, König über Juda war,* zogen die Könige Rezin von Syrien und Pekach Ben-Remalja von Israel gegen Jerusalem.* Sie griffen die Stadt an, konnten sie aber nicht erobern.", heading: "Das Zeichen des Immanuël", footnotes: ["Ahas ... über Juda war. Offenbar war er schon 735 v.Chr. Mitregent geworden, siehe 2. Könige 15,27.", "gegen Jerusalem. Die Invasion von Rezin und Pekach 735/34 v.Chr. ist als syrisch-efraïmitischer Krieg bekannt."] },
      { number: 2, text: "Schon als dem Königshaus gemeldet wurde, dass die syrischen Truppen im Gebiet von Efraïm* stünden, fürchteten sich der König und sein ganzes Volk. Sie zitterten wie vom Sturm geschüttelte Bäume im Wald.", footnotes: ["Efraïm. Einflussreichster Stamm im Nordreich Israels. Sein Name kann für das ganze Nordreich stehen."] },
      { number: 3, text: "Da sagte Jahwe zu Jesaja: \"Geh mit deinem Sohn Schear-Jaschub* hinaus auf die Straße, die zu dem Feld führt, wo die Tuchmacher ihre Stoffe bleichen, an das Ende der Wasserleitung beim oberen Teich. Dort wirst du König Ahas treffen.", footnotes: ["Schear-Jaschub. D.h. Ein Rest kehrt um."] },
      { number: 4, text: "Sag zu ihm: 'Bleib ruhig und handle nicht unüberlegt. Hab keine Angst vor Rezin und Ben-Remalja* und ihrem Zorn. Es sind nur qualmende Brennholzstummel.", footnotes: ["Ben-Remalja. Das ist Pekach, der Sohn Remaljas. Er herrschte von 740-732 v.Chr. (seit 752 Mitregent) über Israel."] },
      { number: 5, text: "Weil die Syrer unter Rezin und die Efraïmiten unter Ben-Remalja den bösen Plan geschmiedet haben," },
      { number: 6, text: "nach Juda zu ziehen, den Leuten dort Angst einzujagen, ihr Land in Besitz zu nehmen und den Sohn von Tabeal als König einzusetzen," },
      { number: 7, text: "sagt Jahwe, der Herr:Das wird nicht zustande kommen, / das wird nicht geschehen." },
      { number: 8, text: "Damaskus wird nur Syriens Hauptstadt bleiben, / und Rezin nur dort König sein.* Es dauert nur noch 65 Jahre, / dann wird auch Efraïm zerschlagen sein / und als Volk nicht mehr bestehen.*", footnotes: ["nur dort König sein. Syrien wurde schon zwei Jahre später unterworfen (732 v.Chr.)", "nicht mehr bestehen. Schon 722 v.Chr., 12 Jahre nach der Weissagung Jesajas, wurde das Nordreich Israel von den Assyrern erobert. Am Ende der Regierungszeit Asarhaddons, 669 v.Chr. war die aggressive Umsiedlungspolitik der Assyrer beendet und es lebten fremde Völker im Gebiet des Nordreiches Israel."] },
      { number: 9, text: "Bis dahin ist Samaria nur noch Hauptstadt von Efraïm, / und Ben-Remalja muss mit Samaria zufrieden sein. / Hat euer Glaube keinen Bestand, werdet auch ihr nicht bestehen!'\"" },
      { number: 10, text: "Jahwe sprach weiter zu Ahas und ließ ihm sagen:" },
      { number: 11, text: "\"Fordere dir ein Zeichen zur Bestätigung von Jahwe, deinem Gott, ganz gleich, ob aus der Höhe des Himmels oder der Tiefe der Totenwelt.\"" },
      { number: 12, text: "Doch Ahas erwiderte: \"Nein, ich will kein Zeichen verlangen, ich will Jahwe nicht auf die Probe stellen.\"" },
      { number: 13, text: "Da sagte Jesaja: \"Hört zu, ihr vom Königshaus! Reicht es euch nicht, dass ihr den Menschen zur Last fallt? Müsst ihr auch noch die Geduld meines Gottes strapazieren?" },
      { number: 14, text: "Deshalb wird euch der Herr selbst ein Zeichen geben. Seht, die unberührte junge Frau wird schwanger werden und einen Sohn zur Welt bringen, den sie Immanuël (Gott mit uns) nennt.*", footnotes: ["Wird im Neuen Testament von Matthäus zitiert: Matthäus 1,23. Siehe auch die Anmerkung zu Jesaja 7,16."] },
      { number: 15, text: "Er wird Dickmilch* und Honig essen, bis er versteht, das Böse zu verwerfen und das Gute zu erwählen.", footnotes: ["Dickmilch. Überfluss an Milch war in diesem Fall kein gutes, sondern ein schlechtes Zeichen (Vers 22!). Durch die Verwüstung des Landes fehlten die normalen Agrarprodukte."] },
      { number: 16, text: "Und bevor er alt genug ist, Gut und Böse zu unterscheiden, wird das Land der beiden Könige verwüstet sein, vor denen dir jetzt graut.*", footnotes: ["... dir jetzt graut. Die Prophezeiung weist zunächst auf ein Mädchen im Umfeld des Königs, das in Kürze heiraten, schwanger werden und ein Kind namens Immanuël zur Welt bringen wird. Zweieinhalb Jahre später, im Jahr 732 v.Chr., als dieses Kind noch ein kleiner Junge war, zerstörte Tiglat-Pileser III. Damaskus. Damit war der Bund zwischen Syrien und Israel zerbrochen und die Gefahr für Juda erst einmal gebannt. Als der Junge 12/13 Jahre alt war und auf das Gesetz verpflichtet wurde (zwischen Gut und Böse wählen konnte), 722 v.Chr., war auch das Nordreich Israel von den Assyrern erobert. Die eigentliche Erfüllung ist jedoch die Schwangerschaft der Jungfrau Maria und die Geburt von Jesus, unserem Herrn (Matthäus 1,21-23)."] },
      { number: 17, text: "Aber Jahwe wird über dich, dein Volk und deine Familie eine Unglückszeit kommen lassen, wie es sie seit der Trennung Efraïms von Juda* nicht gegeben hat. Das Unglück wird der König von Assyrien sein.", footnotes: ["Die Trennung des Nordreiches Israel (Efraïm) von Juda geschah nach Salomos Tod 931 v.Chr., also fast 200 Jahre vorher."] },
      { number: 18, text: "An dem Tag wird Jahwe sowohl den Fliegenschwarm aus dem Nildelta von Ägypten, als auch den Bienenschwarm aus Assyrien herbeipfeifen." },
      { number: 19, text: "Sie werden kommen und sich überall niederlassen: in Talschluchten und Felsspalten, in Dornenhecken und an jeder Wasserstelle." },
      { number: 20, text: "Dann wird der Herr das Schermesser kommen lassen, das er auf der anderen Seite des Euphrat in Dienst genommen hat, nämlich den König von Assyrien, und euch den Kopf, die Schamhaare und den Bart abscheren*.", footnotes: ["Bart abscheren. Als Zeichen der Demütigung."] },
      { number: 21, text: "Wenn diese Zeit kommt, wird jeder nur noch eine Kuh und zwei Ziegen haben." },
      { number: 22, text: "Aber die werden soviel Milch geben, dass jeder Dickmilch essen muss. Denn von Dickmilch und Honig muss jeder leben, der im Land übrig geblieben ist." },
      { number: 23, text: "Dann wird jeder Weinberg den Dornen und Disteln gehören, selbst solche, die 1000 Weinstöcke haben, von denen jeder ein Silberstück wert war." },
      { number: 24, text: "Nur mit Pfeil und Bogen wird man noch dorthin gehen, denn all das Land wird voller Dornen und Disteln sein." },
      { number: 25, text: "Und die Berghänge, die man jetzt noch mit der Hacke bestellt, wird niemand mehr betreten, weil sie sich in Dornengestrüpp und Disteln verwandelt haben. Nur Rinder und Kleinvieh treibt man noch dorthin.\"" },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Jahwe sagte zu mir: \"Nimm dir eine große Tafel und schreibe darauf mit deutlich lesbarer Schrift: 'Für Schnell-Raub Rasch-Beute'", heading: "Schnell-Raub – Rasch-Beute" },
      { number: 2, text: "und lass dies von zwei vertrauenswürdigen Zeugen bestätigen, dem Priester Urija und Secharja Ben-Jeberechja.\"" },
      { number: 3, text: "Als ich dann mit meiner Frau, der Prophetin, schlief, wurde sie schwanger und brachte einen Sohn zur Welt. Da sagte Jahwe zu mir: \"Nenne ihn 'Schnell-Raub Rasch-Beute'!" },
      { number: 4, text: "Denn ehe der Junge 'Vater' und 'Mutter' sagen kann, werden die Reichtümer von Damaskus und die Schätze Samarias dem König von Assyrien vorangetragen.\"" },
      { number: 5, text: "Weiter sagte Jahwe zu mir:", heading: "Die assyrische Invasion" },
      { number: 6, text: "\"Weil dieses Volk* das ruhig dahinfließende Wasser im Kanal von Schiloach* verachtet und sich über Rezin und Ben-Remalja freut,", footnotes: ["dieses Volk. Das meint hier wohl die pro-assyrische Partei in Juda, die sich freute, dass die Assyrer ihren Feind, das Nordreich Israel, zu vernichten begannen.", "Kanal von Schiloach. Ein Bild für Jerusalem im Gegensatz zu dem riesigen Euphratstrom."] },
      { number: 7, text: "wird der Herr die große und reißende Flut des Euphrat über sie kommen lassen, nämlich den König von Assyrien mit all seiner Heeresmacht. Wie ein Strom, der anschwillt und über alle Ufer tritt," },
      { number: 8, text: "wird er sich bis nach Juda hin wälzen und alles überfluten, sodass den Bewohnern das Wasser bis zum Hals steht.* Die Ausläufer dieser Flut bedecken dein Land weit und breit, Immanuël.\"", footnotes: ["bis zum Hals steht. König Sanheribs Invasion 701 v.Chr., also 34 Jahre später, überschwemmte alle Städte Judas außer Jerusalem."] },
      { number: 9, text: "Tobt ihr Völker und erschreckt! / Hört zu, Nationen in der Ferne! / Rüstet nur! Ihr werdet doch zerschmettert. / Rüstet nur – und resigniert!", heading: "Gott – Zuflucht oder Ruin" },
      { number: 10, text: "Schmiedet ruhig Pläne! / Sie werden in die Brüche gehen. / Beratet euch, so viel ihr wollt! / Es kommt doch nichts dabei heraus. / Denn Gott steht uns bei.*", footnotes: ["Gott steht uns bei. Hebräisch: Immanuël"] },
      { number: 11, text: "Denn so sprach Jahwe zu mir, als seine Hand mich packte und er mich davor warnte, den Weg dieses Volkes mitzugehen:" },
      { number: 12, text: "\"Ihr sollt nicht alles Verschwörung nennen, / was dieses Volk Verschwörung nennt! / Ihr müsst nicht fürchten, was sie erschreckt!" },
      { number: 13, text: "Doch Jahwe, den allmächtigen Gott, / den sollt ihr heilig halten! / Vor ihm sollt ihr euch fürchten. / Er flöße euch den Schrecken ein!*", footnotes: ["Wird im Neuen Testament von Petrus auf Christus angewendet: 1. Petrus 3,14-15."] },
      { number: 14, text: "Für die einen wird er das Heiligtum sein, / doch für die anderen aus ganz Israel: / der Stein, an dem man sich stößt, / der Fels, an dem man fällt.* / Für die Bewohner von Jerusalem wird er Netz und Schlinge sein.", footnotes: ["Wird im Neuen Testament von Paulus zusammen mit Jesaja 28,16 zitiert: Römer 9,33."] },
      { number: 15, text: "Viele von ihnen stolpern und kommen zu Fall, / verstricken und verfangen sich.\"" },
      { number: 16, text: "Gottes Warnungen will ich gut verschnüren / und seine Weisungen meinen Schülern in Verwahrung geben." },
      { number: 17, text: "Und ich will warten auf Jahwe, / will hoffen auf ihn, / der sich den Nachkommen Jakobs nicht zeigt." },
      { number: 18, text: "Seht, ich und die Kinder, die Jahwe mir gab,* / ein Wahrzeichen für Israel, / ein Zeichen von Jahwe, dem allmächtigen Gott, / der auf dem Zionsberg wohnt.", footnotes: ["Wird im Neuen Testament zitiert: Hebräer 2,13."] },
      { number: 19, text: "Und wenn sie euch auffordern, von den Totengeistern Auskunft zu holen, von den Wispernden und Murmelnden, dann erwidert: \"Soll ein Volk denn nicht seinen Gott befragen? Sollen die Lebenden sich von den Toten helfen lassen?" },
      { number: 20, text: "Zurück zur Weisung Jahwes und zu seinen Warnungen!\" Wer nicht so denkt, für den gibt es kein Morgenrot." },
      { number: 21, text: "Verdrossen und hungrig streift er durchs Land. Der Hunger macht ihn rasend und er verflucht seinen König und seinen Gott. Er blickt nach oben" },
      { number: 22, text: "und starrt auf die Erde und sieht nur bedrückende Finsternis, Not und Verzweiflung. Er ist hineingestoßen in lichtlose Nacht." },
      { number: 23, text: "Doch es bleibt nicht dunkel über dem, der von Finsternis bedrängt ist. Hat die frühere Zeit dem Land der Stämme Sebulon und Naftali* auch Schande gebracht, so bringt die spätere den Weg am Meer* wieder zu Ehren, auch das Gebiet östlich des Jordan, wo die Fremden wohnen.", heading: "Das messianische Morgenrot", footnotes: ["Sebulon und Naftali. Israelitische Stämme im Norden des Landes, die unter der assyrischen Invasion 734 und 732 v.Chr. am meisten zu leiden hatten.", "Weg am Meer. Das erfüllte sich, als Jesus von Kafarnaum aus am See Gennesaret wirkte, in der Nähe des Fernweges, der von Ägypten nach Damaskus führte und Weg am Meer genannt wurde."] },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Das Volk, das im Dunkeln lebt, / sieht ein großes Licht. / Licht strahlt auf über denen, / die im Land der Todesschatten wohnen.*", footnotes: ["Wird im Neuen Testament zitiert: Matthäus 4,15-16."] },
      { number: 2, text: "Du weckst den Jubel, machst die Freude groß! / Sie freuen sich vor dir wie in der Erntezeit, / sie jubeln wie beim Beuteverteilen." },
      { number: 3, text: "Denn wie am Tag von Midian* / zerbrichst du das drückende Joch, das ihnen den Rücken gebeugt, / den Stock, der sie angetrieben hat.*", footnotes: ["Tag von Midian. Siehe Richter 7,15-25.", "angetrieben hat. Das erfüllte sich während der Invasion Sanheribs 701 v.Chr. (Jesaja 37,36-38)."] },
      { number: 4, text: "Denn jeder Stiefel, der dröhnend daherstampft, / jeder Mantel, der sich in Blutlachen wälzt, / wird ins Feuer geworfen und verbrannt." },
      { number: 5, text: "Denn ein Kind ist uns geboren, ein Sohn ist uns geschenkt; / das wird der künftige Herrscher sein. / Gott hat ihm seinen Namen gegeben: / wunderbarer Berater, / kraftvoller Gott, / Vater der Ewigkeit, / Friedensfürst." },
      { number: 6, text: "Seine Macht reicht weit, / und sein Frieden hört nicht auf. / Er regiert sein Reich auf Davids Thron, / seine Herrschaft hat für immer Bestand, / denn er stützt sie durch Recht und Gerechtigkeit. / Das wirkt Jahwe, der allmächtige Gott, / im Eifer seiner Leidenschaft." },
      { number: 7, text: "Ein Urteil hat mein Herr über Jakob gefällt, / und an Israel wurde es vollstreckt.", heading: "Der Schatten über Samaria" },
      { number: 8, text: "Zu spüren bekam es das ganze Volk – das von Efraïm und wer in Samaria wohnt – mit seinem selbstherrlich hochmütigen Spruch:" },
      { number: 9, text: "\"Die Ziegel sind gefallen, / doch mit Quadern bauen wir auf, / das Holz der Sykomoren* ist zerbrochen, / doch wir setzen dort Zedernbalken ein.\"", footnotes: ["Das Holz der Sykomore (wilder Feigenbaum) eignete sich sehr gut zum Bauen, besonders für Decken und Dachkonstruktionen. Seine Früchte galten als Nahrung der Armen."] },
      { number: 10, text: "Aber Jahwe wiegelt Rezins Unterfürsten auf, / ihre Feinde stachelt er gegen sie an." },
      { number: 11, text: "Die Syrer kommen von vorn / und von hinten die Philister, / und sie fressen Israel mit vollem Maul. – Trotzdem legt sich Gottes Zorn nicht. / Seine Hand bleibt drohend ausgestreckt." },
      { number: 12, text: "Doch das Volk kehrt nicht um zu dem, der es schlägt. / Jahwe, den allmächtigen Gott, suchen sie nicht." },
      { number: 13, text: "Da haut Jahwe Kopf und Schwanz von Israel ab, / Palmzweig und Binse an einem einzigen Tag." },
      { number: 14, text: "Die Ältesten und Vornehmen sind der Kopf, / der Lügen lehrende Prophet ist der Schwanz." },
      { number: 15, text: "Die Führer dieses Volkes sind Verführer, / und die Geführten wissen nicht mehr wohin." },
      { number: 16, text: "Deshalb freut sich der Herr nicht über seine jungen Männer, / erbarmt sich nicht über seine Witwen und Waisen. / Denn alle sind sie gottlos und böse, / aus jedem Mund kommt schändliches Geschwätz. – Trotzdem legt sich Gottes Zorn nicht. Seine Hand bleibt drohend ausgestreckt." },
      { number: 17, text: "Denn ihre Bosheit lodert auf wie ein Feuer, / das Dornen und Disteln verzehrt. / Im dichten Unterholz des Waldes zündet es / und wirbelt als schwarze Rauchwolke hoch." },
      { number: 18, text: "Das Land ist verbrannt durch den glühenden Zorn / von Jahwe, dem allmächtigen Gott. / Das Volk ist ein Raub der Flammen geworden. / Keiner verschonte den andern:" },
      { number: 19, text: "Man fraß rechts und blieb doch hungrig, / man fraß links und wurde nicht satt. / Jeder fraß das Fleisch seines eigenen Arms." },
      { number: 20, text: "Manasse stürzte sich auf Efraïm / und Efraïm auf den Manasse, / und beide fielen über Juda her. – Trotzdem legt sich Gottes Zorn nicht. / Seine Hand bleibt drohend ausgestreckt." },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Weh denen, die unheilvolle Gesetze erlassen, / die unerträgliche Vorschriften machen," },
      { number: 2, text: "um die Schwachen vom Gericht zu entfernen / und die Armen um ihre Rechte zu bringen, / um die Witwen zu plündern / und die Waisen auszurauben." },
      { number: 3, text: "Was werdet ihr am Tag der Heimsuchung tun, / wenn das Unwetter von ferne her kommt? / Zu wem wollt ihr dann fliehen? / Wo wollt ihr Hilfe suchen / und wo eure Ehre lassen?" },
      { number: 4, text: "Beugt man sich dann nicht in Gefangenschaft, / wird man unter den Erschlagenen sein. – Trotzdem legt sich Gottes Zorn nicht. / Seine Hand bleibt drohend ausgestreckt." },
      { number: 5, text: "Weh Assyrien, der Rute meines Zorns! / In seiner Hand ist der Stock meines Grimms.", heading: "Assyrien geht zu weit" },
      { number: 6, text: "Ich sende ihn gegen einen gottlosen Stamm, / gegen ein Volk, das meinen Zorn erregt, / damit er Beute erbeutet / und raubt wie ein Räuber / und es in den Straßendreck tritt." },
      { number: 7, text: "Doch er stellt sich das ganz anders vor, / er verfolgt seinen eigenen Plan. / Nur Vernichtung von Völkern hat er im Sinn, / auslöschen will er, so viele er kann." },
      { number: 8, text: "\"Jeder meiner Feldherrn ist ein König!\", sagt er." },
      { number: 9, text: "\"Ging es Kalne nicht wie Karkemisch*, / wurde Hamat nicht wie Arpad* besiegt / und Samaria* nicht wie Damaskus*?", footnotes: ["Karkemisch am mittleren Euphrat wurde 717 v.Chr. von den Assyrern besiegt, Kalne in Nordsyrien 738 v.Chr.", "Arpad liegt nördlich von Aleppo, in der Nähe von Hamat und südlich von Kalne. Beide Städte wurden 717 v.Chr. von den Assyrern besiegt.", "Samaria wurde 722 v.Chr. von den Assyrern erobert.", "Damaskus wurde 732 v.Chr. von den Assyrern erobert."] },
      { number: 10, text: "Königreiche bekam ich in meine Gewalt, / die viel mehr Götter hatten, / als in Jerusalem und Samaria Statuen stehen." },
      { number: 11, text: "Was ich an Samaria und seinen Göttern tat, / werde ich auch an Jerusalem und seinen Bildern tun.\"" },
      { number: 12, text: "Doch wenn der Herr sein Werk am Zionsberg und an Jerusalem zu Ende gebracht hat, / wird er mit dem König von Assyrien abrechnen, / mit seiner überheblichen Selbstherrlichkeit / und dem hochmütigen Stolz, / mit dem er auf andere herabsieht." },
      { number: 13, text: "Denn er brüstet sich und sagt:\"Aus eigener Kraft habe ich das alles getan, / mit meiner Klugheit habe ich es fertiggebracht! / Ich habe die Grenzen der Völker verrückt, / ihre Vorräte geplündert / und sie mit Macht von ihren Sitzen gestürzt." },
      { number: 14, text: "Wie in ein Vogelnest langte meine Hand in die Habe der Völker. / Wie Eier in einem verlassenen Nest / habe ich ganze Länder zusammengerafft. Keiner war da, der mit den Flügeln schlug, / keiner der den Schnabel aufriss und einen Piep von sich gab.\"" },
      { number: 15, text: "Rühmt sich die Axt gegen den, der sie gebraucht? / Tut die Säge sich groß gegen den, der sie zieht? / Das wäre, als ob der Stock den schwingt, der ihn hebt, / als ob das tote Stück Holz den Mann bewegt." },
      { number: 16, text: "Darum wird der Herr, Jahwe, der allmächtige Gott, / das fette Assyrien dürr werden lassen. / Unter seiner Pracht flackert ein Brand, / der alles in Flammen aufgehen lässt." },
      { number: 17, text: "Israels Licht wird zum Feuer, / sein heiliger Gott zu einer Flamme, / die seine Dornen und Disteln in Brand setzt / und verzehrt an einem einzigen Tag." },
      { number: 18, text: "Mit Stumpf und Stiel werden Wälder und Gärten verbrannt. / Es wird wie ein Aussterben sein." },
      { number: 19, text: "Ein Junge könnte die Waldbäume zählen, / die ihm noch übrig geblieben sind." },
      { number: 20, text: "An dem Tag wird Israels Rest – und wer sonst vom Haus Jakobs entkommen ist – sich nicht mehr stützen auf den, der ihn schlägt, / sondern ganz auf Jahwe vertrauen, / den Heiligen seines Volkes.", heading: "Der gerettete Rest" },
      { number: 21, text: "Ein Rest kehrt um zum starken Gott, / ein Rest von Jakobs Nachkommenschaft." },
      { number: 22, text: "Und wenn dein Volk so zahlreich wäre wie der Sand am Meer, Israel – nur ein Rest davon kehrt um. / Die Vernichtung ist beschlossen. / Die Gerechtigkeit flutet heran." },
      { number: 23, text: "Denn der Herr, Jahwe, der allmächtige Gott, / vollstreckt die Vernichtung mitten im Land.*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 9,27-28"] },
      { number: 24, text: "Darum spricht der Herr, Jahwe, der allmächtige Gott: / \"Fürchte dich nicht, mein Volk, das in Zion wohnt! / Auch wenn Assyrien den Stock über euch schwingt, / wenn es euch schlägt wie Ägypten damals." },
      { number: 25, text: "Es dauert nur noch eine ganz kurze Zeit, / dann wird mein Zorn zu Ende sein / und ist dann auf Assurs Vernichtung bedacht.\"" },
      { number: 26, text: "Jahwe, der allmächtige Gott, wird über ihn die Geißel schwingen. / Gegen sie holt er dann zum Schlag aus / wie am Rabenfels gegen Midian*; / er streckt seinen Stab aus über das Meer / wie damals gegen das Ägyptervolk.", footnotes: ["gegen Midian. Siehe Richter 7,25."] },
      { number: 27, text: "An dem Tag wird die Last Assyriens von deiner Schulter gleiten, / sein Joch von deinem Nacken weggerissen sein, / durch Stärke zersprengt." },
      { number: 28, text: "Sie kommen auf Aja zu, ziehen durch Migron*; / und in Michmas* lassen sie ihren Tross.", footnotes: ["Aja ... Migron. Orte etwa 16 km nördlich von Jerusalem.", "Michmas. 11 km nördlich von Jerusalem."] },
      { number: 29, text: "Sie marschieren durch die Schlucht. / \"Geba wird unser Nachtquartier sein!\" / Rama* zittert vor Angst, / und Sauls Stadt Gibea* ergreift die Flucht.", footnotes: ["Rama. Heimatstadt Samuels, 8 km nördlich von Jerusalem.", "Gibea. 5 km nördlich von Jerusalem."] },
      { number: 30, text: "Schrei gellend, Gallim! / Lausche Lajescha*! / Armes Anatot*!", footnotes: ["Lajescha. Unbekannte Stadt in der Nähe von Jerusalem.", "Anatot. Heimatstadt des Propheten Jeremia."] },
      { number: 31, text: "Madmena flieht, / und die Bewohner von Gebim* rennen davon.", footnotes: ["Madmena ... Gebim. Unbekannte Orte."] },
      { number: 32, text: "Noch heute macht er Halt in Nob* / und streckt seine Hand nach dem Hügel Jerusalems aus, / nach dem Berg, der den Einwohnern Zions gehört.", footnotes: ["Nob. Die Stadt lag wahrscheinlich 2,5 km nordöstlich von Jerusalem."] },
      { number: 33, text: "Seht, wie Jahwe, der allmächtige Gott, mit schrecklicher Gewalt die Äste abhaut. / Die mächtigen Bäume werden gefällt, / alles Hohe wird niedrig gemacht." },
      { number: 34, text: "Das Gestrüpp des Waldes wird mit Eisen zerfetzt, / und die Pracht des Libanon fällt." },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Aus Isais Stumpf* wächst ein Spross, / aus seinen Wurzeln schießt ein neuer Trieb.", heading: "Das Reich des Messias", footnotes: ["Isais Stumpf. Isai war der Vater von König David. Gemeint ist also ein Nachkomme Davids."] },
      { number: 2, text: "Auf ihm wird ruhen der Geist Jahwes, / der Geist der Weisheit und des Verstands, / der Geist des Rates und der Kraft, / der Erkenntnis und der Ehrfurcht vor Jahwe." },
      { number: 3, text: "Jahwe zu fürchten ist ihm eine Lust.Er urteilt nicht nach Augenschein, / verlässt sich nicht auf das, was er hört," },
      { number: 4, text: "sondern richtet auch die Geringen gerecht / und hilft den Gebeugten zu ihrem Recht. / Seine Befehle halten das Land in Zucht, / der Hauch seines Mundes bringt den Gesetzlosen um." },
      { number: 5, text: "Sein Hüftschurz heißt Gerechtigkeit. / Und Wahrheit ist der Gurt, der seine Lenden umschließt." },
      { number: 6, text: "Dann ist der Wolf beim Lamm zu Gast, / und neben dem Böckchen liegt ein Leopard. / Kalb und Löwenjunges wachsen miteinander auf; / ein kleiner Junge hütet sie." },
      { number: 7, text: "Kuh und Bärin teilen eine Weide, / und ihre Jungen legen sich zusammen hin. / Und der Löwe frisst Stroh wie das Rind." },
      { number: 8, text: "Der Säugling spielt am Schlupfloch der Schlange, / in die Höhle der Otter steckt das Kleinkind die Hand." },
      { number: 9, text: "Auf dem ganzen heiligen Berg wird niemand Böses tun, / niemand stiftet Unheil, richtet Schaden an. / Und wie das Wasser den Meeresgrund bedeckt, / so ist das Land von der Erkenntnis Jahwes erfüllt." },
      { number: 10, text: "An dem Tag wird es Isais Wurzelspross sein, / der als Zeichen für alle Völker dasteht; / dann kommen sie und suchen Rat bei ihm. / Sein Palast ist voller Herrlichkeit.*", footnotes: ["Wird im Neuen Testament von Paulus nach der LXX zitiert: Römer 15,12."] },
      { number: 11, text: "Wenn diese Zeit gekommen ist, / erhebt der Herr noch einmal die Hand. / Dann wird er den Rest seines Volkes befreien, von Assyrien und Ägypten, / von Nubien* und vom Oberlauf des Nil, / von Elam*, Schinar* und Hamat* / und von jedem Küstenland*.", footnotes: ["Nubien. Hebräisch: Kusch. Land am Oberlauf des Nil, südlich von Ägypten.", "Elam. Persische Provinz um die Hauptstadt Susa.", "Schinar. Babylonien", "Hamat. Heute: Labwe, etwa 70 km nördlich vom Berg Hermon.", "Küstenland. Gemeint sind die Inseln und Küstenländer des Mittelmeers."] },
      { number: 12, text: "Er stellt diesen Völkern ein Feldzeichen auf / und sammelt Israels Verstoßene ein. Die Versprengten Judas holt er vom Ende der Welt." },
      { number: 13, text: "Dann verfliegt die Eifersucht auf Efraïm, / dann ist die Feindschaft Judas vorbei. / Efraïm wird gegen Juda nicht mehr eifersüchtig sein, / und auch Juda bedrängt Efraïm nicht mehr." },
      { number: 14, text: "Gemeinsam stürmen sie die Hänge hinab / nach Westen gegen die Philister. / Und im Osten plündern sie die Wüstenstämme aus. / Edom* und Moab* sind in ihrer Hand, / und die Ammoniter* werden ihnen hörig sein.", footnotes: ["Edom. Land östlich der Araba im Süden des Toten Meeres, bewohnt von den Nachkommen Esaus.", "Die Moabiter lebten östlich des Toten Meeres zwischen den Flüssen Arnon und Zered.", "Die Ammoniter waren nordöstliche Nachbarn der Moabiter."] },
      { number: 15, text: "Jahwe teilte den Golf am ägyptischen Meer* / und droht nun dem Euphrat mit seiner Hand. / Er zerreißt ihn in sieben Rinnsale durch seine Glut, / dass man zu Fuß hindurchgehen kann.", footnotes: ["... ägyptischen Meer. Das ist offenbar eine Anspielung auf den Durchzug Israels durch das Schilfmeer, siehe 2. Mose 14,21-31."] },
      { number: 16, text: "So entsteht eine Straße für den Rest seines Volkes, / der in Assyrien überlebt hat, / wie es damals eine Straße gab, / als Israel Ägypten verließ." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Dann wirst du sagen: \"Ich preise dich, Jahwe! / Du warst zornig auf mich, / doch nun hat dein Zorn sich gelegt, und ich empfange deinen Trost." },
      { number: 2, text: "Seht den Gott meines Heils! / Ich habe Vertrauen und fürchte mich nicht, / denn Jahwe ist meine Stärke, / Jah* ist meine Freiheit und mein Lied!\"", footnotes: ["Jah. Kurzform von Jahwe."] },
      { number: 3, text: "Voller Freude sollt ihr Wasser schöpfen, / Wasser aus den Quellen des Heils." },
      { number: 4, text: "An dem Tag werdet ihr sagen: \"Preist Jahwe! / Ruft seinen Namen aus! / Macht unter den Völkern sein Wirken bekannt! / Sagt ihnen, wie unvergleichlich groß er ist!" },
      { number: 5, text: "Singt und spielt zur Ehre Jahwes, / denn er hat Gewaltiges getan! / Erfahren möge es die ganze Welt!" },
      { number: 6, text: "Jauchze und juble, du Zionsstadt, / denn der Heilige Israels wohnt in dir!\"" },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Wort, das auf Babylon lastet, und das Jesaja Ben-Amoz offenbart wurde:", heading: "Gott wird die Völker richten (13-27)\nGottes Wort lastet auf Babylon" },
      { number: 2, text: "Auf dem kahlen Berg stellt ein Feldzeichen auf, / erhebt die Stimme, ruft sie herbei, / winkt mit der Hand! / Durch die Tore der hohen Herren ziehen sie ein." },
      { number: 3, text: "Ich selbst rief meine Heiligen zum Kampf, / sie jubeln über meine Hoheit und Macht." },
      { number: 4, text: "Hört ihr das Dröhnen auf den Bergen, / Getöse wie von einer großen Menge? / Horch! Ganze Königreiche kommen heran, / viele Nationen versammeln sich. / Jahwe, der allmächtige Gott, mustert sein Heer." },
      { number: 5, text: "Aus fernen Ländern kommen sie, / von dort wo der Himmel die Erde berührt. / Es ist Jahwe mit den Waffen seines Zorns, / um zugrunde zu richten das ganze große Reich." },
      { number: 6, text: "Schreit vor Angst, denn Jahwes Tag ist nah! / Der Allmächtige holt zum Vernichtungsschlag aus." },
      { number: 7, text: "Da werden alle Hände schlaff, / und jeden verlässt der Mut." },
      { number: 8, text: "Vor Schrecken sind sie ganz verstört, / von Krämpfen und Wehen gepackt. / Sie winden sich wie eine gebärende Frau. / Einer starrt den anderen an, / wie Feuer glüht ihr Gesicht." },
      { number: 9, text: "Seht, es kommt der Gerichtstag Jahwes, / ein grausamer Tag, voll Wut und Zorn. / Er macht die Erde zu einer Wüste / und vernichtet alle Sünder darin." },
      { number: 10, text: "Die Sterne am Himmel funkeln nicht mehr, / vergeblich sucht man den Orion, / die Sternbilder haben kein Licht. / Die Sonne wird schon im Aufgang finster, / und der Mond gibt kein Licht in der Nacht." },
      { number: 11, text: "Für ihre Bosheit strafe ich die ganze Welt, / ihre Schuld zahle ich allen Gottlosen heim. / Die Arroganz der Stolzen löse ich auf, / und den Hochmut der Herrscher erniedrige ich." },
      { number: 12, text: "Einen Mann lasse ich seltener werden als gediegenes Gold, / ein Mensch wird kostbarer als Ofir-Gold* sein.", footnotes: ["Ofir-Gold. Josephus, LXX und Vulgata (Hiob 28,16) verstanden unter Ofir Indien. Dafür spricht, dass es alle in der Bibel erwähnten Güter (Gold, Silber, Edelsteine, Hölzer, Elfenbein, Affen und Pfauen) im alten Indien gab. Ferner ist bekannt, dass vom 2. Jt. v.Chr. an lebhafter Handel zwischen dem Persischen Golf und Indien getrieben wurde. Dazu waren Hochseeschiffe (1. Könige 22,49: Tarschisch-Schiffe) nötig. Eine andere Theorie besagt, dass Ofir eine Stadt war, die vermutlich an der südwestlichen Küste Arabiens oder 75 km nördlich von Bombay (Supura) lag."] },
      { number: 13, text: "Ich werde den Himmel erzittern lassen, / die Erde wird beben vom Grimm Jahwes / an dem Tag, an dem der Allmächtige zürnt." },
      { number: 14, text: "Sie werden wie aufgescheuchte Gazellen sein, / wie eine Herde, die kein Hirt zusammenhält. / Jeder flieht zu seinem Volk, / eilt in sein Heimatland zurück." },
      { number: 15, text: "Es wird jeder erstochen, den man erwischt; / wen man packt, den trifft das Schwert." },
      { number: 16, text: "Sie müssen es mit eigenen Augen sehen, / wie man ihre Kinder zerschmettert, / ihre Häuser plündert / und ihre Frauen schändet." },
      { number: 17, text: "\"Ja, die Meder* lasse ich auf sie los, / die das Geld nicht achten, / die man nicht mit Gold bestechen kann.", footnotes: ["Die Meder, die im Nordwesten des Iran lebten, eroberten 612 v.Chr. zusammen mit den Babyloniern die assyrische Hauptstadt Ninive und 539 v.Chr. zusammen mit den Persern Babylon. Aber sie waren auch schon in den viel früheren Konflikt verwickelt, der im Jahr 689 v.Chr., also 12 Jahre nach der Weissagung Jesajas, zur Eroberung Babylons durch die Assyrer führte."] },
      { number: 18, text: "Ihre Pfeile strecken junge Männer nieder, / mit Kindern machen sie kurzen Prozess / und selbst Säuglinge verschonen sie nicht." },
      { number: 19, text: "Wie es Sodom und Gomorra erging, / den Städten, die Gott zerstörte, / so wird es auch mit Babylon sein, / dem Juwel von Königreichen, / dem Schmuckstück der stolzen Chaldäer*.", footnotes: ["Chaldäer. Bewohner von Süd-Babylonien, später wurden alle Babylonier Chaldäer genannt."] },
      { number: 20, text: "Es bleibt auf Dauer unbewohnt, / unbesiedelt für alle Zeit. / Kein Nomade schlägt dort seine Zelte auf, / kein Hirt lässt seine Schafe dort ruhen." },
      { number: 21, text: "Nur Wüstenspuk gibt es an diesem Ort / und Häuser voller Eulen. / Strauße wird man dort finden, / und Dämonen führen ihre Tänze auf." },
      { number: 22, text: "Hyänen heulen in verlassenen Palästen / und Schakale in den Schlössern der Lust. / Die Tage der Stadt sind gezählt, / bald schlägt die letzte Stunde von Babylon." },
    ] },
    { number: 14, verses: [
      { number: 1, text: "Denn Jahwe wird sich über die Nachkommen Jakobs erbarmen. Er wird Israel noch einmal erwählen und in sein Land zurückbringen. Fremde werden sich ihnen dabei anschließen und dann zum Volk Israel gehören.", heading: "Das Spottlied auf den König von Babel" },
      { number: 2, text: "Die Völker werden Israel nehmen und in seine Heimat zurückbringen. Und dort, im Land Jahwes, werden die Israeliten sie zu Sklaven und Sklavinnen machen. Sie werden die gefangen nehmen, die einst sie in die Gefangenschaft führten, und ihre ehemaligen Unterdrücker unterdrücken." },
      { number: 3, text: "Und wenn Jahwe dir dann Ruhe gewährt von aller Qual und Unruhe und dem harten Sklavendienst," },
      { number: 4, text: "wirst du ein Spottlied auf den König von Babel singen:\"Ach, der Unterdrücker nahm ein Ende! / Mit seiner Schreckensherrschaft ist es aus!" },
      { number: 5, text: "Zersplittern ließ Jahwe den Knüppel der Bösen, / zerbrach den Stock der Tyrannen," },
      { number: 6, text: "der die Völker schlug in blinder Wut / und ihnen grausame Schläge versetzte, / der sie in wildem Zorn unterdrückte / und sie hetzte ohne Erbarmen." },
      { number: 7, text: "Nun ruht und rastet die ganze Erde. / Jubel bricht aus!" },
      { number: 8, text: "Selbst die Zypressen freuen sich mit, / auch die Zedern auf dem Libanon: / 'Seit du gefallen bist und unten liegst, / kommt kein Fäller mehr zu uns herauf.'" },
      { number: 9, text: "Die ganze Totenwelt ist aufgeregt / und bereit, dich zu empfangen. / Für dich wurden Totengeister aufgestört, / die Mächtigen aus einer früheren Welt. / Man schreckt die Könige der Völker hoch, / alle springen von den Stühlen auf." },
      { number: 10, text: "Der Chor der Schatten ruft dir zu: / 'Nun bist du genauso wie wir, / schwach und ohne Macht.'" },
      { number: 11, text: "Ins Totenreich gestürzt ist deine Pracht / und deine rauschende Harfenmusik. / Maden bekommst du als Bett und / mit Würmern deckst du dich zu." },
      { number: 12, text: "Ach wie bist du vom Himmel gefallen, funkelnder Morgenstern*, / zu Boden geschmettert, Eroberer der Welt!", footnotes: ["Morgenstern. Die lateinische Bibel (Vulgata) hat diesen Ausdruck mit Luzifer = \"Lichtbringer\" übersetzt. Von daher wurden die Verse 12-15 in Verbindung mit Lukas 10,18 oft auf den Fall Satans gedeutet. Direkt spricht der Abschnitt aber – wie die Verse vorher und nachher – vom Fall des Königs von Babylon."] },
      { number: 13, text: "Du, du hattest in deinem Herzen gedacht: / 'Ich will zum Himmel hochsteigen! / Höher als die göttlichen Sterne stelle ich meinen Thron! / Im äußersten Norden setze ich mich hin, / dort auf den Versammlungsberg*!", footnotes: ["Versammlungsberg. Gemeint ist wohl der Berg Zaphon, der 40 km nordöstlich von Ugarit in Syrien lag. Die Kanaaniter dachten sich dort die Ratsversammlung der Götter (wie die Griechen auf dem Berg Olymp)."] },
      { number: 14, text: "Über die Wolken will ich hinauf, / dem Allerhöchsten gleichgestellt sein!'" },
      { number: 15, text: "Doch ins Reich der Grüfte musst du hinab, / wirst auf den Grund der Totenwelt gestürzt." },
      { number: 16, text: "Wer dich einst gesehen hat, / betrachtet dich nun, / schaut dich nachdenklich an: 'Ist das der Mann, der die Erde zittern ließ, / der Königreiche aus den Angeln hob?'" },
      { number: 17, text: "Er machte Städte dem Erdboden gleich / und verwüstete die ganze Welt. / Wen er gefangen nahm, der kehrte nie zurück." },
      { number: 18, text: "Alle Herrscher setzt man prächtig bei, / in Ehren ruhen sie in ihrer Gruft." },
      { number: 19, text: "Doch du liegst ohne Grab auf freiem Feld, / hingeworfen wie ein dürrer Zweig, / zertrampelt wie ein totes Tier, / mit Leichen von Erschlagenen bedeckt." },
      { number: 20, text: "Dich bettet man nicht in die steinerne Gruft, / mit denen dort wirst du niemals vereint. / Denn dein Land hast du zerstört, / hingemordet dein eigenes Volk. / Dein Verbrechergeschlecht soll in Ewigkeit vergessen sein!" },
      { number: 21, text: "Bringt seine Söhne her und schlachtet sie ab! / Denn auf ihren Vätern lastete Schuld. / Nie wieder dürfen sie an die Macht, / nie sei die Welt in ihrem Besitz / und der Erdkreis mit ihren Städten gefüllt.\"" },
      { number: 22, text: "\"Ich werde mich gegen sie stellen!\", / sagt Jahwe, der allmächtige Gott. / \"Mit Kind und Kindeskind rotte ich Babylon aus, / mit Stumpf und Stiel!", heading: "Die völlige Vernichtung Babylons" },
      { number: 23, text: "Zum Besitz der Igel mache ich es, / und zu einem Sumpfgebiet. / Ich kehre es mit eisernem Besen aus\", / sagt Jahwe, der allmächtige Gott." },
      { number: 24, text: "Jahwe, der allmächtige Gott, hat es geschworen: / \"Wie ich es mir vornahm, so wird es geschehen, / es wird so kommen, wie ich es beschloss.", heading: "Gegen Assyrien" },
      { number: 25, text: "Assyriens Macht zerbreche ich in meinem Land, / auf meinen Bergen zertrete ich sie. / Dann weicht ihr Joch von meinem Volk, / von seinem Nacken fällt es ab.\"" },
      { number: 26, text: "Das ist Gottes Beschluss über die ganze Welt, / und das ist die Hand, die gegen alle Völker ausgestreckt ist." },
      { number: 27, text: "Denn Jahwe, der allmächtige Gott, setzte es fest. / Wer kann ihn daran hindern? / Seine Hand ist drohend ausgestreckt. / Wer wendet sie wieder zurück?" },
      { number: 28, text: "Im Todesjahr von König Ahas* / kam dieses belastende Wort:", heading: "Gegen die Philister", footnotes: ["Todesjahr von König Ahas. 716 v.Chr. Zu dieser Zeit war Hiskia bereits 13 Jahre lang Mitregent in Juda."] },
      { number: 29, text: "\"Freue dich nicht zu früh, Philisterland! / Zwar ist der Stock zerbrochen, der dich schlug, / doch aus der toten Schlange fährt eine Natter heraus, / und aus der Natter kommt ein fliegender Drache." },
      { number: 30, text: "Auf meiner Wiese weiden die Schwachen, / dort leben die Armen in Sicherheit. / Doch deine Wurzel wird durch Hunger zerstört, / und der Drache bringt den Rest von dir um." },
      { number: 31, text: "Heult auf, ihr Tore! / Schrei um Hilfe, du Stadt! / Verzage, ganz Philisterland! / Eine Rauchwolke kommt von Norden heran. / Es ist ein gewaltiges, geschlossenes Heer." },
      { number: 32, text: "Was für eine Antwort gibt man den Boten der Philisterstämme? / \"Jahwe hat die Grundmauern Zions gelegt. / Dort finden die Armen seines Volkes sicheren Schutz!\"" },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Das Wort, das auf Moab* lasten wird:Ar-Moab* ist zerstört, / vernichtet in einer Nacht. / Auch Kir-Moab* ist zerstört, / verwüstet in einer Nacht.", heading: "Gegen Moab", footnotes: ["Moab. Die Moabiter lebten östlich des Toten Meeres zwischen den Flüssen Arnon und Zered. Sie waren über Lot (1. Mose 19,36-37) mit Israel verwandt. Auch die Urgroßmutter Davids war eine Moabiterin, siehe Rut 4,17; 1. Samuel 22,3-4.", "Ar-Moab. Stadt in Moab, Lage unbekannt.", "Kir-Moab. Identisch mit Kir-Heres, siehe Jesaja 16,7.11. Die bedeutende moabitische Stadt lag 16 km östlich vom südlichen Teil des Toten Meeres."] },
      { number: 2, text: "Die Moabiter steigen zu ihrem Tempel hinauf, / die Einwohner Dibons* weinen auf den Opferhöhen. / Moab klagt über Medeba* und Nebo*. / Auf allen Köpfen eine Glatze, / abgeschoren jeder Bart.", footnotes: ["Dibon. Bedeutende Stadt Moabs, heute Dhiban, 21 km östlich vom Toten Meer, 5 km nördlich der Arnon-Schlucht.", "Medeba. Im heutigen Jordanien, 32 km südlich von Amman.", "Nebo. Heute: Ajun Musa, 15 km östlich vom Nordende des Toten Meeres."] },
      { number: 3, text: "Auf den Gassen laufen sie im Trauersack, / auf Dächern und Plätzen jammert das Volk. / Sie lassen ihren Tränen freien Lauf." },
      { number: 4, text: "Heschbon* und Elale* schreien um Hilfe, / dass man ihre Stimmen noch in Jahaz* hört. / Auch Moabs Krieger schreien laut, / ihrer Seele geht es schlecht.", footnotes: ["Heschbon. 19 km südwestlich von Amman. Die Hauptstadt der Amoriter war von den Moabitern erobert worden.", "Elale. Dorf, 18 km südwestlich von Amman.", "Jahaz. Stadt nördlich des Arnontals."] },
      { number: 5, text: "Und auch mein Herz schreit um Hilfe für dieses Volk.Sie fliehen bis nach Zoar / und nach Eglat-Schelischija*. / Weinend schleppen sich Menschen den Aufstieg nach Luhit hoch, / auf dem Weg nach Horonajim* erheben sie erschütterndes Geschrei.", footnotes: ["Zoar ... Schelischija. Städte südlich bzw. südöstlich des Toten Meeres.", "Luhit ... Horonajim. Ortslagen unbekannt, wahrscheinlich südöstlich vom Süd-Ende des Toten Meeres."] },
      { number: 6, text: "Verschüttet sind die Quellen von Nimrim*, / alles Gras ist verdorrt. / Das Kraut ist verwelkt, / kein Grün ist mehr da.", footnotes: ["Nimrim. Wahrscheinlich eine Oase südöstlich vom Toten Meer."] },
      { number: 7, text: "Was sie noch haben, tragen sie bei sich, / und gehen über den Pappelbach*.", footnotes: ["Pappelbach. Wadi (Trockental, das nur in der Regenzeit Wasser führt) südlich oder südöstlich vom Toten Meer."] },
      { number: 8, text: "An allen Grenzen Moabs hört man Wehgeschrei. / Man hört es bis nach Eglajim, / bis Beer-Elim* dringt sein Klageschrei.", footnotes: ["Eglajim ... Beer-Elim. Offenbar Städte an den Grenzen Moabs."] },
      { number: 9, text: "\"Dimons* Wasser ist schon voller Blut, / doch ich bringe noch mehr Unheil über die Stadt: / Auf die letzten Moabiter im Land, / auf die Überlebenden lasse ich die Löwen los.\"", footnotes: ["Dimon. Vermutlich ein Wortspiel mit Dibon (Vers 2) und Blut (Hebr. dam)."] },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Schickt von Moabs Felsennest* / Schafböcke durch die Wüste – zum Landesherrscher auf dem Zionsberg*", footnotes: ["Felsennest. Hebräisch: Sela. Hier wohl nicht als Ortsname gebraucht.", "... Zionsberg. Die Moabiter sollten wieder ihren Tribut zahlen."] },
      { number: 2, text: "und sagt ihm: / \"Wie herumflatternde Vögel, / wie ein aufgescheuchtes Nest / irren Moabs Frauen an den Furten des Arnon umher." },
      { number: 3, text: "Gib Rat und triff eine Entscheidung für uns! / Mach deinen Schatten wie das Dunkel der Nacht / und verbirg die Vertriebenen, / verrate die Flüchtlinge nicht!" },
      { number: 4, text: "Gib denen, die aus Moab fliehen, / Gastrecht bei dir! / Verstecke sie vor dem wüsten Verfolger!\" / Wenn der Peiniger beseitigt ist, / wenn die Zerstörung aufgehört hat, / die Verwüster aus dem Land verschwunden sind," },
      { number: 5, text: "dann wird ein Thron der Gnade aufgerichtet sein. / Auf ihm, am Wohnsitz Davids, / wird in Wahrheit einer sitzen, / der das Recht sucht / und in Gerechtigkeit erfahren ist." },
      { number: 6, text: "Wir haben vom Hochmut Moabs gehört, / wie überheblich, stolz und vermessen es ist. / Doch sein Prahlen ist leeres Geschwätz." },
      { number: 7, text: "Darum wird Moab sein Schicksal beklagen, / heulen werden sie allesamt. / Kir-Heres' Rosinenkuchen weinen sie nach, / und seufzen tiefbetrübt." },
      { number: 8, text: "Heschbons Terassen sind verwelkt, / verdorrt sind die Weinstöcke von Sibma*, / deren Wein die Starken der Völker schwach gemacht hat. / Bis nach Jaser* reichten ihre Ranken, / bis in die Wüste verliefen sie sich, / überschritten selbst das Tote Meer.", footnotes: ["Sibma. Vielleicht 5 km westlich von Heschbon.", "Jaser. Vielleicht 10 km westlich von Amman."] },
      { number: 9, text: "Darum weine ich mit den Leuten von Jaser um die Weinstöcke Sibmas, / mit meinen Tränen tränke ich euch, Heschbon und Elale. / Denn über Weinlese und allen Ertrag / ist ein Jauchzen der Feinde gefallen." },
      { number: 10, text: "Aus allen Gärten weggerafft sind Freude und Gesang. / In den Weinbergen hört man keinen Jubel mehr. / Niemand stampft mehr Trauben in der Kelter aus, / alle fröhlichen Rufe sind verstummt." },
      { number: 11, text: "Um Moab klagt mein Innerstes, / über Kir-Heres erzittert mein Herz." },
      { number: 12, text: "Selbst wenn Moab sich um Opfer müht, / zum Gebet in sein Heiligtum hochsteigt, / es nützt ihm nichts." },
      { number: 13, text: "Diese Worte hat Jahwe einst über Moab gesagt." },
      { number: 14, text: "Doch jetzt spricht Jahwe so: \"In drei Jahren, die ihr wie ein Tagelöhner zählen werdet, wird man über den Ruhm Moabs nur noch verächtlich lachen. Von seiner zahlreichen Menge wird nur noch ein winziger, ohnmächtiger Rest übrig sein.\"" },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Das Wort, das auf Damaskus lasten wird: / Die Stadt Damaskus gibt es bald nicht mehr, / dann ist sie nur ein Haufen Schutt.", heading: "Gegen Damaskus" },
      { number: 2, text: "Verlassen wird Aroer* samt Umgebung sein. / In aller Ruhe lagern Herden dort / und niemand jagt sie weg.", footnotes: ["Aroer. Stadt am Arnonfluss, 23 km östlich vom Toten Meer. Südlichste Grenze des Einflussgebiets von Syrien."] },
      { number: 3, text: "Aus ist's mit dem Bollwerk Efraïms* / mit dem Damaskus-Königtum. / Und was von Syrien übrig bleibt, / ist nicht mehr, als das von Israel. / Das sagt Jahwe, der allmächtige Gott.", footnotes: ["Bollwerk Efraïms. Spielt auf die Allianz des Nordreiches Israel (Efraïm) mit Syrien an."] },
      { number: 4, text: "An diesem Tag schrumpft Jakobs* Pracht erbärmlich ein, / das Fett seines Leibes schwindet dahin.", footnotes: ["Jakob. Israels Stammvater, steht hier für das ganze Volk."] },
      { number: 5, text: "Es wird wie bei einem Schnitter sein, / der die Halme zusammenrafft / und mit der Sichel die Ähren abmäht. / Es wird sein, wie beim Ährenlesen in der Ebene von Refaïm*.", footnotes: ["Refaïm. Fruchtbares Gebiet westlich von Jerusalem."] },
      { number: 6, text: "Nur eine Nachlese bleibt ihm zurück, / wie beim Abklopfen der Frucht vom Olivenbaum. / Zwei, drei Oliven oben am Ast, / vier, fünf in seinem Gezweig, / sagt Jahwe, Israels Gott." },
      { number: 7, text: "An dem Tag denkt der Mensch wieder an seinen Schöpfer, / richtet seinen Blick auf den Heiligen Israels," },
      { number: 8, text: "schaut nicht mehr auf die eigenen Altäre, / achtet nicht auf das Machwerk der eigenen Hand, / blickt geweihte Pfähle und Sonnensäulen nicht mehr an." },
      { number: 9, text: "An dem Tag sind seine befestigten Städte wie verlassene Orte im Wald, / sind öde wie die Berggipfel damals bei der Ankunft Israels." },
      { number: 10, text: "Ja, du hast vergessen den Gott deines Heils, / hast nicht mehr an deine Fluchtburg gedacht. / Stattdessen legst du Gärtchen für den \"Lieblichen\"* an / und setzt fremde Reben hinein.", footnotes: ["den \"Lieblichen\". Wahrscheinlich der Frühlingsgott Adonis, der in Syrien und Phönizien verehrt wurde."] },
      { number: 11, text: "Kaum hast du sie gepflanzt, schießen sie hoch, / was du morgens gesät hast, sprießt noch am selben Tag. / Aber es wird dir nur Schmerzen bringen, / Krankheiten, gegen die es keine Heilung gibt." },
      { number: 12, text: "Weh! Viele Völker brausen heran: ein Tosen wie das rauschende Meer. / Man hört das Toben der Nationen wie das Tosen einer gewaltigen Flut." },
      { number: 13, text: "Sie donnern heran wie wütende Wogen, / doch von Gott bedroht, weichen sie weit zurück. / Wie Spreu auf den Bergen, davongeblasen vom Wind, / wie Raddisteln*, weggewirbelt vom Sturm.", footnotes: ["Raddistel. Vertrocknete und vom Wind verwirbelte Teile der Gundelia (ein Taumelkraut), die als große Bälle weit durch die Steppe getrieben werden konnten."] },
      { number: 14, text: "Am Abend waren sie noch jähes Entsetzen, / am Morgen schon gibt es sie nicht mehr! / Ja, unsere Räuber bekommen solchen Lohn, / und die uns plündern erhalten dieses Los." },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Weh dem Land des Flügelgeschwirrs, / das jenseits der Ströme Nubiens liegt,", heading: "Gegen Nubien" },
      { number: 2, text: "das Boten in Papyrusbooten übers Wasser schickt, den Strom* hinab. / Kehrt zurück, ihr schnellen Boten, / zu dem glänzenden*, hochgewachsenen Volk, / das weit und breit gefürchtet ist, / das mit angespannter Kraft alles zertritt, / zurück zu dem von Strömen durchfurchten Land.", footnotes: ["den Strom. Wörtlich: das Meer. Im Altertum Bezeichnung für große Ströme, hier ist der Nil gemeint.", "glänzenden. Meint vielleicht die mit Öl eingeriebene Haut der Nubier."] },
      { number: 3, text: "Ihr Bewohner der Erde, ihr Bürger der Welt, / seht hin, wenn auf den Bergen ein Feldzeichen steht, / hört hin, wenn ins Horn gestoßen wird!" },
      { number: 4, text: "Denn so sagte Jahwe zu mir: / \"Von meiner Wohnung aus schaue ich untätig zu, / ruhig wie die flimmernde Mittagsglut, / wie eine Dunstwolke am heißen Erntetag." },
      { number: 5, text: "Denn noch vor der Ernte, / wenn die Blüte abfällt / und der Blütenstand zur reifenden Traube wird, / schneidet man mit dem Rebmesser die Ranken weg, / reißt die Triebe ab und wirft sie fort." },
      { number: 6, text: "Sie werden alle auf den Bergen liegen, / den Raubvögeln und Hyänen zum Fraß. / Den Sommer über sitzen die Raubvögel darauf, / und im Winter fressen die wilden Tiere daran.\"" },
      { number: 7, text: "Dann wird Jahwe, dem allmächtigen Gott, ein Geschenk dargebracht / von einem glänzenden, hochgewachsenen Volk, / das weit und breit gefürchtet ist, / das mit angespannter Kraft alles zertritt, / dessen Land von Strömen durchschnitten wird. / Sie werden zu der Stätte kommen, wo der Name Jahwes wohnt, zum Zionsberg." },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Das Wort, das auf Ägypten lasten wird: / Seht, auf schneller Wolke fährt Jahwe / und kommt bald in Ägypten an. / Ägyptens Götzen zittern vor ihm, / und die Ägypter vergehen vor Angst.", heading: "Gegen Ägypten" },
      { number: 2, text: "\"Ich stachele Ägypter gegen Ägypter auf, / dass Bruder gegen Bruder kämpft, / Freund gegen Freund, / Stadt gegen Stadt / und Land gegen Land." },
      { number: 3, text: "Ägyptens Mut wird ausgehöhlt, / und ich trübe ihre geistige Klarheit. / Dann suchen sie bei Götzen Rat, / bei Zauberern und Wahrsagern und den Geistern von Toten." },
      { number: 4, text: "Ich gebe sie einem harten Herrn in die Hand, / einem grausamen König, der über sie herrscht\", / spricht Jahwe, der allmächtige Gott." },
      { number: 5, text: "Die Wasser des Nils* werden versiegen, / der Strom versandet, trocknet aus.", footnotes: ["Wasser des Nils. Wörtlich: im Meer. Siehe Fußnote zu Jesaja 18,2."] },
      { number: 6, text: "Seine Arme fangen an zu stinken, / die Kanäle von Unterägypten werden leer, / Rohr und Schilf sind schwarz." },
      { number: 7, text: "Das Ried am Fluss, an der Mündung des Nil, / das Saatland an den Ufern trocknet aus, zerstiebt, / und der Wind weht es weg." },
      { number: 8, text: "Da klagen die Fischer, / da trauern die Angler / und jeder, der ein Netz auswerfen will." },
      { number: 9, text: "Die, die Flachs verarbeiten, sind verzweifelt, / und die Leinenweber werden bleich." },
      { number: 10, text: "Das Fundament ihrer Existenz ist zerstört, / und die Lohnarbeiter verlieren den Mut." },
      { number: 11, text: "Nichts als Narren sind die Fürsten von Zoan*! / Pharaos weiseste Räte geben Dummheit von sich. / \"Söhne von Weisen sind wir!\", sagen sie ihm. / \"Wir stammen von alten Königen ab!\"", footnotes: ["Zoan ist wahrscheinlich mit Tanis identisch, das im nordöstlichen Teil des Nildeltas liegt."] },
      { number: 12, text: "Wo sind denn nun deine Weisen, Pharao? / Können sie dir nicht sagen, was Jahwe, der allmächtige Gott, / über Ägypten beschlossen hat?" },
      { number: 13, text: "Die Fürsten von Zoan sind dumm, / und die von Memphis* geben sich Täuschungen hin. / Die Stammesfürsten haben Ägypten ins Taumeln gebracht.", footnotes: ["Zoan und Memphis (Hebr.: Nof) waren die beiden alten Hauptstädte Ägyptens."] },
      { number: 14, text: "Jahwe hat einen Geist des Schwindels für ihr Inneres gemischt, / sodass sie Ägypten ins Stolpern bringen, / bei allem, was es tut, / dass es wie ein Betrunkener in seinem Erbrochenen tappt." },
      { number: 15, text: "Ägypten wird keine Tat mehr gelingen, / die Kopf oder Schwanz, / Palmzweig oder Binse* vollbringen.", footnotes: ["Kopf ... Binse. Synonyme für hoch- und niedriggestellte Menschen, siehe Jesaja 9,13."] },
      { number: 16, text: "Zu der Zeit werden die Ägypter wie ängstliche Frauen sein. Sie werden zittern und beben, wenn Jahwe, der allmächtige Gott, seine Hand über sie schwingt.", heading: "Ägyptens Bekehrung" },
      { number: 17, text: "Sie werden schreckliche Angst vor dem Land Juda haben. Allein der Name Judas wird die Ägypter zum Zittern bringen. Sie fürchten sich vor dem, was Jahwe, der allmächtige Gott, gegen sie beschlossen hat." },
      { number: 18, text: "In dieser Zeit werden fünf ägyptische Städte Hebräisch* sprechen. Eine davon wird Ir-Heres* heißen.", footnotes: ["Hebräisch. Wörtlich: die Sprache Kanaans. Entweder ein symbolischer Bezug auf die Treue zu Jahwe oder ein Hinweis darauf, dass diese Städte von Juden bewohnt sein werden.", "Ir-Heres. Stadt der Zerstörung. Das scheint ein Wortspiel zu sein, denn durch Änderung eines Buchstabens ergibt sich im Hebräischen \"Sonnenstadt\". Das wiederum könnte ein Hinweis auf Heliopolis sein, das von Nebukadnezzar zerstört wurde, siehe Jesaja 43,12-13."] },
      { number: 19, text: "Dann wird es mitten in Ägypten einen Altar für Jahwe* geben, und an der Grenze wird ein Steinmal ihm zu Ehren stehen.", footnotes: ["Altar für Jahwe. Um 170 v.Chr. wurde bei Leontopolis von dem Hohen Priester Onias IV. ein Jahwetempel gebaut, der sich dabei auf diese Weissagung berief."] },
      { number: 20, text: "Das wird die Ägypter ständig an Jahwe, den allmächtigen Gott, erinnern, besonders, wenn sie unterdrückt werden und dann zu Jahwe schreien. Dann wird er einen Retter zu ihnen schicken, der für sie kämpft und sie befreit." },
      { number: 21, text: "So wird sich Jahwe den Ägyptern zu erkennen geben, und auch sie werden sehen, wer er ist. Sie werden ihm Schlacht- und Speisopfer bringen und sich immer an das halten, was sie ihm feierlich geloben." },
      { number: 22, text: "Jahwe wird die Ägypter zwar schlagen, aber ihnen wieder aufhelfen. Sie werden zu ihm umkehren, und er wird ihre Gebete erhören und sie heilen." },
      { number: 23, text: "Zu der Zeit wird es eine Straße von Ägypten nach Assyrien geben. Die Völker werden sich gegenseitig besuchen und gemeinsam Jahwe dienen." },
      { number: 24, text: "Dann wird Israel der Dritte im Bund sein und – zusammen mit Assyrien und Ägypten – ein Segen für die ganze Erde." },
      { number: 25, text: "Denn Jahwe, der allmächtige Gott, wird sie segnen mit den Worten: \"Gesegnet sei mein Volk Ägypten! Gesegnet sei Assyrien, das Werk meiner Hände! Gesegnet sei Israel, mein Eigentum!\"" },
    ] },
    { number: 20, verses: [
      { number: 1, text: "Es geschah in dem Jahr, in dem der assyrische König Sargon* den Tartan, seinen obersten Feldherrn, nach Aschdod* schickte, und dieser es belagerte und eroberte.*", heading: "Die Krise um Aschdod", footnotes: ["Sargon II. regierte von 721-705 v.Chr.", "Aschdod. Philisterstadt am Mittelmeer.", "eroberte. Das geschah im Jahr 711 v.Chr. Schon 713 v.Chr. hatte die Stadt im Vertrauen auf Ägypten und Nubien gegen Assyrien rebelliert und wollte auch Juda mit hineinziehen."] },
      { number: 2, text: "Jahwe hatte zu Jesaja Ben-Amoz gesagt*: \"Zieh deinen Trauersack und deine Sandalen aus!\" Er tat es und ging nur mit einem Lendenschurz bekleidet barfuß umher.", footnotes: ["hatte ... gesagt. Das war bereits drei Jahre vorher, siehe Vers 3."] },
      { number: 3, text: "Nun sagte Jahwe: Drei Jahre lang ist mein Diener Jesaja barfuß und im Lendenschurz herumgelaufen. Als lebendes Zeichen sollte er zeigen, was Ägypten und Nubien treffen wird." },
      { number: 4, text: "Der assyrische König wird die Ägypter und Nubier gefangen wegtreiben, nackt und barfuß, ja sogar mit entblößtem Gesäß. Was für eine Schande für die Ägypter!" },
      { number: 5, text: "Und alle, die von Nubien Hilfe erwarteten und so große Stücke auf Ägypten hielten, werden enttäuscht und entmutigt sein." },
      { number: 6, text: "Und die Bewohner dieses Küstenstreifens hier werden dann sagen: \"Sie waren unsere Hoffnung gewesen! Zu ihnen sind wir um Schutz und Hilfe gelaufen! Sie sollten uns vor dem assyrischen König retten! Wo gibt es jetzt noch Rettung für uns?\"" },
    ] },
    { number: 21, verses: [
      { number: 1, text: "Das Wort, das über der Wüste am Meer lasten wird: / Wie ein Sturm, der über den Negev* fegt, / kommt das Unheil aus der Wüste, / einem schrecklichen Land.", heading: "Die Verwüstung Babylons", footnotes: ["Negev. Das heiße Südland Israels, zum Teil gebirgige Wüste."] },
      { number: 2, text: "Furchtbare Dinge wurden mir gezeigt: / \"Der Verräter verrät, und der Zerstörer zerstört. / Brecht auf, ihr Elamiter*! / Ihr Meder*, belagert die Stadt! / Mit allem Seufzen über sie mache ich Schluss.\"", footnotes: ["Elamiter. Land und Volk östlich von Babylon, Hauptstadt Susa.", "Meder. Iranischer Stamm, der das medisch-persische Hochland bewohnte."] },
      { number: 3, text: "Darum zittert mein Körper, / von Krämpfen gepackt, / von Wehen geschüttelt wie eine gebärende Frau. / Von dem, was ich höre, bin ich betäubt, / bestürzt von dem, was ich sehen muss." },
      { number: 4, text: "Mein Herz rast, ein Schauder schüttelt mich. / Die mir so liebe Dämmerstunde hat es mir zum Grauen gemacht." },
      { number: 5, text: "Man deckt den Tisch, / legt die Polster zurecht; / man isst und trinkt. / \"Steht auf, Offiziere! / Ölt eure Schilde* ein!\"", footnotes: ["Die Schilde waren mit Leder überzogen."] },
      { number: 6, text: "Denn das hat der Herr mir gesagt: / \"Geh und stell einen Wachtposten auf. / Er soll dir melden, was er sieht." },
      { number: 7, text: "Sieht er einen Wagenzug, / ein Pferdegespann, / einen Zug Kamele oder Esel, / dann passe er auf! / Er passe ganz scharf auf!\"" },
      { number: 8, text: "Da rief der Wächter:* / \"Herr, den ganzen Tag steh ich bereit, / bin auf dem Posten jede Nacht!", footnotes: ["Wächter. So mit der LXX und den Qumrantexten. Die meisten hebräischen Handschriften haben: \"Da rief er, ein Löwe.\""] },
      { number: 9, text: "Da, was sehe ich? / Ein Zug von Männern, ein Pferdegespann! / Und einer von ihnen ruft: / 'Gefallen! Gefallen ist Babylon! / Alle Bilder seiner Götter sind zerstört!'\"" },
      { number: 10, text: "Du, mein zerschlagenes, zerdroschenes Volk! / Ich verkünde euch das, was ich höre – von Jahwe, dem allmächtigen Gott." },
      { number: 11, text: "Das Wort, das auf Duma* lasten wird: / Aus Seïr ruft man mir zu: / \"Wächter, wie lange noch dauert die Nacht? / Wächter, wie lange noch dauert die Nacht?\"", heading: "Gegen Duma und Arabien", footnotes: ["Duma. Hebräisch: Totenstille. Es gibt eine Oase dieses Namens östlich des Berglandes von Seïr (Edom)."] },
      { number: 12, text: "Der Wächter spricht: / \"Der Morgen kommt, / aber noch ist es Nacht! / Wenn ihr fragen wollt, / kommt wieder und fragt!\"" },
      { number: 13, text: "Das Wort, das auf Arabien lasten wird: / In der Steppe müsst ihr übernachten, / Männer, Karawanen von Dedan*.", footnotes: ["Dedan. Wahrscheinlich eine Wegstation auf der Weihrauchroute von Südarabien nach Syrien. Es kann auch einen arabischen Stamm meinen."] },
      { number: 14, text: "Bringt dem Durstigen Wasser hin, / Bewohner des Landes von Tema*, / geht dem Flüchtling entgegen mit Brot!", footnotes: ["Tema. Wüstenoase 400 km südöstlich von Elat in Saudi-Arabien."] },
      { number: 15, text: "Denn sie sind vor den Schwertern geflohen, / vor dem Ansturm des Krieges, / dem gezückten Schwert und dem gespannten Bogen." },
      { number: 16, text: "Denn das hat der Herr mir gesagt: \"In noch einem Jahr, das euch wie ein Tagelöhnerjahr erscheinen wird, ist es mit Kedars* Herrlichkeit vorbei.", footnotes: ["Kedar. Nomadenstamm in der syrisch-arabischen Wüste, bekannt durch seine Herden."] },
      { number: 17, text: "Von seinen berühmten Bogenschützen bleiben nur ganz wenige am Leben, spricht Jahwe, der Gott Israels.\"" },
    ] },
    { number: 22, verses: [
      { number: 1, text: "Das Wort, das auf dem Tal der Offenbarung* lasten wird: / Was ist mit dir, dass du auf den Dachterrassen stehst,", heading: "Gegen Jerusalem", footnotes: ["Tal der Offenbarung. Gemeint ist Jerusalem und seine unmittelbare Umgebung."] },
      { number: 2, text: "du lärmerfüllte tosende Stadt, / du fröhliche Burg? / Deine Toten fielen nicht durchs Schwert und nicht im Kampf." },
      { number: 3, text: "Alle deine Führer sind geflohen, / und alle sind gefangen – ohne einen Bogenschuss. So weit sie auch gelaufen waren, / nun sind sie gefesselt – allesamt." },
      { number: 4, text: "Darum sage ich: \"Lasst mich allein mit meinem Schmerz! / Lasst meine Tränen laufen! / Tröstet mich nicht wegen der Gewalt an meinem Volk!" },
      { number: 5, text: "Denn der Herr hat Verwirrung, Verheerung, Verstörung in das Tal der Offenbarung gebracht – Jahwe, der allmächtige Gott. / Die Mauer wird bestürmt – und bricht. / Hilfegeschrei hört man am Hang." },
      { number: 6, text: "Elam* hat den Köcher umgehängt, / die Streitwagen sind bespannt und bemannt, / und Kir* hat seinen Schild enthüllt.", footnotes: ["Elam. Persische Provinz um die Hauptstadt Susa.", "Kir. Ort in Mesopotamien, Identität unbekannt."] },
      { number: 7, text: "Deine herrlichen Täler sind mit Wagen gefüllt, / und Reiter nehmen Stellung gegen das Tor." },
      { number: 8, text: "So nimmt man Juda jeden Schutz. / An dem Tag habt ihr im Waldhaus* nach Waffen gesucht", footnotes: ["Waldhaus. Halle am königlichen Palast, von Salomo mit Zedern aus dem Libanon gebaut."] },
      { number: 9, text: "und habt die Risse in der Mauer gesehen, / viele Risse in der Davidsstadt.* / Im unteren Teich habt ihr das Wasser gestaut.", footnotes: ["Die Davidsstadt umfasste das Gebiet des alten Jebus, das von David erobert worden war. Es bildete den Kern Jerusalems."] },
      { number: 10, text: "Dann habt ihr Jerusalems Häuser gezählt, / ganze Gebäude niedergerissen / und die Mauer der Stadt damit fester gemacht." },
      { number: 11, text: "Zwischen den beiden Mauern habt ihr ein Sammelbecken angelegt – für das Wasser des alten Teichs.Doch habt ihr nicht auf den geblickt, der alles bewirkt; / ihr habt nicht an den gedacht, der solche Unglücke plant." },
      { number: 12, text: "Wohl rief der Herr an jenem Tag. / Jahwe, der allmächtige Gott, rief euch zum Weinen und zur Wehklage auf, / zum Glatzescheren und zum Trauersack." },
      { number: 13, text: "Doch er fand Jubel und Vergnügen bei euch, / Ochsenschlachten und Schafeschächten, / Fleischessen und Weintrinken. / \"Lasst uns essen und trinken\", habt ihr gesagt, / \"denn morgen sind wir tot!\"*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: 1. Korinther 15,32."] },
      { number: 14, text: "Doch Jahwe, der allmächtige Gott, hat sich mir offenbart: / \"Diese Schuld vergebe ich euch nicht, bis ihr sterbt!, / schwört Jahwe, der allmächtige Gott.\"" },
      { number: 15, text: "So sprach der Herr, Jahwe, der allmächtige Gott: Geh zu diesem Verwalter da, zu Schebna, dem Palastvorsteher, und sage ihm:", heading: "Schebna und Eljakim" },
      { number: 16, text: "\"Was machst du hier eigentlich? Wer gab dir die Erlaubnis, hier oben eine Grabkammer aushauen zu lassen? Was fällt dir ein, deine letzte Wohnung in den Fels zu meißeln?" },
      { number: 17, text: "Pass auf, Mann! Jahwe wird dich im Wind herumwirbeln und dich zusammenkneten," },
      { number: 18, text: "er wird dich zu einem Knäuel zusammenwickeln und wie einen Ball wegschleudern in ein Land mit großen weiten Ebenen. Dort wirst du sterben, und dorthin kommen auch die Wagen deiner Ehrsucht, du Schandfleck für das Königshaus!" },
      { number: 19, text: "Ich werde dich aus deinem Amt verjagen und dafür sorgen, dass man dich von deinem hohen Posten holt." },
      { number: 20, text: "An dem Tag werde ich Eljakim Ben-Hilkija berufen, meinen Diener." },
      { number: 21, text: "Ich ziehe ihm dein Amtsgewand an und lege ihm deinen Gürtel um. Ich übertrage ihm alle Vollmachten, die du jetzt hast. Er wird wie ein Vater für die Bewohner Jerusalems und das Volk von Juda sein." },
      { number: 22, text: "Ich vertraue ihm die Schlüssel zum Palast der Nachkommen Davids an. Was er öffnet, wird kein anderer verschließen, und was er verschließt, wird keiner mehr öffnen." },
      { number: 23, text: "Ich werde ihn wie einen Pflock fest in die Wand einschlagen. Seine ganze Verwandtschaft wird durch ihn zu Ehren kommen." },
      { number: 24, text: "Doch die ganze Sippe wird sich mit Kind und Kegel an ihn hängen, wie an einen Pflock, an dem das ganze Tongeschirr mit Schüsseln und Krügen hängt." },
      { number: 25, text: "Dann wird der Pflock, der so fest in der Wand sitzt, abbrechen, und die Last, die er trug, geht zu Bruch, sagt Jahwe, der allmächtige Gott.\"" },
    ] },
    { number: 23, verses: [
      { number: 1, text: "Das Wort, das auf Tyrus* lasten wird: / Heult, ihr Handelsschiffe*, denn euer Hafen ist zerstört! / Als ihr von Zypern kamt, habt ihr davon gehört.", heading: "Gegen Tyrus", footnotes: ["Tyrus und Sidon (Vers 2) waren die wichtigsten Hafenstädte Phöniziens (heute: Libanon).", "Handelsschiffe. Wörtlich: Tarschisch-Schiffe, d.h. Hochseeschiffe, die bis nach Tarschisch fahren konnten (siehe Fußnote zu 1. Könige 10,22)."] },
      { number: 2, text: "Werdet stumm, ihr Küstenbewohner, / ihr Händler von Sidon. / Eure Aufkäufer überquerten das Meer" },
      { number: 3, text: "und führten Korn aus Ägypten ein. / Die Saat am Nil und die Ernte am Strom brachten euch den Gewinn." },
      { number: 4, text: "Schäm dich, Sidon, und du, Festung am Meer! / Nun sagt euch das Meer: \"Es ist, als hätte ich nie geboren, / als hätte ich niemals Wehen gehabt! / Zog ich denn niemals Kinder groß?\"*", footnotes: ["... Kinder groß. Selbst das Meer hat seine Kinder verloren, wenn die Handelsschiffe ausbleiben."] },
      { number: 5, text: "Sobald die Nachricht nach Ägypten kommt, werden sie sich winden, / wie es einst bei der von Tyrus geschah." },
      { number: 6, text: "Fahrt doch nach Tarschisch* hinüber! / Heult, ihr Küstenbewohner!", footnotes: ["Tarschisch. Ort in Spanien (siehe Fußnote zu 1. Könige 10,22)."] },
      { number: 7, text: "Ist das eure fröhliche, brausende Stadt, / gegründet in uralter Zeit, / die ihre Siedler in die Ferne schickt?" },
      { number: 8, text: "Wer hat das Unheil gegen dieses Tyrus geplant, / das Königskronen spendete, / dessen Kaufleute Fürsten waren / und dessen Händler die Vornehmsten der Welt?" },
      { number: 9, text: "Es beschloss Jahwe, der allmächtige Gott, / um zu entweihen die prunkende Pracht, / zu erniedrigen die Großen der Welt." },
      { number: 10, text: "Bewässert euer Land wie die Bauern am Nil, / ihr Kinder von Tarschisch! / Denn es gibt keine Werft mehr bei euch." },
      { number: 11, text: "Jahwe hat seine Hand über das Meer ausgestreckt und Königreiche erschreckt. / Er erließ den Befehl, Phöniziens Burgen niederzureißen." },
      { number: 12, text: "Er sagte: \"Nie mehr sollst du fröhlich sein, / Sidon*, du vergewaltigte junge Frau! / Auch wenn ihr nach Zypern flieht, / findet ihr dort keine Sicherheit.", footnotes: ["Sidon. Im 7. Jh. v.Chr. wurde die Stadt von Esarhaddon erobert, 587 v.Chr. von Nebukadnezzar."] },
      { number: 13, text: "Das ist ja ein Chaldäerland, / jenes Volk, das damals noch nicht war. / Nun hat Assyrien es für seine Schiffe bestimmt. / Sie haben Belagerungstürme gebaut, / die Burgen zerstört und zu Trümmerhaufen gemacht." },
      { number: 14, text: "Heult, ihr Schiffe von Tarschisch, / denn euer Hafen wurde zerstört." },
      { number: 15, text: "Es kommt eine Zeit, wo Tyrus siebzig Jahre lang – so lange wie ein König lebt – vergessen sein wird. Und nach diesen siebzig Jahren wird es Tyrus ergehen, wie der Hure im Lied:" },
      { number: 16, text: "Nimm die Laute, / durchstreife die Stadt, / du vergessene Hure! / Spiel, so gut du kannst! / Singe Lied um Lied, / damit man wieder an dich denkt!" },
      { number: 17, text: "Wenn die siebzig Jahre vorbei sind, wird Jahwe sich wieder um Tyrus kümmern. Die Stadt wird ihr altes Geschäft wieder aufnehmen und sich an alle Königreiche der Welt verkaufen." },
      { number: 18, text: "Aber ihr Handelsgewinn und Hurenlohn wird dann Jahwe gehören. Er wird nicht angesammelt und gehortet werden, sondern denen zugutekommen, die in der Nähe Jahwes wohnen, damit sie reichlich zu essen haben und Prachtgewänder tragen können." },
    ] },
    { number: 24, verses: [
      { number: 1, text: "Jahwe verwüstet die Erde und fegt sie leer, / er entstellt ihr Gesicht und zerstreut die Bewohner.", heading: "Gottes Gericht über die Erde" },
      { number: 2, text: "Dann geht es dem Priester wie dem Volk, / dem Sklaven wie dem Herrn, / der Magd wie der Gebieterin, / dem Käufer wie dem Verkäufer, / dem Borger wie dem Leiher, / dem Schuldner wie dem Gläubiger." },
      { number: 3, text: "Die Erde wird völlig leer und ausgeplündert sein, / denn Jahwe hat das Urteil gefällt." },
      { number: 4, text: "Die Erde verfällt und verfault, / der Weltkreis verwelkt, / und auch die Mächtigen gehen ein." },
      { number: 5, text: "Entweiht liegt die Erde unter ihren Bewohnern, / denn sie haben Gottes Gesetz übertreten, / seine Ordnungen missachtet und den ewigen Bund ungültig gemacht." },
      { number: 6, text: "Darum hat der Fluch die Erde versehrt, / und die Bewohner büßen für ihre Schuld. / Sie schwinden dahin, von Glut verzehrt. / Von den Menschen bleibt nur ein winziger Rest." },
      { number: 7, text: "Es vertrocknet der Most, der Weinstock verwelkt, / und die einst so Fröhlichen seufzen jetzt." },
      { number: 8, text: "Der Freudenklang der Tamburine verstummt, / der Lärm der feiernden Menge erstirbt, / das fröhliche Harfenspiel bricht ab." },
      { number: 9, text: "Man trinkt keinen Wein mehr bei frohem Gesang, / bitter schmeckt den Zechern ihr Bier." },
      { number: 10, text: "Zertrümmert ist die öde Stadt, / verschlossen und verrammelt jedes Haus." },
      { number: 11, text: "Man wimmert um Wein auf den Gassen. / Die Freude ist untergegangen, / aller Jubel im Land ist verbannt." },
      { number: 12, text: "Öde ist der Rest der Stadt, / das Tor ist nur ein Haufen Schutt." },
      { number: 13, text: "So wird es unter den Völkern der Erde geschehen. / Es wird wie beim Abschlagen von Oliven sein, / wie bei der Nachlese im Weinberg, / wenn die Ernte dann vorüber ist." },
      { number: 14, text: "Sie beginnen zu jubeln, / sie preisen die Größe Jahwes. / Über das Meer im Westen jauchzen sie ihm zu." },
      { number: 15, text: "\"Ehrt auch im Osten den Namen Jahwes, / und an den Meeresküsten lobt Jahwe, Israels Gott!\"" },
      { number: 16, text: "Vom Ende der Erde hören wir Gesang: / \"Gebt ihm die Ehre, er hat für das Recht gesorgt!\"Ich aber schreie: \"Mir ist elend, ich vergehe! / Wehe mir, ich kann nicht mehr!\" / Treulose kennen keine Treue! / Nur noch Treuebruch, Veruntreuung und Treulosigkeit!" },
      { number: 17, text: "Grauen und Furcht, Fallgrube und Fangnetz erwarten die Bewohner der Welt." },
      { number: 18, text: "Wer vor den Schreckensschreien flieht, fällt in die Grube, / und wer sich aus der Grube retten kann, verfängt sich im Netz. / Die Schleusen des Himmels öffnen sich, / es erschüttert die Fundamente der Welt." },
      { number: 19, text: "Berstend reißt die Erde auf, / sie bricht und zerbricht, / sie wankt und schwankt," },
      { number: 20, text: "sie taumelt wie ein Betrunkener, / schaukelt wie eine Nachthütte im Feld, / denn ihr Frevel wuchtet schwer auf ihr. / Sie fällt und steht nicht wieder auf." },
      { number: 21, text: "An dem Tag zieht Jahwe zur Rechenschaft / die Geistesmächte der unsichtbaren Welt / und die irdischen Herrscher der Erde." },
      { number: 22, text: "Sie werden zusammengetrieben und in die Grube gesperrt. / Sie werden ins Gefängnis gebracht und nach langer Zeit erst bestraft." },
      { number: 23, text: "Da wird der Mond ganz rot vor Scham / und die Sonne vor Schande bleich, / denn Jahwe, der allmächtige Gott, herrscht als König – auf dem Zionsberg und in Jerusalem. / Und seinen Führern zeigt er seine Herrlichkeit." },
    ] },
    { number: 25, verses: [
      { number: 1, text: "Jahwe, du bist mein Gott! / Dich will ich erheben und deinen Namen preisen! / Denn du hast Wunder vollbracht nach deinem Beschluss, / der schon lange gefasst und nun in wahrhaftiger Treue ausgeführt ist.", heading: "Gottes Friedensreich" },
      { number: 2, text: "Die Stadt hast du zum Steinhaufen gemacht, / die starke Burg zu einem Trümmerfeld. / Die Paläste der Fremden bewohnt keiner mehr. / Die Stadt wird niemals wieder aufgebaut." },
      { number: 3, text: "Nun ehrt dich ein mächtiges Volk, / die Städte gewalttätiger Stämme fürchten dich." },
      { number: 4, text: "Denn du bist die Festung des Schwachen, / die Zuflucht des Armen in seiner Not, / ein Schutzdach vor dem Wolkenbruch, / ein Schatten vor der Sonnenglut, / wenn die Wut der Tyrannen wie ein Wetter gegen eine Mauer tobt" },
      { number: 5, text: "und wie glühende Hitze den ausgedörrten Boden verbrennt. / Du hast ihr Toben zum Schweigen gebracht. / Wie der Schatten einer Wolke die Hitze dämpft, / so dämpftest du ihr Siegesgeschrei." },
      { number: 6, text: "Hier auf dem Zionsberg wird es geschehen: / Jahwe, der allmächtige Gott, wird alle Völker zum Fest einladen, / zu einem Mahl mit feinsten Speisen und einem guten Tropfen, / mit kräftigen, köstlichen Gerichten / und gut gelagertem alten Wein." },
      { number: 7, text: "Hier wird er den Schleier zerreißen, der allen Völkern das Gesicht verhüllt, / die Decke entfernen, die auf den Nationen liegt." },
      { number: 8, text: "Den Tod wird er für immer verschlingen / und Jahwe, der Herr, wischt die Tränen von jedem Gesicht,* / und entfernt die Schmach seines Volkes von der Welt. / Das hat Jahwe zugesagt.", footnotes: ["Wird im Neuen Testament von Paulus und Johannes zitiert: 1. Korinther 15,54; Offenbarung 7,17."] },
      { number: 9, text: "An dem Tag wird man sagen: / \"Da ist unser Gott! Auf ihn hatten wir unsere Hoffnung gesetzt. / Das ist Jahwe! Wir haben nicht vergeblich gehofft. / Jubeln wir! Freuen wir uns, denn er hat uns die Rettung gebracht!\"" },
      { number: 10, text: "Jahwes Hand schützt diesen Berg, / doch Moab wird zertreten im eigenen Land, / so wie man Stroh in der Jauche zertritt." },
      { number: 11, text: "Und rudert er mit seinen Armen darin / wie ein Schwimmer, der sich zu retten versucht, / wird sein Hochmut dennoch niedergedrückt, / auch wenn er sich geschickt dagegen wehrt." },
      { number: 12, text: "Deine hohen, steilen Mauern reißt er ab / und macht alle dem Erdboden gleich." },
    ] },
    { number: 26, verses: [
      { number: 1, text: "Dann singt man in Juda dieses Lied: / \"Wir haben eine starke Stadt, / denn Wall und Mauer gab er uns zum Schutz.", heading: "Lobgesang der Erlösten" },
      { number: 2, text: "Macht die Tore auf, damit ein Volk einzieht, das gottrecht lebt, / das ihm die Treue hält" },
      { number: 3, text: "und sich durch nichts beirren lässt. / Frieden, ja Frieden gibst du dem, der dir vertraut." },
      { number: 4, text: "Jahwe soll man immer vertrauen! / Denn Jahwe, Gott*, ist ein ewiger Fels!", footnotes: ["Jahwe, Gott. Eigentlich: Jah (=Kurzform von Jahwe), Jahwe."] },
      { number: 5, text: "Die in stolzer Höhe wohnten, hat er niedergeduckt, / die hochragende Burg hat er gänzlich zerstört, / er hat sie niedergestoßen bis in den Staub." },
      { number: 6, text: "Nun soll sie zertreten der Fuß: / die Füße der Armen, die Tritte von Menschen ohne Macht.\"" },
      { number: 7, text: "Wer gottrecht lebt, hat einen geraden Weg; / dem, der dir gehorcht, ebnest du die Bahn." },
      { number: 8, text: "Selbst wenn du uns strafen musst, / warten wir voll Hoffnung auf dich, Jahwe. / Wir sehnen uns nach dir, nach deinem Namen, deinem Lob." },
      { number: 9, text: "Bei Nacht sind meine Gedanken bei dir, / voller Sehnsucht suche ich dich. / Wenn du deine Gerichte auf der Erde vollstreckst, / lernen die Menschen, was Gerechtigkeit ist." },
      { number: 10, text: "Doch wenn ein Gottloser begnadigt wird, / lernt er nie Gerechtigkeit. / Selbst in diesem Land, wo dein Recht gilt, / handelt er verkehrt und sieht nicht die Hoheit Jahwes." },
      { number: 11, text: "Auch deine hocherhobene Hand nehmen sie nicht wahr. / Doch deinen Eifer um dein Volk werden sie sehen, Jahwe! / Und das Feuer, das deinen Feinden gilt, verzehre auch sie!" },
      { number: 12, text: "Du wirst uns Frieden geben, Jahwe, / denn du hast ja alle unsere Taten für uns vollbracht." },
      { number: 13, text: "Außer dir haben auch andere Herren über uns geherrscht, Jahwe. / Nur durch dich haben wir an deinen Namen gedacht." },
      { number: 14, text: "Tote werden nicht lebendig, / Totengeister stehen nicht wieder auf. / Deshalb hast du sie ja heimgesucht und beseitigt / und jeden Gedanken an sie zunichte gemacht." },
      { number: 15, text: "Du hast dein Volk vermehrt, Jahwe, / hast dein Volk groß gemacht und seine Grenzen weit. / Du hast deine Herrlichkeit gezeigt." },
      { number: 16, text: "In der Not haben sie dich gesucht, Jahwe, / und als du straftest, kamen sie klagend zu dir." },
      { number: 17, text: "Wie eine schwangere Frau kurz vor der Geburt, / wie sie sich windet und in Schmerzen schreit, / so waren wir vor dir, Jahwe." },
      { number: 18, text: "Wir waren schwanger, wanden uns in Schmerzen und gebaren Wind. / Rettung konnten wir dem Land nicht bringen / und keinen Bewohner für die Welt." },
      { number: 19, text: "Doch deine Toten werden leben, / die Leichen meines Volkes werden auferstehen! / Wacht auf und jubelt, Bewohner des Staubs! / Du, Herr, bist wie ein belebender Tau; / darum gibt die Erde die Toten heraus." },
      { number: 20, text: "Geh, mein Volk, in deine Kammer und schließ die Tür hinter dir zu! / Verbirg dich einen Augenblick, bis das Strafgericht vorüber ist." },
      { number: 21, text: "Denn schon tritt Jahwe aus seiner Wohnung heraus, / um für ihre Schuld zu bestrafen die Bewohner der Welt. / Dann deckt die Erde das Blut wieder auf / und verbirgt die Ermordeten nicht mehr." },
    ] },
    { number: 27, verses: [
      { number: 1, text: "An dem Tag wird Jahwe / durch sein hartes, großes, starkes Schwert / abrechnen mit dem Leviatan*, / der flüchtigen gewundenen Schlange, / dem Ungeheuer im Meer.", footnotes: ["Leviatan. Verkörperung gottfeindlicher Mächte, besonders Ägypten."] },
      { number: 2, text: "An dem Tag singt ihm das Lied vom wundervollen Weinberg zu:", heading: "Ein Volk für Gott" },
      { number: 3, text: "\"Ich, Jahwe, behüte ihn, / begieße ihn zu jeder Zeit, / bewache ihn bei Tag und Nacht, / dass niemand sich an ihm vergreift." },
      { number: 4, text: "Mein Zorn auf ihn ist verraucht. / Doch finde ich Dornen und Disteln darin, / gibt's einen schonungslosen Krieg: / Sie werden ausgerissen und verbrannt." },
      { number: 5, text: "So geht es dem, der nicht Schutz bei mir sucht / und Frieden mit mir macht, / ja, Frieden mit mir schließt." },
      { number: 6, text: "Jakob wird noch Wurzeln schlagen, / Israel wird blühen und gedeihen / und mit Früchten erfüllen die ganze Welt." },
      { number: 7, text: "Hat der Herr sein Volk geschlagen, wie er ihre Schläger schlug? / Hat er von ihnen so viel umgebracht, wie er das bei ihren Mördern tat?" },
      { number: 8, text: "Mit Maßen, durch Verbannung hast du es bestraft! / Sein heftiger Atem trieb sie fort am Tag, als der Sturm von Osten kam." },
      { number: 9, text: "Dadurch wird Jakobs Schuld gesühnt. / Und weil seine Sünde beseitigt ist,* / macht er die Götzenaltäre zerschlagenen Kalksteinen gleich. / Aschera-Pfähle* werden verschwunden sein, / und Räucheraltäre nirgends mehr stehen.", footnotes: ["Wird im Neuen Testament von Paulus zusammen mit Jesaja 59,20-21 zitiert: Römer 11,26-27.", "Die Aschera war eine Fruchtbarkeitsgöttin, die in geweihten Pfählen verehrt wurde."] },
      { number: 10, text: "Leer ist dann die befestigte Stadt, / ein verlassener Ort, / einsam wie die Steppe. / Kälber weiden dort, / lagern sich und fressen ihre Büsche kahl." },
      { number: 11, text: "Wenn dann die Zweige dürr geworden sind, / brechen Frauen sie ab und heizen damit. / Es ist ein unverständiges Volk, / deshalb hat sein Schöpfer kein Erbarmen mit ihm. / Er, der es gebildet hat, begnadigt es nicht." },
      { number: 12, text: "Doch es kommt eine Zeit, in der Jahwe die Ähren ausklopfen wird – vom Bach Ägyptens* bis zum Euphratstrom. / Da wird man euch zusammenlesen, / ihr Israeliten!", footnotes: ["Bach Ägyptens. Nach Josua 15,4 war er die Grenze zwischen Israel und Ägypten. Heute: Wadi El-Arisch."] },
      { number: 13, text: "An dem Tag dröhnt das große Horn*. / Dann kommen die Verirrten aus Assyrien heim, / und die in Ägypten Verstreuten kehren zurück. / Dann beten sie Jahwe in Jerusalem auf dem heiligen Berg an.", footnotes: ["Das große Horn (Hebräisch: Schofar) war aus den gewundenen Hörnern des männlichen Fettschwanzschafes hergestellt und brachte einen dumpfen, durchdringenden Ton hervor."] },
    ] },
    { number: 28, verses: [
      { number: 1, text: "Weh der stolzen Krone der Betrunkenen, / dem welkenden Kranz seiner herrlichen Pracht, / der Hauptstadt über dem fetten Tal*, / dem Stolz aller Weinseligen von Efraïm.", heading: "Nur Gott kann euch retten (28-35)\nDie Herausforderung der Spötter", footnotes: ["Hauptstadt ... Tal. Gemeint ist wahrscheinlich die Stadt Samaria, die auf einem Hügel lag."] },
      { number: 2, text: "Schon hält der Herr einen Starken und Mächtigen bereit. / Er kommt wie ein Hagelwetter, / wie ein verheerender Sturm, / wie ein Wolkenbruch mit mächtiger Wasserflut, / der alles mit Wucht zu Boden reißt." },
      { number: 3, text: "Zertrampeln wird er die stolze Krone der Betrunkenen von Efraïm." },
      { number: 4, text: "Der welkenden Blüte seiner prächtigen Zier, / der Hauptstadt über dem fetten Tal wird es gehen / wie der frühen Feige vor der Ernte: / Der erste, der sie erblickt, pflückt sie schnell ab und verschlingt sie sofort." },
      { number: 5, text: "An dem Tag wird Jahwe, der allmächtige Gott, zu einer herrlichen Krone für den Rest seines Volks / und zu einem prachtvollen Kranz." },
      { number: 6, text: "Er wird zum Geist des Rechts für den, der zu Gericht sitzen muss, / und zur Heldenkraft für den, der den Feind aus der Stadt vertreibt." },
      { number: 7, text: "Doch auch diese hier schwanken, berauscht vom Wein, / und taumeln, benebelt vom Bier: / Priester und Propheten sind betrunken, / schwanken vom Bier und sind benebelt vom Wein. / Sie torkeln, wenn sie weissagen, und taumeln im Gericht." },
      { number: 8, text: "Ihre Tische sind von Erbrochenem voll, / alles ist besudelt, kein Platz ist mehr frei davon." },
      { number: 9, text: "Und dann sagen sie: \"Wem will der denn Einblick geben? / Wem will der erzählen, was Gott will? / Sind wir denn kleine Kinder, / eben von der Mutterbrust entwöhnt?" },
      { number: 10, text: "Was soll das Zaw-la-zaw, zaw-la-zaw / und kaw-la-kaw, kaw-la-kaw*, / hier ein wenig, dort ein wenig?\"", footnotes: ["... kaw-la-kaw. Die Betrunkenen ahmen spöttisch Jesajas Rede nach. Der Sinn ist unklar, vielleicht mit M. Buber: Spurgrad in der Spur, schnurgrad an der Schnur."] },
      { number: 11, text: "Ja, durch Menschen mit stammelnden Lippen und fremden Sprachen / sagt Gott sein Wort zu diesem Volk." },
      { number: 12, text: "Er hatte zu ihnen gesagt: \"So findet ihr Ruhe. / Gönnt doch den Müden die Rast! / Ich biete euch Sicherheit!\" / Aber sie wollten nicht hören.*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: 1. Korinther 14,21."] },
      { number: 13, text: "Darum wird Jahwe sie hören lassen: / \"Zaw-la-zaw, zaw-la-zaw / und kaw-la-kaw, kaw-la-kaw, / hier ein wenig, dort ein wenig.\" / Nach hinten stürzen sie und brechen sich das Genick. / Sie laufen den Feinden ins Netz, / gefangen führt man sie fort." },
      { number: 14, text: "Darum hört das Wort Jahwes, ihr Lästermäuler, / ihr Herrscher von Jerusalem!" },
      { number: 15, text: "Ihr prahlt, mit dem Tod im Bund zu sein. / Ihr habt mit dem Totenreich einen Vertrag? / Ihr glaubt, wenn die Katastrophe kommt, geht sie an euch vorbei, / denn ihr hättet Lügen zu eurer Zuflucht gemacht, / euch abgesichert durch Betrug?" },
      { number: 16, text: "Darum spricht der Herr Jahwe: Seht her, ich habe auf dem Zionsberg ein festes Fundament gelegt: / ein erprobter Block, ein kostbarer Eckstein, ein felsenfester Grund. / Wer ihm vertraut, hält ebenso stand*.", footnotes: ["Wird im Neuen Testament von Paulus zusammen mit Jesaja 8,14 zitiert: Römer 9,33; und allein von Paulus in Römer 10,11 und von Petrus in 1. Petrus 2,6."] },
      { number: 17, text: "Als Richtschnur nehme ich das Recht / und als Waage die Gerechtigkeit. / Der Hagelsturm fegt eure Lügenzuflucht weg, / und Wasser überflutet das Versteck." },
      { number: 18, text: "Euer Bündnis mit dem Tod ist dann gelöst, / und mit dem Totenreich ist der Vertrag gelöscht. / Und wenn die Katastrophe wie eine Flut über euch kommt, / seid ihr nur noch zertretenes Land." },
      { number: 19, text: "Sooft sie heranbraust, reißt sie euch mit, / und Morgen für Morgen tobt sie heran. / Selbst in der Nacht habt ihr keine Ruhe mehr. / Und jedes Prophetenwort wird euch eine Schreckensnachricht sein." },
      { number: 20, text: "Ja, \"das Bett ist zu kurz, um sich auszustrecken / und die Decke zu schmal, um sich einzuwickeln.\"" },
      { number: 21, text: "Denn Jahwe wird sich erheben wie am Berg Perazim, / er wird toben wie im Tal von Gibeon*. / Doch was er tut, wird euch befremden, / sein Werk wird euch unheimlich sein.", footnotes: ["Perazim ... Gibeon. In beiden Schlachten stand Gott auf der Seite Israels, siehe 2. Samuel 5,20; Josua 10,10. Jetzt aber wird es umgekehrt sein."] },
      { number: 22, text: "Darum lasst jetzt euren Spott, damit man eure Fesseln nicht noch fester zieht! / Denn ich habe von Jahwe, dem allmächtigen Gott, / vom Herrn der ganzen Erde, ein \"Zunichte!\" gehört / und ein \"Entschieden!\"" },
      { number: 23, text: "Horcht auf und hört meine Stimme! / Gebt acht und hört auf mein Wort!" },
      { number: 24, text: "Pflügt der Bauer denn den ganzen Tag zur Vorbereitung auf die Saat? / Eggt er denn jeden Tag sein Ackerland?" },
      { number: 25, text: "Nein, wenn er die Äcker geebnet hat, streut er Dill und Kümmel aus, / sät Weizen, Hirse, Gerste auf sein Feld und Dinkel an den Rand." },
      { number: 26, text: "So unterwies ihn sein Gott, / belehrte ihn, wie er vorgehen soll." },
      { number: 27, text: "Dill drischt man nicht mit Dreschschlitten* aus, / und das Wagenrad wird nicht über Kümmel gerollt. / Dill wird mit dem Stab geklopft / und Kümmel mit dem Stock.", footnotes: ["Ein Dreschschlitten bestand aus zwei oder mehreren miteinander verbundenen vorn aufgebogenen Brettern, unter denen meist noch spitze Steine oder Eisenmesser befestigt waren, um die Körner herauszulösen und die Halme zu zerschneiden. Sie wurden von Tieren im Kreis über das auf der Tenne ausgebreitete Getreide gezogen."] },
      { number: 28, text: "Auch das Brotkorn wird nicht zermalmt, / nicht dauernd drischt der Drescher darauf ein. / Er sorgt, dass weder Wagenräder darüber rollen, / noch Pferdehufe es zerstampfen." },
      { number: 29, text: "Auch das weiß er von Jahwe, dem allmächtigen Gott. / Gottes Pläne sind zum Staunen, / er führt sie immer zum Erfolg." },
    ] },
    { number: 29, verses: [
      { number: 1, text: "Weh dir Ariël, du Gottesherd*, / du Stadt, die David einst belagert hat. / Fügt nur Jahr an Jahr und feiert Fest um Fest!", heading: "Letzte Gnadenfrist für \"Ariël\"", footnotes: ["Gottesherd. Nach Hesekiel 43,15 ist damit der obere Teil des Brandopferaltars gemeint, der Herd, in dem die Glut lag. Hier steht es für Jerusalem als Gottes eigener Herd und Altar."] },
      { number: 2, text: "Ich werde Ariël bedrängen, dass es Stöhnen und Wehgeschrei gibt / und es mir wie ein Gottesherd* wird.", footnotes: ["wie ein Gottesherd. Voll mit Erschlagenen, wie die Opfertiere auf dem Altar, wie ein Holocaust, ein Ganzopfer im Feuer."] },
      { number: 3, text: "Ich umlagere dich in engem Ring, / ich schließe dich ein mit einem Wall / und umstelle dich mit Belagerungsgeschütz." },
      { number: 4, text: "Dann wirst du auf dem Boden liegen / und reden in den Staub gebeugt, / dass deine Stimme dumpf erklingt. / Wie eine Geisterstimme aus der Totenwelt / wispert deine Rede aus dem Staub heraus." },
      { number: 5, text: "Und die Menge deiner Feinde ist wie feiner Staub, / das Heer der Angreifer wie dahinfliegende Spreu. / Doch dann wird es ganz plötzlich geschehen, / in einem Augenblick:" },
      { number: 6, text: "Jahwe greift ein, der allmächtige Gott, / mit Donnern und Dröhnen und gewaltigem Krach, / mit Wind und Wirbelsturm / und wütenden Flammen und lodernder Glut." },
      { number: 7, text: "Und die Horde der Völker, die gegen Ariël zieht, / es belagert und bestürmt, ist nur noch wie ein böser Traum, / ein Bild in der Nacht." },
      { number: 8, text: "Es wird sein, wie wenn ein Hungriger vom Essen träumt: / Wacht er auf, ist sein Magen immer noch leer. / Wenn ein Durstiger vom Trinken träumt und aufwacht, / ist er mit trockener Kehle völlig erschöpft. / So wird es dieser Völkermenge gehen, / die den Zionsberg bekriegt." },
      { number: 9, text: "Starrt nur hin und werdet starr! / Bleibt verblendet und erblindet! / Ihr seid berauscht, doch nicht von Wein, / ihr taumelt hin und her, und das ganz ohne Bier." },
      { number: 10, text: "Denn Jahwe hat einen Geist der Ohnmacht über euch gebracht. / Eure Augen – die Propheten – hat er zugedrückt / und eure Häupter – die Seher – hat er verhüllt." },
      { number: 11, text: "Und jede Offenbarung ist für euch wie eine Schriftrolle versiegelt. Gibt man sie einem, der lesen kann, und sagt: \"Hier, lies das!\", wird er antworten: \"Das kann ich nicht, es ist versiegelt.\"" },
      { number: 12, text: "Und gibt man sie mit der gleichen Bitte einem, der nicht lesen kann, wird er antworten: \"Ich kann nicht lesen!\"" },
      { number: 13, text: "Weiter hat der Herr gesagt:\"Dieses Volk ist nur mit dem Mund nah bei mir, / es ehrt mich mit den Lippen, aber sein Herz ist weit von mir fort.* / Ihre Gottesfurcht ist ohne Wert, weil sie nur auf angelernten, menschlichen Geboten beruht.", footnotes: ["Wird im Neuen Testament von Jesus Christus zitiert: Matthäus 15,8-9; Markus 7,6-7."] },
      { number: 14, text: "Deshalb will ich auch in Zukunft seltsam handeln an diesem Volk, / wunderlich und wundersam, / dass die Weisheit seiner Weisen vergeht / und der Verstand ihrer Verständigen verfliegt.*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: 1. Korinther 1,19."] },
      { number: 15, text: "Weh denen, die ihre Pläne verstecken vor Jahwe, / damit ihre Werke im Dunkeln bleiben, und sagen: \"Wer sieht uns denn? / Wer merkt schon, was wir tun?\"" },
      { number: 16, text: "Wie verdreht ihr nur seid! / Ist der Töpfer denn nicht mehr wert als der Ton? / Kann das Werk von seinem Schöpfer sagen: \"Er hat mich ja nicht gemacht!\"? / Kann das Kunstwerk von dem Künstler sagen: \"Er versteht doch nichts davon!\"?" },
      { number: 17, text: "Nur noch eine kurze Zeit, dann wandelt sich der Libanon in einen Garten, / und der Garten wird zu einem Wald." },
      { number: 18, text: "An dem Tag werden selbst die Tauben hören, was aus dem Buch gelesen wird, / und die Augen der Blinden werden Dunkel und Finsternis los." },
      { number: 19, text: "Die Erniedrigten freuen sich wieder über Jahwe, / und die Armen jubeln über Israels heiligen Gott." },
      { number: 20, text: "Dann ist der Unterdrücker nicht mehr da, / und mit dem Spötter ist es aus. / Dann sind alle beseitigt, die böse Absichten hatten," },
      { number: 21, text: "die andere als Verbrecher verleumden, / die Richtern bei der Arbeit Fallen stellen / und den, der Recht sucht, aus seinem Recht verdrängen." },
      { number: 22, text: "Darum sagt Jahwe, der Abraham gerettet hat, zu den Nachkommen Jakobs: / \"Nun ist Jakob nicht mehr bloßgestellt, / sein Gesicht wird nicht mehr bleich." },
      { number: 23, text: "Denn wenn er und seine Kinder sehen, was ich in ihrer Mitte tue, / geben sie meinem Namen die Ehre, / machen sie Jakobs Heiligen groß und fürchten Israels Gott." },
      { number: 24, text: "Und die, deren Geist im Irrtum war, / bekommen Einsicht zurück, / die Murrenden nehmen Belehrung an." },
    ] },
    { number: 30, verses: [
      { number: 1, text: "\"Weh den trotzigen Söhnen!\", spricht Jahwe. / \"Sie machen einen Plan, der nicht von mir ausgeht; / sie schließen einen Bund, der gegen meinen Willen ist, / und häufen Schuld auf Schuld.", heading: "Gegen Bündnis-Verhandlungen" },
      { number: 2, text: "Sie ziehen nach Ägypten hinab und fragen nicht nach meinem Rat. / Sie suchen Schutz beim Pharao und Zuflucht im Schatten Ägyptens." },
      { number: 3, text: "Doch der Schutz des Pharao wird euch zur Schande / und die Zuflucht in Ägypten zur Schmach." },
      { number: 4, text: "Eure Oberen kamen zwar bis Zoan* / und eure Gesandten bis nach Hanes*,", footnotes: ["Zoan. Siehe Jesaja 19,11. Dort lebten die Israeliten früher als Sklaven.", "Hanes. Vielleicht Herakleopolis Magna, 80 km südlich von Kairo."] },
      { number: 5, text: "doch sie wurden nur enttäuscht. / Dieses Volk kann niemandem nützen, / es schafft weder Hilfe noch Gewinn, / sondern bringt nur Schande und Hohn.\"" },
      { number: 6, text: "Das Wort, das auf dem Großtier des Südens lastet: / Durch ein Land von Gefahren und Angst, / von Löwinnen und Löwen, / von Nattern und fliegenden Schlangen / bringen sie ihren Reichtum auf dem Rücken der Esel / und ihre Schätze auf den Höckern der Kamele zu einem Volk, das niemand nützen kann." },
      { number: 7, text: "Denn Ägyptens Hilfe ist nichts wert. / Darum nenne ich es: \"Das Ungetüm, das untätig ist.\"" },
      { number: 8, text: "Geh jetzt und schreibe es auf eine Tafel, / verzeichne es auch in ein Buch, / dass es bezeugt ist für alle Zeit!" },
      { number: 9, text: "Denn mein Volk ist ein widerspenstiges Volk. / Sie wollen meine Kinder sein, doch lügen sie dabei, / denn sie hören nicht auf die Weisung Jahwes." },
      { number: 10, text: "Zu den Sehern sagen sie: \"Seht nicht!\" / und zu den Schauenden: \"Ihr sollt uns nicht das Richtige schauen, sondern das, was uns gefällt! / Gebt uns eure Phantasien!" },
      { number: 11, text: "Verlasst den Weg! Weicht ab vom Pfad! / Lasst uns in Ruhe mit Israels heiligem Gott!\"" },
      { number: 12, text: "Darum spricht der Heilige Israels: / \"Weil ihr dieses Wort verwerft, euch auf Gewalt und Betrug verlasst," },
      { number: 13, text: "darum wird eure Schuld für euch sein wie ein durchgehender Riss, / wie eine Beule in einer hohen Mauer, / die dann plötzlich, in einem Augenblick, zusammenbricht.\"" },
      { number: 14, text: "Er wird sie zerbrechen, wie ein Töpferkrug zerbricht, der mitleidlos zertrümmert wird, / sodass kein Stück mehr unter seinen Scherben ist, / mit dem man Glut aus einem Ofen / oder Wasser aus der Pfütze schöpfen kann." },
      { number: 15, text: "Denn so spricht der Herr, Jahwe, Israels heiliger Gott: / \"Durch Umkehr und Ruhe werdet ihr befreit, / im Stillsein und Vertrauen liegt eure ganze Kraft. / Doch ihr wolltet es ja nicht." },
      { number: 16, text: "Ihr sagt: 'Nein, auf Pferden fliegen wir dahin!' – Nicht fliegen, sondern fliehen werdet ihr! – Ihr sagt: 'Auf schnellen Rennern reiten wir!' – Eure Verfolger rennen schneller als ihr." },
      { number: 17, text: "Tausend von euch werden zittern, wenn ein einziger droht; / und wenn nur fünf euch bedrohen, / rennt ihr alle davon. / Und was von euch übrig bleibt, ist wie eine Signalstange auf dem Berg, / wie ein Feldzeichen auf der Hügelspitze." },
      { number: 18, text: "Und trotzdem wartet Jahwe darauf, euch gnädig zu sein. / Um sich über euch zu erbarmen, zeigt er seine Macht, / denn Jahwe ist ein Gott des Rechts. / Wohl denen, die auf sein Eingreifen vertrauen!" },
      { number: 19, text: "Ja, du Volk aus Zion, das in Jerusalem wohnt, weine, weine doch nicht mehr! Er wird dir Gnade schenken, wenn du um Hilfe rufst; sobald er deine Stimme hört, antwortet er schon." },
      { number: 20, text: "Zwar hat der Herr euch Brot der Not und Wasser der Bedrängnis gereicht*, doch jetzt verbirgt er sich nicht länger vor euch: Deine Augen dürfen deinen Lehrer sehen.", footnotes: ["... gereicht. Verkürzte Rationen während der Belagerung."] },
      { number: 21, text: "Wenn ihr nach rechts oder links abbiegen wollt, werdet ihr eine Stimme hinter euch hören: \"Dies ist der Weg, dem folgt!\"" },
      { number: 22, text: "Dann wirst du den Überzug deiner silbernen Schnitzbilder und die Bekleidung deiner goldenen Götzen entweihen. Wie etwas Besudeltes wirfst du sie weg. \"Fort mit dem Dreck!\", sagst du dazu." },
      { number: 23, text: "Dann gibt er Regen deiner Saat auf dem Feld, und Brotgetreide als guten Ertrag, saftig und fett. Dann weidet euer Vieh auf einem weiten Wiesengrund." },
      { number: 24, text: "Die Rinder und Esel, mit denen ihr die Felder pflügt, werden vermengtes Sauerfutter fressen, das man mit Worfschaufel und Gabel gemischt und vor ihnen ausgebreitet hat." },
      { number: 25, text: "Am Tag der großen Schlacht werden Wasserbäche von allen Bergen und allen hohen Hügeln fließen, wenn die feindlichen Türme fallen." },
      { number: 26, text: "Dann wird das Licht des Mondes wie das Licht der Sonne sein, und das Sonnenlicht wird sieben Mal so hell erscheinen wie sonst, als ob das Licht von einer Woche an einem Tag zusammentrifft. An diesem Tag wird Jahwe die Wunden, die er seinem Volk geschlagen hat, heilen und verbinden." },
      { number: 27, text: "Seht, Jahwe kommt persönlich von weither! / Er glüht vor Zorn und ist gewaltig erregt. / Seine Lippen verziehen sich vor Grimm, / und seine Zunge ist wie ein um sich fressendes Feuer." },
      { number: 28, text: "Sein Atem tobt wie ein reißender Bach, dessen Wasser bis zum Halse steht. / Er schüttelt die Völker in seinem Sieb / und schüttet sie fort wie wertlose Spreu. / Er legt einen Zaum in ihr Maul, der sie in die Irre führt." },
      { number: 29, text: "Dann singt ihr Lieder, wie in der Nacht, in der das Fest gefeiert wird. / Ihr werdet euch wie Pilger freuen, die mit Flöten zu Jahwes Berg ziehen, zu ihm, dem Felsen Israels." },
      { number: 30, text: "Dann hört man Jahwes Donnerstimme, / sein Arm zuckt herab mit zornigem Grollen und verzehrendem Feuer, / mit Unwetter, Wolkenbruch und Hagelschlag." },
      { number: 31, text: "Ja, vor der Stimme Jahwes erschrickt Assyrien, wenn es seine Rute spürt." },
      { number: 32, text: "Jedes Mal, wenn die Zuchtrute saust, die Jahwe auf sie niederfahren lässt, / hört man Tamburin- und Zitherspiel. / Mit schwingendem Arm kämpft er gegen sie." },
      { number: 33, text: "Längst ist die Feuerstelle auch für den König bereit: / tief und weit, ein riesiger Verbrennungsplatz, Holzscheite massenhaft. / Wie ein Lavastrom setzt der Atem Jahwes ihn in Brand." },
    ] },
    { number: 31, verses: [
      { number: 1, text: "Weh denen, die um Hilfe nach Ägypten ziehen, / die auf die Masse der Pferde und Streitwagen vertrauen und auf die Menge ihrer Reiter! / Sie schauen nicht auf Israels heiligen Gott / und fragen nicht nach Jahwe.", heading: "Nicht auf Ägypten vertrauen!" },
      { number: 2, text: "Doch nicht nur sie, auch er ist weise und bringt Unglück herbei. / Seine Worte nimmt er nicht zurück. / Er stellt sich gegen die ganze Bande, / die Bösewichter und ihre Kumpane." },
      { number: 3, text: "Ägypter sind nur Menschen und nicht Gott, / ihre Pferde nur Geschöpfe und nicht Geist. / Wenn Jahwe die Hand ausstreckt, kommt der Beschützer zu Fall / und sein Schützling ebenso, und alle beide kommen um." },
      { number: 4, text: "Denn das hat Jahwe mir gesagt: / \"Wie der Löwe über seiner Beute knurrt, / der Junglöwe, gegen den man alle Hirten zusammengeholt hat, / wie er vor ihrem Geschrei nicht erschrickt / und sich bei ihrem Lärm nicht duckt, / so kommt Jahwe, der allmächtige Gott, auf den Berg Zion herab, / zur Verteidigung seiner Hügelstadt." },
      { number: 5, text: "Wie ein Vogel flatternd sein Nest beschützt, / so wird Jahwe, der allmächtige Gott, Jerusalem beschirmen, / beschützen und retten, schonen und befreien.\"" },
      { number: 6, text: "Ihr Israeliten, kehrt um zu dem, von dem ihr so tief abgefallen seid!" },
      { number: 7, text: "Denn es kommt der Tag, an dem jeder seine silbernen und goldenen Götzenbilder verabscheuen wird, die Götzen, die ihr mit euren Händen zu eurer Sünde angefertigt habt." },
      { number: 8, text: "Assyrien wird fallen durch das Schwert, / doch nicht durch eines Menschen Schwert. Vor diesem Schwert ergreift es die Flucht. / Seine jungen Krieger müssen Zwangsarbeit tun." },
      { number: 9, text: "Sein Fels* wird vor Grauen vergehen, / seine Oberen ergreifen die Flucht, / spricht Jahwe, der seinen Herd in Jerusalem hat / und dessen Feuer auf dem Zion brennt.", footnotes: ["Sein Fels ist das, worauf sich Assyrien vergeblich stützte."] },
    ] },
    { number: 32, verses: [
      { number: 1, text: "Seht, ein König kommt, der gerecht regiert. / Auch seine Oberen halten sich an das Recht.", heading: "Das Reich der Gerechtigkeit" },
      { number: 2, text: "Jeder von ihnen ist wie ein sicherer Platz im Sturm, / ein Schutzdach vor dem Wolkenbruch, / wie ein Wasserlauf im dürren Gebiet, / wie der Schatten eines Felsens im glühenden Land." },
      { number: 3, text: "Da sehen alle Augen klar und alle Ohren hören gut." },
      { number: 4, text: "Hitzköpfe werden einsichtig handeln / und Stotternde reden deutlich und klar." },
      { number: 5, text: "Ein gemeiner Mensch wird nicht mehr vornehm genannt / und ein Schurke nicht mehr als ehrlich hingestellt." },
      { number: 6, text: "Denn ein gemeiner Mensch redet Gemeinheit und sein Herz bereitet Böses vor. / Sein Tun ist schändlich und sein Reden beleidigt Jahwe. / Er lässt den Hungrigen darben und den Durstigen nicht trinken." },
      { number: 7, text: "Ein Schurke wendet schlimme Mittel an und schmiedet böse Pläne. / Mit Lügen bringt er Gebeugte zu Fall, / auch wenn der Arme sein Recht beweist." },
      { number: 8, text: "Doch ein redlicher Mensch schlägt Redliches vor / und setzt sich für Redliches ein." },
      { number: 9, text: "Steht auf, ihr sorglosen Frauen, / hört zu, ihr unbekümmerten Töchter, / passt auf und hört auf mein Wort!", heading: "Die Frauen Jerusalems" },
      { number: 10, text: "Noch gut ein Jahr, dann zittert ihr Stolzen vor Angst. / Denn die Weinlese ist vernichtet, / es gibt keine Obsternte mehr." },
      { number: 11, text: "Bangt, ihr Sorglosen, / bekümmert euch, ihr Unbekümmerten! / Zieht euch aus, entkleidet euch / und legt den Trauersack an." },
      { number: 12, text: "Schlagt euch an die Brust / und jammert über die prächtigen Felder, / die fruchtreiche Rebe," },
      { number: 13, text: "das Ackerland von meinem Volk, / das in Gestrüpp und Dornen aufgeht, / jammert über die Häuser voller Freude in der ausgelassenen Stadt." },
      { number: 14, text: "Denn der Palast ist verlassen und leer, / die lärmende Stadt totenstill; / Burg* und Wachtturm sind für immer ein Ruinenfeld, / den Herden zum Weideplatz, / den Wildeseln zur Lust.", footnotes: ["Burg. Hebräisch: Ofel. Der befestigte Südabhang des Tempelberges."] },
      { number: 15, text: "So wird es bleiben, bis Gott seinen Geist über uns gießt. / Dann wird die Wüste zum Garten, und der Garten wird zu einem Wald." },
      { number: 16, text: "In der Wüste siedelt das Recht / und im Garten Gottes Gerechtigkeit." },
      { number: 17, text: "Die Wirkung der Gerechtigkeit wird Friede sein, / ewige Sicherheit und Ruhe ihr Ertrag." },
      { number: 18, text: "Dann wird mein Volk an einem Ort des Friedens wohnen, / in sorgenfreier Ruhe und sicherem Heim." },
      { number: 19, text: "Den Wald der Feinde wird Hagel zerschlagen, und ihre Stadt wird untergehen." },
      { number: 20, text: "Doch ihr sät überall an allen Wassern; / Rind und Esel laufen frei herum. / Wie glücklich seid ihr!" },
    ] },
    { number: 33, verses: [
      { number: 1, text: "Weh dir, du Zerstörer, der selbst nie zerstört worden ist, / du Hinterlistiger, den noch niemand hintergangen hat! / Sobald du mit dem Zerstören fertig bist, wird man auch dich zerstören. / Und wenn du jeden hintergangen hast, wirst du selbst ein Opfer der Hinterlist.", heading: "Das Verlangen nach Freiheit" },
      { number: 2, text: "Jahwe, sei uns gnädig! / Auf dich haben wir gehofft. / Sei uns jeden Morgen ein helfender Arm, / sei unsere Rettung in Zeiten der Not!" },
      { number: 3, text: "Vor deiner Stimme ergreifen die Völker die Flucht, / wenn du aufstehst, zerstreuen sie sich." },
      { number: 4, text: "Dann rafft ihr euch Beute wie ein Heuschreckenschwarm, / wie Grashüpfer rennt ihr und stürzt euch darauf." },
      { number: 5, text: "Hoch erhaben ist Jahwe, er wohnt in der Höhe und sorgt, / dass in Zion Recht und Gerechtigkeit herrscht." },
      { number: 6, text: "Dann lebt ihr in Sicherheit und habt eine Fülle von Heil, / von Weisheit und Erkenntnis. / Und Zions Schatz ist die Ehrfurcht vor Jahwe." },
      { number: 7, text: "Seht, die Gotteshelden jammern auf der Straße, / die Friedensboten weinen bitterlich." },
      { number: 8, text: "Verödet sind die Straßen, kein Reisender wagt sich hinaus. / Der Feind hat den Vertrag ungültig gemacht, / missachtet seine Zeugen, / und Menschenleben zählen für ihn nicht." },
      { number: 9, text: "Es vertrocknet und verwelkt das Land, / beschämt steht der Libanon da, schwarz und verdorrt, / Scharon* ist einer Steppe gleich, / Baschan* und Karmel* stehen kahl.", footnotes: ["Scharon. Fruchtbare Ebene am Mittelmeer.", "Baschan. Fruchtbares Weideland nordöstlich vom See Gennesaret.", "Karmel. Fruchtbares Gartenland an den Hängen des Karmelberges am Mittelmeer."] },
      { number: 10, text: "Jetzt stehe ich auf, spricht Jahwe. / Jetzt erhebe ich mich, jetzt greife ich ein!" },
      { number: 11, text: "Ihr geht schwanger mit Stroh, / und was ihr gebärt, ist nur Spreu. / Euer Schnauben ist ein Feuer, das euch selbst verbrennen wird." },
      { number: 12, text: "Die Völker werden zu Kalk verbrannt, / ins Feuer geworfen wie Dornengestrüpp." },
      { number: 13, text: "Ihr fernen Völker hört, was ich getan; / ihr Nahen, erkennt meine Macht!" },
      { number: 14, text: "Die Sünder in Zion erschrecken tief, / Zittern hat die Gottlosen gepackt: / Wer hält es denn bei rasendem Feuer aus? / Wer kann denn wohnen bei der ewigen Glut?" },
      { number: 15, text: "Wer das Rechte tut und die Wahrheit sagt, / wer keinen Gewinn durch Ausbeutung macht, / wer kein Bestechungsgeschenk entgegennimmt, / wer sich nicht in Mordpläne einweihen lässt / und nicht gafft, wo Unrecht geschieht." },
      { number: 16, text: "Der wird auf den Höhen wohnen, / Bergfestungen sind sein Schutz. / Er hat immer ausreichend Brot, und auch sein Wasser versiegt nie." },
      { number: 17, text: "Deine Augen werden den König in seiner Schönheit erblicken, / sie sehen auf ein weites, offenes Land.", heading: "Die bessere Zukunft" },
      { number: 18, text: "Dann denkt ihr an den früheren Schrecken zurück: / \"Wo ist der, der unser Geld gezählt hat, / wo der, der unser Silber wog und unsere Festungstürme überwachte?\"" },
      { number: 19, text: "Du musst das freche Volk nun nicht mehr sehen, / das Volk mit dunklen, unverständlichen Lauten, / mit stammelnden Worten ohne Sinn." },
      { number: 20, text: "Schau Zion an, die Stadt unserer Zusammenkunft! / Deine Augen sehen Jerusalem, diesen sicheren Ort: / ein Zelt, das nie mehr wandern muss, / dessen Pflöcke niemand herauszieht und dessen Seile keiner je löst." },
      { number: 21, text: "Denn dort ist ein Mächtiger bei uns, es ist Jahwe. / Jerusalem wird wie ein Ort an Strömen sein, / mit mächtigen, breiten Armen, auf denen es keine Galeeren gibt. / Kein feindliches Schiff segelt darauf." },
      { number: 22, text: "Denn Jahwe ist unser Richter, / Jahwe ist es, der uns führt, / Jahwe ist unser König, der uns befreit!" },
      { number: 23, text: "Zwar hängen deine Taue schlaff, / sie halten den Mastbaum nicht fest und breiten das Segel nicht aus. / Dann aber wird Beute über Beute ausgeteilt, / sodass selbst Lahme Beute gewinnen." },
      { number: 24, text: "Und kein Bewohner wird sagen: \"Ich bin krank.\" / Dem Volk, das hier wohnt, wird die Schuld vergeben sein." },
    ] },
    { number: 34, verses: [
      { number: 1, text: "Kommt her, ihr Völker, und hört! / Ihr Völkerstämme, hört aufmerksam zu! / Es höre die Erde und was auf ihr lebt, / der Erdkreis und was ihm entsprosst!", heading: "Gottes Gericht am Beispiel Edoms" },
      { number: 2, text: "Jahwe ist zornig auf die Völker, / sein Grimm richtet sich gegen ihr Heer. / Er hat sie alle unter den Bann* gestellt / und gibt sie zum Abschlachten frei.", footnotes: ["Bann. Das bedeutete die vollständige Vernichtung von Menschen, Tieren und Gütern."] },
      { number: 3, text: "Die Erschlagenen wirft man hinaus. / Der Gestank ihrer Leichen steigt auf. / Die Berge sind von ihrem Blut durchtränkt." },
      { number: 4, text: "Selbst die Gestirne vergehen, und der Himmel rollt sich ein wie ein Buch*. / Sein ganzes Heer verwelkt wie das Weinlaub und schrumpft wie vertrocknete Feigen.", footnotes: ["Buch. Die Bücher waren damals bis zu 10 Meter lange Schriftrollen."] },
      { number: 5, text: "Am Himmel erscheint mein Schwert, / auf Edom fährt es herab, / auf das Volk, das im Gericht dem Bann verfallen ist." },
      { number: 6, text: "Das Schwert Jahwes ist voller Blut, / es trieft vom Fett der Lämmer, / vom Blut der Böcke und von ihrem Nierenfett. / Denn ein Schlachtfest hält Jahwe in Bozra*, / ein großes Schlachten in Edoms Land.", footnotes: ["Bozra. Wichtige edomitische Stadt, Schafzuchtzentrum, 40 km südöstlich vom Süd-Ende des Toten Meeres."] },
      { number: 7, text: "Auch Wildochsen stürzen mit ihnen hin, / der junge und der starke Stier. / Der Boden ist von Blut durchtränkt, / die Erde trieft von ihrem Fett." },
      { number: 8, text: "Das ist der Vergeltungstag Jahwes, / ein Jahr der Abrechnung für Zions Recht." },
      { number: 9, text: "Edoms Bäche verwandeln sich in Pech, / zu Schwefel wird sein Staub. / Das ganze Land wird brennender Teer." },
      { number: 10, text: "Tag und Nacht erlischt er nicht, / ewig steigt sein Rauch empor. / Für alle Zeiten verödet das Land, / für immer und ewig zieht niemand hindurch." },
      { number: 11, text: "Dohle und Igel besitzen es, / Eule und Rabe nisten darin. / Hier ist die Messschnur \"Öde\" gespannt, / und das Senkblei \"Leere\"* hängt herab.", footnotes: ["Öde ... Leere. Hebräisch: Tohu und Bohu erinnern an 1. Mose 1,2."] },
      { number: 12, text: "Kein Fürst ruft je wieder ein Königtum aus, / seine Obersten sind alle dahin." },
      { number: 13, text: "In den Palästen wuchert Dornengesträuch, / Nesseln und Disteln zwischen den Mauern. / Schakale und Strauße bevölkern das Land." },
      { number: 14, text: "Wildkatzen und Hyänen treffen sich dort, / ein Dämon ruft hier dem anderen zu. / Selbst das Nachtgespenst findet sich ein und ruht sich hier aus." },
      { number: 15, text: "Die Sprungnatter legt ihre Eier dort ab und brütet sie aus, / hier sammeln sich Geier in großer Schar." },
      { number: 16, text: "Forscht nach im Buch Jahwes und lest! / Nicht eins von diesen Wesen wird vermisst, alle sind sie da! / Denn so hat es Jahwe befohlen; / sein Geist hat sie alle zusammengebracht." },
      { number: 17, text: "Er selbst hat ihnen das Land vermessen, / durchs Los ihr Stück ihnen zugeteilt. / Für immer ist es ihr Besitz, / für alle Zeiten wohnen sie dort." },
    ] },
    { number: 35, verses: [
      { number: 1, text: "Freuen werden sich Wüste und trockenes Land. / Die Steppe frohlockt, / sie blüht wie eine Krokuswiese auf.", heading: "Die Erlösung Israels" },
      { number: 2, text: "Sie wird in voller Blüte stehen, / und voll Freude jubeln. / Herrlich wie der Libanon wird sie dann sein, / prächtig wie der Karmel und die Ebene Scharon. / Und die Herrlichkeit Jahwes werden sie sehen, / die Pracht und Hoheit von unserem Gott." },
      { number: 3, text: "Macht die erschlafften Hände stark / und die weichen Knie fest!" },
      { number: 4, text: "Ruft den verzagten Herzen zu: / \"Seid stark und fürchtet euch nicht! / Seht, dort kommt euer Gott mit Rache und Vergeltung! / Er selbst wird euch befreien!\"" },
      { number: 5, text: "Dann lässt er Blinde wieder sehen / und schenkt den Tauben das Gehör." },
      { number: 6, text: "Der Lahme springt dann wie ein Hirsch, / der Stumme jubelt froh. / In der Wüste brechen Quellen auf, / in der Steppe fließen Bäche." },
      { number: 7, text: "Der Glutsand wird zu einem Teich, / das dürre Land sprudelt Wasser hervor. / Da wo jetzt Schakale hausen, / ist dann ein Platz für Schilf und Rohr." },
      { number: 8, text: "Eine Straße wird es dort geben, / man nennt sie den heiligen Weg. / Kein unreiner Mensch darf auf ihm gehen, / er ist nur für Gottes Volk. / Selbst Unkundige finden den Weg / und werden nicht in die Irre geführt." },
      { number: 9, text: "Es wird keinen Löwen dort geben, / kein Raubtier lauert auf ihr. / Nur die Erlösten wandern darauf." },
      { number: 10, text: "Die von Jahwe Befreiten kehren heim. / Mit Jubel kommen sie nach Zion zurück. / Aus ihren Augen strahlt unendliches Glück. / Wonne und Freude stellen sich ein, / Kummer und Seufzen sind für immer vorbei." },
    ] },
    { number: 36, verses: [
      { number: 1, text: "Im 14. Regierungsjahr Hiskijas* marschierte der assyrische König Sanherib* in Juda ein und eroberte alle befestigten Städte*.", heading: "36-39: Assyrien und Babylon im Vordergrund\nAssyrer vor Jerusalem (36-37)\nAssyrer vor Jerusalem", footnotes: ["Hiskijas. Im 14. Jahr seiner Alleinregierung, 701 v.Chr. Hiskija war von 729 v.Chr. an Mitregent und regierte von 715-696 allein.", "Sanherib war von 705-681 v.Chr. König von Assyrien.", "alle befestigten Städte. Sanherib rühmte sich, 46 befestigte Städte in Juda eingenommen zu haben."] },
      { number: 2, text: "Von Lachisch* aus schickte er den Rabschake, einen seiner höchsten Würdenträger, mit einem gewaltigen Heer zu Hiskija nach Jerusalem. Der Rabschake stellte sich an die Straße, die zu dem Feld führt, wo die Tuchmacher ihre Stoffe bleichen, an das Ende der Wasserleitung beim oberen Teich*.", footnotes: ["Lachisch. Stadt im Hügelland 46 km südwestlich von Jerusalem. Sie wurde von König Rehabeam zur Festung ausgebaut.", "Teich. Siehe Jesaja 7,3."] },
      { number: 3, text: "Da kamen Eljakim Ben-Hilkija, der Palastvorsteher, der Staatsschreiber Schebna und der Kanzler Joach Ben-Asaf zu ihm heraus." },
      { number: 4, text: "Der Rabschake trug ihnen eine Botschaft an Hiskija auf:\"Der Großkönig, der König von Assyrien lässt dir sagen: Worauf vertraust du eigentlich, dass du dich so sicher fühlst?" },
      { number: 5, text: "Meinst du, der Ausgang eines Krieges wird von Worten bestimmt? Womit willst du antreten gegen meine Macht und Kriegserfahrung? Auf wen vertraust du denn, dass du es wagst, dich gegen mich aufzulehnen?" },
      { number: 6, text: "Verlässt du dich etwa auf Ägypten, dieses zerbrochene Bambusrohr, das jedem die Hand verletzt, der sich darauf stützt? Der Pharao von Ägypten ließ noch jeden im Stich, der sich auf ihn verließ. –" },
      { number: 7, text: "Vielleicht wirst du jetzt behaupten: Wir vertrauen auf Jahwe, unseren Gott! Aber hat Hiskija nicht gerade dessen Höhenheiligtümer und Altäre beseitigt? Hat er nicht den Leuten in Juda und Jerusalem befohlen, nur noch vor dem einen Altar anzubeten? –" },
      { number: 8, text: "Mein Herr, der König von Assyrien, bietet dir eine Wette an: 'Ich will dir 2000 Pferde geben, wenn du die Reiter dazu stellen kannst!'" },
      { number: 9, text: "Wie willst du auch nur einen einzigen Provinzstatthalter vertreiben, einen der geringsten Diener meines Herrn? Aber du verlässt dich ja auf die Macht der ägyptischen Pferde und Streitwagen!" },
      { number: 10, text: "Und noch etwas: Bin ich etwa gegen den Willen Jahwes in dieses Land einmarschiert, um es in Schutt und Asche zu legen? Jahwe selbst hat mir gesagt: Greif dieses Land an und verwüste es!\"" },
      { number: 11, text: "Da unterbrachen Eljakim, Schebna und Joach den Würdenträger und baten ihn: \"Sprich doch bitte aramäisch mit uns! Wir verstehen es. Sprich nicht hebräisch! Die Leute auf der Stadtmauer hören uns zu.\"" },
      { number: 12, text: "Doch der Rabschake erwiderte: \"Hat mich mein Herr etwa nur zu dir und deinem Herrn gesandt? Nein, gerade diese Männer, die da oben auf der Mauer sitzen, sollen es hören. Denn bald werden sie zusammen mit euch ihren eigenen Kot fressen und ihren Harn saufen.\"" },
      { number: 13, text: "Da trat der Rabschake noch ein Stück vor und rief laut auf Hebräisch: \"Hört, was der Großkönig, der König von Assyrien euch sagen lässt:" },
      { number: 14, text: "Lasst euch nicht von Hiskija täuschen! Er kann euch nicht retten." },
      { number: 15, text: "Lasst euch von ihm auch nicht auf Jahwe vertrösten: 'Jahwe wird uns bestimmt retten; diese Stadt wird dem Assyrerkönig nicht in die Hände fallen!'" },
      { number: 16, text: "Hört nicht auf Hiskija! Denn der König von Assyrien sagt euch: Kommt heraus und ergebt euch mir! Dann kann jeder von seinem Weinstock und Feigenbaum essen und aus seiner Zisterne trinken," },
      { number: 17, text: "bis ich euch in ein Land bringe, das ebenso gut wie eures ist, wo es Korn und Most, Brot und Weinberge gibt." },
      { number: 18, text: "Lasst euch von Hiskija nicht an der Nase herumführen, wenn er behauptet: 'Jahwe wird uns retten!' Hat denn irgendein Gott der anderen Völker sein Land vor dem König von Assyrien retten können?" },
      { number: 19, text: "Wo sind denn die Götter von Hamat und Arpad? Wo sind die Götter von Sefarwajim*? Haben sie etwa Samaria vor mir beschützt?", footnotes: ["Sefarwajim. Ort in Syrien, Lage unbekannt. Die Einwohner wurden von den Assyrern im Norden Israels angesiedelt, siehe 2. Könige 17,24.31."] },
      { number: 20, text: "Wer von allen Göttern hat sein Land vor mir retten können? Und dann soll Jahwe Jerusalem vor mir beschützen?\"" },
      { number: 21, text: "Die Männer auf der Mauer schwiegen und gaben ihm keine Antwort, wie es der König befohlen hatte." },
      { number: 22, text: "Die drei Unterhändler gingen mit eingerissenen Gewändern* zu Hiskija und berichteten ihm, was der Rabschake gesagt hatte.", footnotes: ["mit zerrissenen Gewändern. Als Zeichen von Trauer und Entsetzen riss man vom Halsausschnitt an das Gewand mit einem heftigen Ruck etwa eine Handlänge ein."] },
    ] },
    { number: 37, verses: [
      { number: 1, text: "Als der König das hörte, riss er sein Obergewand ein, legte den Trauersack an und ging ins Haus Jahwes." },
      { number: 2, text: "Dann schickte er den Palastvorsteher Eljakim und den Staatsschreiber Schebna mit den Ältesten der Priesterschaft, ebenfalls im Trauersack, zu Jesaja Ben-Amoz." },
      { number: 3, text: "Im Namen des Königs sollten sie ihm sagen: \"Heute ist ein schrecklicher Tag, wir sind gezüchtigt und geschmäht. Die Kinder sind bis an den Muttermund gekommen, aber zum Gebären ist keine Kraft mehr da." },
      { number: 4, text: "Wenn doch Jahwe, dein Gott, die Worte des Rabschake hören wollte, den der König von Assyrien geschickt hat, um ihn, den lebendigen Gott, zu verhöhnen. Vielleicht bestraft er den König wegen dieser Worte, die er gehört hat. Bete doch für die, die von Gottes Volk noch übrig geblieben sind.\"" },
      { number: 5, text: "Die Männer kamen zu Jesaja und erhielten folgende Antwort:" },
      { number: 6, text: "\"Sagt eurem Herrn: 'So spricht Jahwe: Hab keine Angst vor den Drohungen, die du gehört hast! Fürchte dich nicht vor den Lästerungen der Boten des assyrischen Königs!" },
      { number: 7, text: "Pass auf, ich werde dafür sorgen, dass er ein Gerücht hört und in sein Land zurückkehrt! Dort werde ich ihn umbringen lassen.'\"" },
      { number: 8, text: "Der Rabschake kehrte zu seinem König zurück. Er hatte erfahren, dass dieser von Lachisch aufgebrochen war und inzwischen gegen Libna kämpfte." },
      { number: 9, text: "Sein König hatte nämlich gehört, dass der nubische König Tirhaka* mit einem Heer gegen ihn heranrücken würde. Deshalb schickte er Boten zu Hiskija", footnotes: ["Der 20-jährige Tirhaka wird elf Jahre später König von Ägypten sein (690-664)."] },
      { number: 10, text: "und ließ ihm ausrichten: \"Lass dich von deinem Gott nicht täuschen, auch wenn du ihm vertraust! Denke nicht, dass Jerusalem dem König von Assyrien niemals in die Hände fällt!" },
      { number: 11, text: "Du hast ja gehört, was die Könige von Assyrien mit all den anderen Ländern gemacht haben, an denen sie den Bann vollstreckten. Und da willst ausgerechnet du verschont bleiben?" },
      { number: 12, text: "Haben die Götter jener Völker, die meine Vorfahren vernichtet haben, ihre Nationen etwa retten können: Gosan*, Haran*, Rezef* und die Bevölkerung Edens* in Telassar*?", footnotes: ["Gosan. Stadt in Nordmesopotamien, in die einige Israeliten von den Assyrern deportiert worden waren.", "Haran. Stadt, westlich von Gosan, in der Abraham einige Jahre lebte, siehe 1. Mose 11,31.", "Rezef. Stadt zwischen Haran und dem Euphrat.", "Eden. Aramäisches Fürstentum in der Nähe des oberen Euphrat-Tals.", "Telassar. Noch nicht identifizierte Stadt in Eden zwischen den Flüssen Euphrat und Balich."] },
      { number: 13, text: "Wo sind denn die Könige, die in Hamat und Arpad regierten? Wo sind die Könige von Sefarwajim, Hena* und Awa*?\"", footnotes: ["Hena. Vermutlich Stadt in Nordsyrien.", "Awa. Stadtstaat in Nordsyrien, aus dem der Assyrerkönig Salmanassar Leute nach Israel umsiedelte, siehe 2. Könige 17,24."] },
      { number: 14, text: "Hiskija nahm das Schreiben der Boten in Empfang und las es. Dann ging er in den Tempel, breitete es vor Jahwe aus" },
      { number: 15, text: "und betete:" },
      { number: 16, text: "\"Jahwe, du allmächtiger Gott Israels, der über den Cherubim* thront, du allein bist Gott und Herr über alle Reiche der Welt. Du hast Himmel und Erde geschaffen.", footnotes: ["Cherubim. Majestätische (Engel-)Wesen, die Gottes Herrlichkeit repräsentieren. Geschnitzte Abbilder von ihnen breiteten ihre Flügel über die Bundeslade Israels aus und bildeten im Tempel die sichtbare Basis für den unsichtbaren Thron Gottes."] },
      { number: 17, text: "Schenk mir Gehör, Jahwe! Sieh doch, wie es uns geht! Hör doch, wie Sanherib dich, den lebendigen Gott, verhöhnt!" },
      { number: 18, text: "Es ist wahr, Jahwe, die Könige von Assyrien haben alle diese Länder verwüstet." },
      { number: 19, text: "Sie haben deren Götter ins Feuer geworfen. Aber das waren ja keine Götter, sondern Machwerke aus Holz und Stein, die man vernichten konnte." },
      { number: 20, text: "Doch jetzt, Jahwe, unser Gott, rette uns vor ihm, damit alle Königreiche der Welt erkennen, dass du allein Jahwe bist.\"" },
      { number: 21, text: "Da ließ Jesaja Ben-Amoz Hiskija ausrichten: \"So spricht Jahwe, der Gott Israels: Was du zu mir wegen Sanherib, dem König von Assyrien, gebetet hast, habe ich gehört." },
      { number: 22, text: "Höre nun, was Jahwe über ihn sagt:'Zion, die unberührte junge Frau, / verachtet dich und spottet über dich, / die Tochter Jerusalem schüttelt den Kopf." },
      { number: 23, text: "Wen hast du verhöhnt und geschmäht, / gegen wen die Stimme erhoben? / Mit wem ließest du dich ein? – Mit Israels heiligem Gott!" },
      { number: 24, text: "Durch deine Boten verhöhntest du ihn. / Du prahlst: Mit den Streitwagen bezwang ich die Berge, / ich stieg bis zum Gipfel des Libanon. / Den Hochwald seiner Zedern habe ich gefällt, / seine schönsten Zypressen dazu. / Ich kam auf die entlegenste Höhe, / drang in jedes Dickicht vor." },
      { number: 25, text: "Ich grub nach Wasser und trank davon. / Mit meiner Fußsohle trocknete ich die Flüsse Ägyptens aus." },
      { number: 26, text: "Hast du es nicht gehört? / Schon vor langer Zeit habe ich es gewollt. / Seit uralten Tagen habe ich es geplant, / jetzt ließ ich es kommen, dass du befestigte Städte zerstörst, / sie zu öden Steinhaufen machst." },
      { number: 27, text: "Machtlos waren ihre Bewohner, / von Schrecken erfüllt. / In Schande sind sie gestoßen. / Sie waren wie Kraut auf dem Feld, / wie grünes Gras, / wie Gras auf den Dächern, / vom Ostwind verdorrt." },
      { number: 28, text: "Ich weiß, ob du ruhst oder gehst oder kommst. / Ich kenne auch dein Toben gegen mich." },
      { number: 29, text: "Und weil du so gegen mich tobst, / ziehe ich dir einen Ring durch die Nase / und lege dir einen Zaum ins Maul / und führe dich auf dem Weg zurück, / auf dem du gekommen bist.'" },
      { number: 30, text: "Und du, Hiskija, wirst daran erkennen, dass es so geschieht: In diesem Jahr werdet ihr den Nachwuchs der Ernte essen, im nächsten Jahr den Wildwuchs, aber im dritten Jahr werdet ihr wieder säen und ernten, Weinberge pflanzen und ihre Früchte genießen." },
      { number: 31, text: "Und die Bewohner Judas, die mit dem Leben davongekommen sind, werden wieder Wurzeln schlagen und Früchte tragen." },
      { number: 32, text: "Denn ein Rest wird aus Jerusalem kommen, Übriggebliebene vom Berg Zion. Das wird Jahwe, der allmächtige Gott, in seinem Liebeseifer tun." },
      { number: 33, text: "Darum sagt Jahwe Folgendes über den assyrischen König: 'Er wird nicht in diese Stadt eindringen, nicht einen Pfeil wird er hineinschießen. Er wird sie nicht mit Schilden berennen und keinen Wall gegen sie aufschütten." },
      { number: 34, text: "Auf demselben Weg, auf dem er gekommen ist, wird er wieder heimkehren. Er wird ganz bestimmt nicht in diese Stadt eindringen, spricht Jahwe." },
      { number: 35, text: "Um meiner Ehre willen und meinem Diener David zuliebe werde ich diese Stadt retten und beschützen.'\"" },
      { number: 36, text: "In dieser Nacht tötete ein Engel Jahwes im Lager der Assyrer 185.000 Mann. Am nächsten Morgen war alles mit Leichen übersät." },
      { number: 37, text: "Da brach König Sanherib den Feldzug ab und kehrte in seine Heimat nach Ninive zurück." },
      { number: 38, text: "Als er eines Tages im Tempel seines Gottes Nisroch betete, erschlugen ihn seine Söhne Adrammelech und Sarezer mit dem Schwert. Daraufhin mussten sie in das Land Ararat* fliehen, und Sanheribs Sohn Asarhaddon wurde König.", footnotes: ["Land Ararat. Armenien, nördlich von Assyrien."] },
    ] },
    { number: 38, verses: [
      { number: 1, text: "In dieser Zeit* wurde Hiskija todkrank. Da kam der Prophet Jesaja Ben-Amoz zu ihm und sagte: \"Jahwe lässt dir sagen: 'Bereite dich auf dein Ende vor und regle deine Angelegenheiten, du kannst nicht am Leben bleiben!'\"", heading: "Babylonier in Jerusalem (38-39)\nHiskijas Krankheit", footnotes: ["In dieser Zeit. Hiskijas Krankheit und der anschließende Besuch der babylonischen Delegation müssen etwa ein Jahr vor dem Feldzug der Assyrer stattgefunden haben, denn Vers 6 verspricht ja erst die Rettung vor ihnen. Und der in Kapitel 39,1 erwähnte Babylonierkönig Merodach Baladan war schon nicht mehr an der Macht, als die Assyrer kamen."] },
      { number: 2, text: "Da drehte sich Hiskija zur Wand und betete:" },
      { number: 3, text: "\"Ach Jahwe, denk doch daran, dass ich dir immer treu war, dass ich mit ganzer Hingabe tat, was dir gefällt!\" Dann begann er laut zu weinen." },
      { number: 4, text: "Da kam das Wort Jahwes zu Jesaja:" },
      { number: 5, text: "\"Geh wieder zu Hiskija und sage ihm: 'Jahwe, der Gott deines Vorfahren David, lässt dir sagen: Ich habe dein Gebet gehört und deine Tränen gesehen. Ich gebe dir noch fünfzehn Jahre Lebenszeit hinzu." },
      { number: 6, text: "Außerdem werde ich dich und diese Stadt vor dem Assyrerkönig retten. Ich werde Jerusalem beschützen." },
      { number: 7, text: "Jahwe wird dich an folgendem Zeichen erkennen lassen, dass er seine Zusage wahr macht:" },
      { number: 8, text: "Pass auf! Ich lasse den Schatten auf der Treppe, die König Ahas gebaut hat, um die zehn Stufen zurückgehen, die er heute bereits vorangegangen ist.'\" Da ging der Schatten die zehn Stufen zurück." },
      { number: 9, text: "Nachdem Hiskija von seiner Krankheit genesen war, schrieb er folgendes Gedicht nieder:" },
      { number: 10, text: "\"Ich dachte schon: Mitten im Leben stehe ich am Tor der Totenwelt, / der Rest meiner Jahre wird mir geraubt." },
      { number: 11, text: "Ich dachte, ich werde Jah nicht sehen, / Jahwe unter den Lebendigen. / Dort, wo die Abgeschiedenen sind, erblickt man keinen Menschen mehr." },
      { number: 12, text: "Mein Leben ist wie ein Nomadenzelt, / das abgebrochen weggetragen wird. / Wie ein Weber sein Tuch, habe ich mein Leben zu Ende gewebt. / Nun schneidet er mich vom Kettgarn los. / Noch ehe der Tag zur Nacht wird, machst du ein Ende mit mir." },
      { number: 13, text: "Ich schrie um Hilfe bis zum Morgen, / doch wie ein Löwe zerbrach er all mein Gebein. / Noch ehe der Tag zur Nacht wird, machst du ein Ende mit mir." },
      { number: 14, text: "Meine Stimme piepst wie eine Schwalbe, / sie krächzt wie ein Kranich. / Wie Taubengurren klingt meine Klage. / Mit müden Augen starre ich nach oben. / O Herr, ich bin am Ende! / Tritt du als Bürge für mich ein!" },
      { number: 15, text: "Was soll ich nun reden?! / Er hat getan, was er mir angekündigt hat. / Ich verbringe meine Jahre in bitterem Leid." },
      { number: 16, text: "Herr, davon lebt man, und darin lebt auch mein Geist, / dass du mich gesund und lebendig machst." },
      { number: 17, text: "Doch zum Heil wurde mir das bittere Leid! / Du hast mich liebevoll umfangen und mein Leben vor der Grube des Verderbens bewahrt. / Ja, alle meine Sünden warfst du weit hinter dich." },
      { number: 18, text: "Denn das Totenreich kann dich nicht loben, / kein Toter preist dich mit Gesang. / Im Grab hofft niemand auf deine Treue." },
      { number: 19, text: "Allein der Lebende preist dich so wie ich am heutigen Tag. / Die Väter sagen den Kindern: Auf dich ist Verlass!" },
      { number: 20, text: "Jahwe war da und rettete mich! / Alle Tage unseres Lebens soll das Saitenspiel erklingen im Tempel Jahwes.\"" },
      { number: 21, text: "Jesaja hatte nämlich gesagt, man solle einen Verband aus gepressten Feigen auf das Geschwür legen, damit der König wieder gesund werde." },
      { number: 22, text: "Und Hiskija hatte gefragt: \"An welchem Zeichen erkenne ich, dass ich wieder in den Tempel Jahwes gehen kann?\"" },
    ] },
    { number: 39, verses: [
      { number: 1, text: "In dieser Zeit kam eine Gesandtschaft des babylonischen Königs Merodach-Baladan, dem Sohn Baladans*, zu Hiskija. Der König hatte gehört, dass Hiskija krank gewesen und wieder zu Kräften gekommen war. Er ließ ihm ein Schreiben und Geschenke überbringen.*", heading: "Gesandte aus Babylon", footnotes: ["Merodach-Baladan. Regierte von 721-710 v.Chr. über Babylon. Danach musste er sich der assyrischen Herrschaft unter Sargon II. beugen. Einige Zeit nach Sargons Tod 705 v.Chr. konnte er kurz die babylonische Unabhängigkeit wiederherstellen, bis er 702 v.Chr. vor Sanherib fliehen musste.", "Geschenke überbringen. Offenbar wollte er Hiskija in eine anti-assyrische Allianz bringen."] },
      { number: 2, text: "Hiskija freute sich sehr darüber und zeigte ihnen seinen ganzen Besitz: Silber, Gold, die Vorräte an Balsam und feinem Öl, sein Waffenlager und alle seine anderen Schätze. Er zeigte ihnen alles in seinem Haus und in seinem ganzen Reich." },
      { number: 3, text: "Da kam der Prophet Jesaja zu ihm und fragte: \"Was wollten diese Männer von dir? Woher sind sie gekommen?\" – \"Sie kamen aus einem sehr fernen Land\", erwiderte Hiskija, \"aus Babylonien\"." },
      { number: 4, text: "\"Was haben sie in deinem Palast gesehen?\", fragte Jesaja weiter. \"Sie haben alles gesehen, was ich besitze\", erwiderte Hiskija. \"Ich habe sie in alle Schatzkammern schauen lassen.\"" },
      { number: 5, text: "Da sagte Jesaja: \"Höre, was Jahwe, der allmächtige Gott, dir sagen lässt:" },
      { number: 6, text: "'Eines Tages wird der ganze Reichtum in deinem Palast, alles, was du und deine Vorfahren angehäuft haben, nach Babylon weggeschafft werden. Nichts wird übrig bleiben, spricht Jahwe." },
      { number: 7, text: "Und von deinen Enkelsöhnen, deinen Nachfahren, die du gezeugt haben wirst, wird man einige nach Babylon bringen. Sie werden den König dort in seinem Palast bedienen.'\"" },
      { number: 8, text: "Da sagte Hiskija zu Jesaja: \"Das Wort Jahwes, das du mir gesagt hast, ist gut.\" Und er fügte hinzu: \"Wenn nur zu meinen Lebzeiten Frieden und Sicherheit herrschen!\"" },
    ] },
    { number: 40, verses: [
      { number: 1, text: "\"Tröstet, tröstet mein Volk\", sagt euer Gott.", heading: "40-66: Babylon im Hintergrund\nGott schickt Kyrus als Retter (40-48)\nDie Botschaft von der Erlösung" },
      { number: 2, text: "\"Macht den Leuten Jerusalems Mut! / Sagt ihnen, dass die Zwangsarbeit zu Ende geht, / dass ihre Schuld abgetragen ist! / Jahwe ließ sie doppelt* bezahlen für alle ihre Sünden.\"", footnotes: ["doppelt. Nach dem Gesetz die übliche Forderung zum Schadenersatz, siehe 2. Mose 22,3.6.8."] },
      { number: 3, text: "Hört! In der Wüste ruft eine Stimme: / \"Bahnt Jahwe einen Weg! / Baut eine Straße für unseren Gott!*", footnotes: ["Wird im Neuen Testament von Matthäus, Markus und Johannes dem Täufer zitiert: Matthäus 3,3; Markus 1,3; Johannes 1,23."] },
      { number: 4, text: "Jedes Tal soll aufgefüllt, / jeder Berg und Hügel erniedrigt werden! / Alles Zerklüftete soll zur Ebene werden / und alles Hügelige flach!" },
      { number: 5, text: "Denn offenbaren wird sich die Herrlichkeit Jahwes, / und alle Menschen werden es sehen. / Jahwe selbst hat das gesagt.\"" },
      { number: 6, text: "Eine Stimme sagte: \"Predige!\" / \"Was soll ich predigen?\", fragte ich. – \"Alle Menschen sind wie Gras, / und all ihre Schönheit ist wie die Blume auf dem Feld. *", footnotes: ["Wird im Neuen Testament von Petrus zitiert: 1. Petrus 1,24-25."] },
      { number: 7, text: "Das Gras verdorrt, die Blume verwelkt, / denn der Hauch Jahwes wehte sie an. / Ja, wie Gras ist das Volk!" },
      { number: 8, text: "Das Gras verdorrt, die Blume verwelkt, / aber das Wort unseres Gottes bleibt für immer in Kraft.\"" },
      { number: 9, text: "Steig auf einen hohen Berg, du Freudenbotin Zion! / Ruf mit lauter Stimme die frohe Botschaft aus, Jerusalem! / Rufe laut und scheue dich nicht! / Sage den Städten Judas: / \"Seht, da ist euer Gott!" },
      { number: 10, text: "Seht, Jahwe, der Herr kommt mit Kraft! / Er herrscht mit starker Hand. / Den Lohn für seine Mühe bringt er mit. / Sein Volk, das er gewonnen hat, geht vor ihm her." },
      { number: 11, text: "Er weidet seine Herde wie ein Hirt, / nimmt die Lämmer auf seinen Arm. / Er trägt sie im Bausch seines Gewands, / und die Mutterschafe leitet er sacht.\"" },
      { number: 12, text: "Wer kann das Wasser messen mit seiner hohlen Hand? / Wer greift den Himmel mit der Handspanne ab? / Wer fasst mit Eimern* den Staub, der die Erde bedeckt? / Wer wiegt die Berge mit der Waage ab / und legt die Hügel auf die Waagschale drauf?", heading: "Der unvergleichliche Gott", footnotes: ["Eimern. Wörtlich: Dreiling, das heißt ein Drittel Efa, etwa 7,3 Liter."] },
      { number: 13, text: "Wer ermisst den Geist Jahwes? / Wer wird von ihm in seine Pläne eingeweiht?*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 11,34; 1. Korinther 2,16."] },
      { number: 14, text: "Wen fragte er um Rat, dass er ihm auf die Sprünge hilft, / ihn belehrt über den richtigen Weg, / ihm Erkenntnis schenkt und ihn zur vollen Einsicht führt?" },
      { number: 15, text: "Seht, Völker sind wie Tropfen am Eimer für ihn, / wie Stäubchen auf der Waage. / Inseln hebt er wie Sandkörner hoch." },
      { number: 16, text: "Zum Brennholz reicht der Libanon nicht aus / und sein Wild nicht zum Brandopfer für Gott." },
      { number: 17, text: "Vor ihm sind alle Völker wie ein Nichts, / ihre Macht hat vor ihm kein Gewicht." },
      { number: 18, text: "Mit wem wollt ihr Gott denn vergleichen? / Hält irgendetwas den Vergleich mit ihm aus?" },
      { number: 19, text: "Das Götzenbild etwa, das der Kunsthandwerker gießt, / das der Goldschmied mit Gold überzieht und mit silbernen Kettchen behängt?" },
      { number: 20, text: "Da wählt jemand ein Stück Holz, das nicht fault, / und sucht einen geschickten Künstler. / Der stellt ihm das Götterbild auf, dann wackelt es nicht." },
      { number: 21, text: "Begreift ihr denn nicht? / Wollt ihr es nicht hören? / Hat man es euch nicht von Anfang an erzählt? / Versteht ihr nicht, was euch die Gründung der Erde lehrt?" },
      { number: 22, text: "Er ist es, der hoch über dem Erdball thront, / dass die Menschen ihm wie Heuschrecken sind. / Er spannt den Himmel wie einen Schleier aus, / wie ein Zeltdach zum Wohnen." },
      { number: 23, text: "Er stürzt die Mächtigen ins Nichts / und nimmt den Richtern der Erde ihre Gewalt." },
      { number: 24, text: "Kaum sind sie gepflanzt, kaum gesetzt, / kaum hat der Setzling Wurzeln geschlagen, / da haucht er sie an und sie verdorren. Der Sturm trägt sie wie Strohstoppeln fort." },
      { number: 25, text: "\"Mit wem wollt ihr mich also vergleichen, / wer ist mir gleich?\", fragt der heilige Gott." },
      { number: 26, text: "Hebt eure Augen und seht: / Wer hat die Sterne da oben geschaffen? / Er lässt hervortreten ihr Heer, / abgezählt und mit Namen gerufen. / Durch die Macht des Allmächtigen fehlt keiner davon." },
      { number: 27, text: "Ihr Nachkommen Jakobs, Israeliten, / warum behauptet ihr: \"Jahwe weiß nicht, wie es uns geht. / Er kümmert sich nicht um unser Recht!\"?" },
      { number: 28, text: "Weißt du es denn nicht, / oder hast du es noch nie gehört? / Jahwe ist ein ewiger Gott, / der die ganze weite Erde schuf. / Er wird nicht müde, seine Kraft lässt nicht nach / und seine Weisheit ist unerschöpflich tief." },
      { number: 29, text: "Er gibt dem Müden Kraft, / und die Schwachen macht er stark." },
      { number: 30, text: "Die Jungen werden müde und matt, / junge Männer stolpern und brechen zusammen." },
      { number: 31, text: "Doch die auf Jahwe hoffen, gewinnen neue Kraft. / Wie Adler breiten sie die Flügel aus. / Sie laufen und werden nicht müde, / sie gehen und werden nicht matt." },
    ] },
    { number: 41, verses: [
      { number: 1, text: "Hört mich schweigend an, ihr Meeresländer*! / Ihr Völker, sammelt Kraft! / Dann kommt herzu und sprecht. / Wir gehen miteinander vor Gericht.", heading: "Gott und Götzen vor Gericht", footnotes: ["Meeresländer meint Küstenländer und Inseln."] },
      { number: 2, text: "Wer hat den Mann aus dem Osten* berufen, / wer schenkte ihm überall Sieg? / Wer gibt ihm die Völker preis und stürzt die Könige vor ihm? / Wer macht sie vor seinem Schwert wie Staub, / vor seinem Bogen wie verwehtes Stroh?", footnotes: ["Mann aus dem Osten. Gemeint ist Kyrus der Große, von 559-530 v.Chr. König von Persien, der 539 v.Chr. Babylon eroberte und den Juden die Rückkehr in ihre Heimat erlaubte, siehe Esra 1,1-4."] },
      { number: 3, text: "Er verfolgt sie, rückt unversehrt vor, / berührt kaum mit den Füßen den Weg." },
      { number: 4, text: "Wer hat das bewirkt und getan? / Es ist der, der von Anfang an die Menschen in ihr Dasein rief. / Ich, Jahwe, bin es bei den Ersten, / und auch bei den Letzten bin ich es noch!" },
      { number: 5, text: "Die Meeresländer sahen es und fürchteten sich, / die Menschen vom Ende der Erde bekamen Angst. / Sie machten sich auf und kamen herbei." },
      { number: 6, text: "Sie halfen einander und machten sich Mut." },
      { number: 7, text: "Der Kunsthandwerker ermutigt den Goldschmied, / der, der glättet, den, der auf den Amboss schlägt, / und er sagt von der Lötung: \"Sie ist gut!\" / Dann macht er das Götzenbild mit Nägeln fest, dass es nicht wackelt." },
      { number: 8, text: "Doch du, mein Diener Israel, / du, Jakob, den ich erwählte, / Nachkomme meines Freundes Abraham," },
      { number: 9, text: "dich habe ich vom Ende der Erde genommen, / dich aus ihrem fernsten Winkel geholt und zu dir gesagt: / Du stehst in meinem Dienst! / Ich habe dich erwählt und dich auch jetzt nicht verstoßen." },
      { number: 10, text: "Schau nicht ängstlich nach Hilfe aus, / denn ich, dein Gott, ich stehe dir bei! / Hab keine Angst, denn ich bin dein Gott! / Ich mache dich stark und ich helfe dir! / Ich halte dich mit meiner rechten und gerechten Hand." },
      { number: 11, text: "In Schimpf und Schande stehen alle da, / die gegen dich gewütet haben. / Sie gehen zugrunde, werden wie Nichts, / die Männer, die dein Lebensrecht bestreiten." },
      { number: 12, text: "Du wirst sie suchen, aber nicht mehr finden, / die Männer, die mit dir zankten. / Die Krieg mit dir führten, werden wie Nichts und Nichtigkeit." },
      { number: 13, text: "Denn ich bin Jahwe, dein Gott. / Ich fasse dich bei der Hand und sage zu dir: / Fürchte dich nicht! Ich selbst, ich helfe dir!" },
      { number: 14, text: "Erschrick nicht, kleines Würmchen Jakob, / du kleines Häuflein Israel! / Ich, ich helfe dir, spricht Jahwe. / Dein Erlöser ist der heilige Gott Israels." },
      { number: 15, text: "Ich habe dich zu einem scharfen, neuen Dreschschlitten* gemacht, / dich mit Doppelschneiden bestückt. / Berge sollst du dreschen und zermalmen, / Hügel machst du zu Spreu.", footnotes: ["Dreschschlitten. siehe Fußnote zu Jesaja 28,27."] },
      { number: 16, text: "Du wirst sie worfeln, und der Wind trägt sie davon, / der Sturm weht sie fort. / Doch du wirst jubeln über Jahwe, / wirst dich rühmen in Israels heiligem Gott." },
      { number: 17, text: "Die Gebeugten und Bedürftigen suchen Wasser, aber keins ist da. / Ihre Zunge vertrocknet vor Durst. / Doch ich, Jahwe, erhöre sie. / Ich, der Gott Israels, verlasse sie nicht." },
      { number: 18, text: "Aus kahlen Hängen lasse ich Ströme fließen, / in öden Tälern Quellen entspringen. / Ich mache Wüstenland zum Wasserteich, / lasse aus dürrem Boden Wasser quellen." },
      { number: 19, text: "Ich werde Zedern in die Wüste setzen, / Akazie, Myrte und Olivenbaum. / Mitten in die Steppe pflanze ich Platanen, Zypressen und Wacholder," },
      { number: 20, text: "damit sie sehen und erkennen, / verstehen und begreifen, / dass Jahwe hier eingegriffen hat, / dass der heilige Gott Israels das alles erschuf." },
      { number: 21, text: "\"Stellt euch auf zum Prozess!\", spricht Jahwe. / \"Bringt eure Beweise vor!\", sagt der König Jakobs." },
      { number: 22, text: "\"Schafft sie her und sagt uns, was geschehen wird! / Erklärt uns, was in der Vergangenheit geschah, damit wir es zu Herzen nehmen, / und lasst uns erkennen, wohin das führt! / Oder sagt uns, was die Zukunft bringen wird!" },
      { number: 23, text: "Sagt uns doch, was später kommt, / damit wir merken, dass ihr Götter seid! / Ja, zeigt uns Gutes oder auch das Böse, / dann starren wir uns an und fürchten uns vereint!" },
      { number: 24, text: "Seht, ihr seid ja nichts und könnt auch nichts. / Einen Gräuel erwählt, wer immer euch wählt!" },
      { number: 25, text: "Ich habe ihn im Norden erweckt,* und er kam, / der Mann aus dem Osten, der meinen Namen nennt!* / Statthalter zertritt er wie Lehm, / so wie ein Töpfer den Ton zerstampft.", footnotes: ["im Norden erweckt. In seiner frühen Regierungszeit eroberte Kyrus einige Reiche nördlich von Babylon.", "Osten ... nennt. Babylon liegt östlich von Israel. In seinem Dekret zur Rückkehr der Israeliten nennt Kyrus auch den Namen des Herrn."] },
      { number: 26, text: "Wer verkündete das im Voraus, sodass wir sagen könnten: 'Er hat Recht gehabt!'? / Keiner war es, der es meldete, / keiner, der es hören ließ. / Kein Wörtchen hat man von euch gehört." },
      { number: 27, text: "Als Erster habe ich zu Zion gesagt: / 'Seht, da ist es, da sind sie!' / Ich habe Jerusalem den Freudenboten geschickt." },
      { number: 28, text: "Und sehe ich mich um – niemand ist da. / Keiner von diesen Göttern konnte mir raten, / keiner gibt mir Antwort auf meine Fragen." },
      { number: 29, text: "Sie alle sind ja nur Betrug, / zustande bringen sie nichts. / Ihre Statuen sind windig und leer.\"" },
    ] },
    { number: 42, verses: [
      { number: 1, text: "Seht, das ist mein Diener, ich stehe zu ihm! / Ich habe ihn erwählt, und ich finde Gefallen an ihm. / Ich habe meinen Geist auf ihn gelegt. / Er bringt den Völkern das Recht.", heading: "Erstes Lied vom Diener Gottes" },
      { number: 2, text: "Er macht kein Aufheben und schreit nicht herum. / Auf der Straße hört man seine Stimme nicht." },
      { number: 3, text: "Das geknickte Rohr bricht er nicht durch, / den glimmenden Docht löscht er nicht aus. / Ja, er bringt wirklich das Recht." },
      { number: 4, text: "Er selbst verglimmt nicht und knickt auch nicht ein, / bis er das Recht auf der Erde durchgesetzt hat. / Die Meeresländer warten schon auf sein Gesetz.*", footnotes: ["Wird im Neuen Testament von Matthäus zitiert: Matthäus 12,18-21."] },
      { number: 5, text: "So spricht Jahwe, Gott, / der den Himmel geschaffen und ausgespannt / und die Erde und all ihr Gewächs ausgebreitet hat; / der dem Volk auf ihr den Atem gab, / Leben und Geist denen, die auf ihr gehen:" },
      { number: 6, text: "\"Ich, Jahwe, ich habe dich aus Gerechtigkeit gerufen, / ich fasse dich an der Hand. / Ich stehe dir zur Seite und rüste dich aus. / Ich mache dich zum Bund* für das Volk, / und für alle Völker zum Licht,", footnotes: ["zum Bund. Der Messias wird Gottes Bundesverheißungen an Israel erfüllen."] },
      { number: 7, text: "um blinde Augen zu öffnen und Gefangene aus dem Gefängnis zu holen, / um alle, die im Dunkeln sitzen, aus ihrer Haft zu befreien." },
      { number: 8, text: "Ich bin Jahwe, das ist mein Name! / Diese Ehre lass ich mir von niemandem nehmen. / Den Götzen gebe ich nicht mein Lob." },
      { number: 9, text: "Seht, was ich früher sagte, ist eingetroffen. / Nun kündige ich Neues an. / Noch ehe es aufsprosst, hört ihr es von mir.\"" },
      { number: 10, text: "Singt Jahwe ein neues Lied! / Tragt seinen Ruhm bis ans Ende der Welt, / die ihr das Meer befahrt und von seiner Fülle lebt, / Meeresländer und ihre Bewohner!", heading: "Gottes Sieg" },
      { number: 11, text: "Die Steppe mit ihren Orten erhebe lauten Gesang, / auch die Dörfer, die Kedar* bewohnt. / Jubeln sollen die Felsbewohner, / jauchzen von den Gipfeln ihrer Berge!", footnotes: ["Kedar. Siehe Jesaja 21,16."] },
      { number: 12, text: "Sie sollen Jahwe die Ehre geben, / seinen Ruhm in den Meeresländern verkünden!" },
      { number: 13, text: "Jahwe zieht aus wie ein Held, / entfacht wie ein Krieger seine Leidenschaft, / erhebt ein lautes Kriegsgeschrei, / bezwingt seine Feinde wie ein Held." },
      { number: 14, text: "Lange habe ich geschwiegen, / blieb still, bezähmte mich. / Doch jetzt stöhne ich wie eine Frau bei der Geburt, / will schnauben und schnaufen zugleich." },
      { number: 15, text: "Berge und Hügel dörre ich aus, dass all ihr Grün vertrocknen wird. / Ströme lasse ich versiegen und Seen trockne ich aus." },
      { number: 16, text: "Blinde führe ich auf einem Weg, den sie nicht kennen, / ich lasse sie auf unbekannten Pfaden gehen. / Die Finsternis vor ihnen mache ich zum Licht, / holprige Stellen zur ebenen Bahn. / Das werde ich ganz sicher tun, niemand bringt mich davon ab!" },
      { number: 17, text: "Wer sich auf Götzenbilder verlässt, wird beschämt; / wer Gussbilder seine Götter nennt, wird völlig zuschanden." },
      { number: 18, text: "Hört, ihr Tauben! / Ihr Blinden, schaut her und seht!", heading: "Israel – blind und taub" },
      { number: 19, text: "Wer ist blind, wenn nicht mein Diener, / wer taub, wenn nicht mein Bote, den ich sende? Wer ist blind wie mein Vertrauter, / blind wie der Diener Jahwes?" },
      { number: 20, text: "Du hast viel gesehen und doch nichts beachtet, / die Ohren geöffnet und doch nichts gehört." },
      { number: 21, text: "Jahwe hat euch in diese Lage gebracht, / denn er wacht über seine Gerechtigkeit / und macht so sein Gesetz groß und berühmt." },
      { number: 22, text: "Doch jetzt sind sie ein beraubtes, ausgeplündertes Volk, / in Erdlöchern gefesselt, / in Gefängnissen versteckt. / Sie wurden als Beute verschleppt und kein Retter war da. / Sie wurden ausgeplündert und niemand sagte: \"Gib wieder her!\"" },
      { number: 23, text: "Wer von euch nimmt das zu Ohren, / und wer beherzigt es für die kommende Zeit?" },
      { number: 24, text: "Wer gab Jakob der Plünderung preis? / Wer lieferte Israel den Räubern aus? / War es nicht Jahwe, an dem wir uns versündigt hatten? / Doch sie wollten nicht auf seinen Wegen gehen / und hörten nicht auf sein Gesetz." },
      { number: 25, text: "Da goss er die Glut seines Zorns über sie aus / und die Schrecken des Krieges. / Es loderte rings um sie her, / doch zur Erkenntnis kamen sie nicht, / es sengte sie an, / doch es hat sie nicht zur Besinnung gebracht." },
    ] },
    { number: 43, verses: [
      { number: 1, text: "Aber jetzt sagt Jahwe, / der dich geschaffen hat, Jakob, / der dich bildete, Israel: / \"Fürchte dich nicht, / denn ich habe dich erlöst! / Ich habe dich bei deinem Namen gerufen, / du gehörst mir!", heading: "Erlösung durch Gnade" },
      { number: 2, text: "Musst du durchs Wasser gehen, bin ich bei dir, / und durch reißende Ströme – sie überfluten dich nicht. / Musst du durchs Feuer gehen, / wirst du nicht versengt, / diese Flamme verbrennt dich nicht." },
      { number: 3, text: "Denn ich bin Jahwe, dein Gott, / ich bin Israels heiliger Gott, / und ich rette dich! / Ägypten gebe ich als Lösegeld für dich, / Nubien und Seba* noch dazu.", footnotes: ["Seba war ein Land in der Nähe von Kusch (Nubien)."] },
      { number: 4, text: "Weil du mir wert und teuer bist, / weil ich dich liebe, gebe ich Menschen an deiner Stelle hin, / ganze Völker für dein Leben." },
      { number: 5, text: "Fürchte dich nicht, denn ich bin bei dir! / Von dort, wo die Sonne aufgeht, / hole ich deine Nachkommen zurück, / und von dort, wo sie untergeht, / sammle ich euch ein." },
      { number: 6, text: "Zum Norden sage ich: 'Gib sie heraus!', / und zum Süden: 'Halte sie nicht zurück!' / Lass kommen meine Söhne von fern / und meine Töchter vom Ende der Welt," },
      { number: 7, text: "jeden, der mein Eigentum ist, / den ich zu meiner Ehre erschuf / und ins Leben rief!\"" },
      { number: 8, text: "\"Es soll vortreten mein blindes Volk, das doch Augen hat – und Ohren, die nicht hören!", heading: "Zeugen im Prozess" },
      { number: 9, text: "Alle Völker sind versammelt zum Gericht, / alle Nationen herangeholt! / Welcher ihrer Götter hat dies angekündigt? / Welche ihrer Weissagungen trafen überhaupt ein? Mögen sie uns Zeugen dafür stellen! / Die sollen es hören und sagen: 'Es ist wahr!' –" },
      { number: 10, text: "Ihr seid meine Zeugen\", spricht Jahwe, / \"und mein Diener, den ich erwählte, / damit ihr erkennt und mir glaubt, / damit ihr einseht, dass ich es bin! / Vor mir gab es keinen Gott, / und nach mir wird kein anderer sein." },
      { number: 11, text: "Ich bin Jahwe, / einen Retter außer mir gibt es nicht!" },
      { number: 12, text: "Ich habe es angekündigt / und habe euch gerettet. / Ich habe es euch hören lassen, als noch kein fremder Gott bei euch war. / Und ihr seid meine Zeugen\", spricht Jahwe, / \"und ich bin Gott." },
      { number: 13, text: "Und auch in Zukunft bin ich noch derselbe Gott. / Niemand reißt etwas aus meiner Hand! / Was ich tun will, kann niemand verhindern.\"" },
      { number: 14, text: "So spricht Jahwe, euer Erlöser, / Israels heiliger Gott: / \"Um euretwillen habe ich gegen Babel geschickt; / und als Flüchtlinge treibe ich sie hinab / in Schiffen, ihrem Stolz – sie und auch die Chaldäer." },
      { number: 15, text: "Ich bin Jahwe, euer heiliger Gott, / der Schöpfer Israels und euer König!\"" },
      { number: 16, text: "So spricht Jahwe, der einen Weg durchs Meer gebahnt / und euch sicher durch die Fluten geführt hat," },
      { number: 17, text: "der ausziehen ließ Streitwagen und Pferd, / Heer und Held. / Nun liegen sie zusammen da und stehen nicht wieder auf, / ausgelöscht wie ein verglimmender Docht." },
      { number: 18, text: "Denkt nicht an das, was früher war, / achtet nicht auf das Vergangene!" },
      { number: 19, text: "Seht, ich wirke Neues! / Es wächst schon auf. / Merkt ihr es nicht? / Ich bahne einen Weg durch die Wüste, / lege Ströme in der Einöde an." },
      { number: 20, text: "Schakale und Strauße, die Wüstentiere ehren mich, / weil ich der Wüste Wasser gab / und Ströme in der Öde fließen ließ, / damit mein auserwähltes Volk zu trinken hat." },
      { number: 21, text: "Dieses Volk, das ich mir schuf, / soll erzählen, was ich tat." },
      { number: 22, text: "Und doch hast du mich nicht gerufen, Jakob! / Israel, du hast dich nicht um mich gemüht!" },
      { number: 23, text: "Du hast mir keine Lämmer als Opfer gebracht, / mich nicht mit Schlachtopfern geehrt! / Auch mit Speisopfern habe ich dir keine Arbeit gemacht! / Ich habe dich nicht mit Weihrauch ermüdet!" },
      { number: 24, text: "Du hast mir für dein Geld kein Würzrohr gekauft, / mich nicht mit dem Fett deiner Opfer gelabt! / Doch mit deinen Sünden hast du mir Arbeit gemacht! / Mit deinen Vergehen hast du mich ermüdet!" },
      { number: 25, text: "Ich, ich bin es doch, der deine Vergehen auslöscht. / Um meinetwillen denke ich nicht mehr an deine Schuld." },
      { number: 26, text: "Klag mich doch an! Treten wir miteinander vor Gericht! / Trag deine Sache vor und beweise dein Recht!" },
      { number: 27, text: "Schon dein Urahn hat gesündigt, / und deine Führer brachen mit mir." },
      { number: 28, text: "Darum habe ich die Vorsteher des Heiligtums entweiht, / habe Jakob in den Bann getan und gab Israel der Verachtung preis.\"" },
    ] },
    { number: 44, verses: [
      { number: 1, text: "\"Doch jetzt hör zu, mein Diener Jakob, / und du, erwähltes Israel!", heading: "Neues Leben für Gottes Volk" },
      { number: 2, text: "So spricht Jahwe, dein Schöpfer, / der dich im Mutterleib gebildet hat, / der, der dir hilft: / Hab keine Angst, mein Diener Jakob, / du mein erwählter Jeschurun!*", footnotes: ["Jeschurun ist ein Ehrenname für Israel und bedeutet vielleicht: der Redliche."] },
      { number: 3, text: "Denn ich gieße Wasser auf das Durstige, / rieselnde Bäche auf das trockene Land. / Ich gieße meinen Geist über deine Nachkommen aus, / meinen Segen über deine Kinder," },
      { number: 4, text: "dass sie aufschießen wie Gras nach dem Regen, / wie Weidenbäume an Wasserbächen." },
      { number: 5, text: "Der eine sagt: 'Ich gehöre Jahwe!' / Nach Jakob nennt sich ein anderer. / Einer schreibt auf seine Hand: 'Eigentum Jahwes!', / und ein anderer legt sich den Namen 'Israel' bei.\"" },
      { number: 6, text: "So spricht Jahwe, der König Israels und sein Erlöser, / Jahwe, der allmächtige Gott: / \"Ich bin der Erste und ich bin der Letzte, / außer mir gibt es keinen Gott!" },
      { number: 7, text: "Wer ist mir gleich? / Er soll sich melden, / spreche es aus, / beweise es mir! / Wer ließ von Urzeiten an das Kommende hören? / Sollen sie uns doch sagen, was alles noch kommt!" },
      { number: 8, text: "Lasst euch nicht erschrecken und zittert nicht! / Habe ich es dir nicht schon lange gesagt? / Ihr seid meine Zeugen dafür. / Gibt es noch einen Gott außer mir? / Es gibt keinen Fels, / ich müsste ihn kennen!" },
      { number: 9, text: "Alle Götzenmacher sind ein Nichts, / ihre geliebten Götzen nützen nichts. / Und ihre Zeugen sehen nichts und werden beschämt." },
      { number: 10, text: "Wie kann man sich nur einen Gott machen wollen, / ein Götterbild gießen, / das doch nie etwas nützt?" },
      { number: 11, text: "Wer mit so etwas verbunden ist, wird sicher beschämt. / Die Kunsthandwerker sind ja auch nur Menschen. / Mögen sie sich sammeln, / treten sie vor! / Erschrecken werden sie / und schämen werden sie sich." },
      { number: 12, text: "Der Schmied nimmt ein Stück Eisen und steckt es in die Glut. / Dann bringt er es mit Hämmern in die gewünschte Form, / bearbeitet es mit seinem kräftigen Arm. / Dabei hungert er sich ab und verliert seine Kraft, / er trinkt kein Wasser und ist ganz erschöpft." },
      { number: 13, text: "Der Holzschnitzer misst einen Block ab, / umreißt ihn mit dem Stift, / zeichnet mit dem Zirkel vor / und arbeitet die Form mit Stecheisen aus. / Sein Schnitzbild sieht aus wie ein Mensch. / Es ist ein Prachtstück von Mann. / Dann wird es in ein Haus gestellt." },
      { number: 14, text: "Vorher fällt man eine Zeder, / wählt eine Eiche oder sonst einen stärkeren Baum, / pflanzt eine Fichte, die der Regen wachsen lässt." },
      { number: 15, text: "Sie dienen ihm als Feuerholz, / er nimmt davon und wärmt sich damit, / heizt ein, um damit Brot zu backen, / oder er schnitzt daraus einen Gott und wirft sich nieder vor ihm." },
      { number: 16, text: "Die Hälfte davon legt er ins Feuer, / röstet Fleisch in der Glut und sättigt sich daran. / Auch wärmt er sich und sagt: / 'Ah, mir wird warm! Wie gut das tut!'" },
      { number: 17, text: "Und den Rest davon macht er zu einem Gott, / zu seinem Götterbild. / Er bückt sich vor ihm, / wirft sich nieder und betet zu dem Holz: / 'Rette mich, du bist ja mein Gott!' –" },
      { number: 18, text: "Unwissend sind sie und ohne Verstand! / Ihre Augen sind verklebt, dass sie nichts sehen, / und ihr Herz, dass es nicht begreift." },
      { number: 19, text: "Keiner denkt darüber nach und kommt zu Verstand: / 'Die Hälfte habe ich verbrannt, / in seiner Glut backte ich zum Essen Brot und röstete Fleisch, / und den Rest davon machte ich zu einem Gräuel. / Vor einem Holzklotz bückte ich mich.'" },
      { number: 20, text: "Wer Asche hütet, ist betrogen, / sein Herz hat ihn getäuscht. / So rettet er sein Leben nicht, / so sagt er nicht: 'Ein Trugbild hab ich in der Hand!'" },
      { number: 21, text: "Bedenke dies, Jakob, / denn mein Diener bist du! / Ich habe dich geschaffen, Israel, / und du stehst unter meinem Schutz! / Ich vergesse dich nicht!" },
      { number: 22, text: "Wie eine Wolke fege ich deine Verfehlungen weg, / wie einen Nebel deine Sünden. / Kehr zu mir um, / denn ich habe dich erlöst!\"" },
      { number: 23, text: "Jubelt, ihr Himmelswelten, denn Jahwe hat es getan! / Jauchzt, ihr Tiefen der Erde! / Brecht in Jubel aus, ihr Berge, / du Wald und alle deine Bäume! / Denn Jahwe hat Jakob erlöst, / an Israel zeigt er seine Herrlichkeit." },
      { number: 24, text: "So spricht Jahwe, dein Erlöser, / der dich im Mutterleib gebildet hat: / \"Ich bin es, Jahwe, der alles wirkt, / der den Himmel ausgespannt und die Erde ausgebreitet hat, / ich allein! / Wer war da bei mir?", heading: "Berufung des Befreiers Kyrus" },
      { number: 25, text: "Ich bin es, der die Wahrsager zu Narren macht, / die Zeichen der Orakelpriester platzen lässt, / der die Weisen zur Umkehr zwingt und all ihr Wissen wertlos macht." },
      { number: 26, text: "Ich bin es, der das Wort bestätigt, das sein Diener spricht; / der den Plan ausführt, den seine Boten verkünden; / der von Jerusalem sagt: 'Es werde bewohnt!' / und von den Städten Judas: 'Sie werden wieder aufgebaut! / Eure Trümmer richte ich auf!'," },
      { number: 27, text: "der zum tiefen Meer sagt: 'Trockne aus! / Deine Fluten sollen versiegen!';" },
      { number: 28, text: "der von Kyrus* spricht: 'Er ist mein Hirt! / Er wird alles tun, was ich von ihm will.' / Er wird befehlen: 'Jerusalem wird aufgebaut! / Der Grundstein des Tempels werde gelegt!'\"", footnotes: ["Kyrus. Dieser persische König war zu Jesajas Zeit noch nicht einmal geboren. Mehr als 150 Jahre später, 536 v.Chr., würde er den Juden die Heimkehr aus der Verbannung erlauben. Eine ähnliche Ankündigung findet sich nur noch in 1. Könige 13,2, wo Joschija 300 Jahre vor seiner Geburt schon namentlich erwähnt wird."] },
    ] },
    { number: 45, verses: [
      { number: 1, text: "So spricht Jahwe zu Kyrus, seinem Gesalbten, / den er an die Hand gefasst hat, um Völker ihm zu unterwerfen, / um Königen den Hüftgurt zu lösen, / um vor ihm zu öffnen Tür und Tor:" },
      { number: 2, text: "\"Ich selbst, ich gehe vor dir her. / Ich ebne die Ringmauern ein, / zerschlage Bronzetore und zerbreche eiserne Riegel." },
      { number: 3, text: "Ich liefere dir die verborgenen Schätze / und die versteckten Vorräte aus, / damit du erkennst, dass ich, Jahwe, / der Gott Israels bin, der dich bei deinem Namen rief." },
      { number: 4, text: "Wegen Jakob, meinem Diener, / wegen meinem Schützling Israel / habe ich dich berufen / und verlieh dir einen Ehrennamen, / ohne dass du mich kanntest." },
      { number: 5, text: "Ich bin Jahwe, und sonst ist keiner da! / Ich bin der einzige Gott! / Ich gebe dir die Macht, / obwohl du nichts von mir weißt," },
      { number: 6, text: "damit man von da, wo die Sonne aufgeht, / bis dahin, wo sie untergeht, erkennt, / dass es außer mir keinen Gott gibt. / Ich bin Jahwe, und sonst ist keiner da!" },
      { number: 7, text: "Ich bin es, der Licht und Dunkelheit macht, / der Frieden gibt und Unheil schafft. / Ich, Jahwe, bin es, der das alles tut." },
      { number: 8, text: "Ihr Himmel oben, träufelt Gerechtigkeit herab, / ihr Wolken lasst sie strömen! / Die Erde öffne sich und bringe Heil hervor, / lasse wachsen Gerechtigkeit. / Ich, Jahwe, habe das bewirkt.\"" },
      { number: 9, text: "Weh dem, der mit seinem Urheber hadert / und doch nur eine Scherbe von vielen Tonscherben ist. / Sagt der Ton vielleicht zum Töpfer: / \"Was machst du denn da?\" / Hält er ihm vielleicht vor: / \"Du hast kein Geschick!\"?" },
      { number: 10, text: "Weh dem, der zum Vater sagt: / \"Warum hast du gezeugt?\" / und zur Frau: / \"Warum hast du Wehen gehabt?\"" },
      { number: 11, text: "So spricht Jahwe, der heilige Gott Israels und sein Schöpfer: / \"Fragt mich über das, was kommt! / Doch meine Kinder und das Werk meiner Hände lasst mir anbefohlen sein!" },
      { number: 12, text: "Ich selbst habe die Erde gemacht und den Menschen auf ihr! / Ich habe den Himmel ausgespannt / und gab den Sternen ihr Gesetz." },
      { number: 13, text: "Weil ich gerecht bin, habe ich Kyrus erweckt / und ebne ihm seinen Weg. / Meine Stadt baut er wieder auf, mein verschlepptes Volk lässt er frei, / ohne Lösegeld und ohne Bestechungsgeschenk. / Das sagt Jahwe, der allmächtige Gott.\"" },
      { number: 14, text: "So spricht Jahwe: / \"Der Erwerb der Ägypter, / der nubische Handelsgewinn, / die hochgewachsenen Leute von Seba* / werden dir gehören. / Als Sklaven werden sie dir folgen, / in Fesseln kommen sie herbei. / Sie werfen sich nieder vor dir und bekennen: / 'Nur bei dir ist Gott! / Sonst gibt es keinen, überhaupt keinen Gott!'\"", heading: "Die Huldigung der Nationen", footnotes: ["Siehe Fußnote zu Jesaja 43,3!"] },
      { number: 15, text: "Ja, du bist ein Gott, der sich verborgen hält, / du Gott und Retter Israels!" },
      { number: 16, text: "Zuschanden sollen sie alle werden, die Götzenmacher, / und tief beschämt abziehen allesamt." },
      { number: 17, text: "Doch Israel wird durch Jahwe befreit / und so für immer gerettet sein. / Nie werdet ihr beschämt und enttäuscht." },
      { number: 18, text: "Denn so spricht Jahwe, der den Himmel schuf – er ist Gott –, der die Erde geformt und gebildet hat – er selbst hat sie gegründet; / nicht formlos schuf er sie, / sondern zum Bewohnen hat er sie gemacht: / \"Ich bin Jahwe und keiner sonst!" },
      { number: 19, text: "Ich habe nicht im Verborgenen geredet, / irgendwo in einem finsteren Land. / Ich habe den Nachkommen Jakobs nicht gesagt: / 'Vergeblich sucht ihr mich.' / Nein, ich bin Jahwe, der die Wahrheit sagt! / Was ich verkünde, ist gerecht!" },
      { number: 20, text: "Versammelt euch, kommt alle her! / Tretet vor, die ihr dem Untergang eurer Völker entkommen seid! / Wer Holzgötter herumträgt, hat keinen Verstand, / er fleht zu einem Gott, der ihm nicht helfen kann." },
      { number: 21, text: "Erzählt doch von den Taten eurer Götter! / Ja, beratet euch und bringt Beweise herbei! / Wer hat dies alles seit langem verkündet, / es längst im Voraus angesagt? / War ich es nicht, Jahwe, außer dem es weiter keinen Gott gibt? / Außer mir gibt es keinen gerechten und rettenden Gott!" },
      { number: 22, text: "Wendet euch mir zu und lasst euch retten, / ihr Menschen von allen Enden der Welt! / Denn ich bin Gott und keiner sonst!" },
      { number: 23, text: "Ich schwöre bei mir selbst, / Wahrheit kommt aus meinem Mund, / ein Wort, das unverbrüchlich ist: / Alle fallen vor mir auf die Knie / und jede Zunge schwört mir zu:*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 14,11."] },
      { number: 24, text: "'Nur bei Jahwe ist Wahrheit und Macht!' / Beschämt werden alle zu ihm kommen, / die gegen ihn gewütet haben." },
      { number: 25, text: "In Jahwe werden alle Israeliten gerecht, / und in ihm rühmen sie sich dann!\"" },
    ] },
    { number: 46, verses: [
      { number: 1, text: "Bel* hat sich gebeugt, Nebo* krümmt sich nieder; / ihre Bilder werden weggeschleppt und auf Lasttiere gepackt. / Eine Last sind eure Götzenbilder für das erschöpfte Vieh.", heading: "Sturz der Götzen Babylons", footnotes: ["Bel ist ein anderer Name für Marduk, den Hauptgott Babylons, und entspricht dem kanaanäischen Baal (=Herr).", "Nebo, der Gott des Lernens und Schreibens, galt als Sohn Marduks."] },
      { number: 2, text: "Sie krümmen sich, brechen in die Knie; / sie können die Last nicht retten / und ziehen selbst in die Gefangenschaft." },
      { number: 3, text: "\"Ihr Nachkommen Jakobs, hört auf mich, / du Überrest von Israel! / Ich habe euch getragen, seit es euch gibt, / ihr seid mir aufgebürdet von Mutterleib an." },
      { number: 4, text: "Bis in euer Greisenalter bin ich es, der euch trägt. / Bis ihr alt und grau geworden seid, schleppe ich euch. / Ich habe es bisher getan und werde es auch künftig tun. / Ich selbst belade mich und werde euch retten." },
      { number: 5, text: "Mit wem wollt ihr mich vergleichen, / neben wen stellt ihr mich? / Wem wollt ihr mich ähnlich machen, / mich anpassen zum Vergleich?" },
      { number: 6, text: "Da schütten sie Gold aus ihrem Beutel, / wiegen Silber auf der Waage ab, / bezahlen einen Goldschmied, dass er einen Gott daraus macht. / Vor dem bücken sie sich dann und werfen sich hin." },
      { number: 7, text: "Sie heben ihn auf ihre Schultern, / tragen ihn umher und stellen ihn wieder an seinen Platz. / Dort steht er dann und rührt sich nicht. / Ruft man um Hilfe, antwortet er nicht; / er rettet niemand aus der Not." },
      { number: 8, text: "Denkt daran und achtet darauf, / besinnt euch, ihr Treulosen!" },
      { number: 9, text: "Denkt an das, was früher war, von Urzeiten her: / Ja, ich bin Gott und keiner sonst. / Es gibt keinen Gott, der mir gleicht." },
      { number: 10, text: "Von Anfang an habe ich den Ausgang gezeigt, / lange im Voraus die ferne Zukunft vorhergesagt. / Meine Pläne verwirkliche ich, / und was ich mir vornehme, das tue ich auch." },
      { number: 11, text: "Ich rufe den Adler aus dem Osten, / den Mann aus dem fernen Land, der meinen Plan ausführt. / Ja, ich habe es gesagt und lasse es auch so kommen. / Ich habe es geplant, und ich führe es aus." },
      { number: 12, text: "Hört her, ihr Starrköpfe, / die fern sind von dem, was recht ist vor Gott." },
      { number: 13, text: "Ich bringe euch die Gerechtigkeit, / sie ist nicht mehr fern, / meine Rettung verspätet sich nicht. / Zion gebe ich meine Hilfe / und Israel meine strahlende Pracht.\"" },
    ] },
    { number: 47, verses: [
      { number: 1, text: "\"Herunter mit dir, Babylon! / Du stolze junge Frau, setz dich in den Staub! / Setz dich auf die Erde ohne Thron, / du Tochter der Chaldäer! / Du wirst nicht länger die verwöhnte Dame sein!", heading: "Babylons Sturz" },
      { number: 2, text: "Dreh den Mühlstein, mahle Mehl! / Weg mit dem Schleier, heb die Schleppe hoch, / zeig deine Schenkel und wate durch den Strom." },
      { number: 3, text: "Deine Blöße werde aufgedeckt, jeder sehe deine Scham. / Ich werde Rache nehmen, / kein Mensch hindert mich daran!\"," },
      { number: 4, text: "spricht unser Erlöser. / Es ist Jahwe, der Allmächtige,/ Israels heiliger Gott." },
      { number: 5, text: "\"Sei still und setz dich hin, / du Tochter der Chaldäer! / Du musst in die Finsternis. / Denn nun nennt dich niemand mehr 'Herrin vieler Reiche'." },
      { number: 6, text: "Ich war zornig über mein Volk, / entweihte mein Erbe und gab es in deine Gewalt. / Doch du hast kein Erbarmen gehabt, / selbst auf den Greis hast du ein schweres Joch gelegt." },
      { number: 7, text: "Du meintest, auf ewig Herrin zu sein, / hast dir nichts zu Herzen genommen / und nicht an das Ende gedacht." },
      { number: 8, text: "So höre nun, du lüsternes Weib, / das sich in Sicherheit wiegt und denkt: 'Ich und niemand sonst! / Ich sitze nie als Witwe da, / Kinderlosigkeit kenne ich nicht!'" },
      { number: 9, text: "Doch beides wird über dich kommen, / plötzlich und am selben Tag: / Kinderlosigkeit und Witwenschaft. / Es trifft dich mit Wucht trotz all deiner Zauberei, / trotz deiner Bannsprüche mit ihrer gewaltigen Macht." },
      { number: 10, text: "In deiner Bosheit hast du dich sicher geglaubt. / 'Niemand sieht mich', dachtest du. / Deine Weisheit und dein Wissen haben dich irregeführt, / sodass du dir eingeredet hast: / 'Ich, und gar nichts sonst!'" },
      { number: 11, text: "So kommt Unheil über dich, / gegen das du keinen Zauber kennst. / Eine Katastrophe bricht herein, / die du nicht abwenden kannst. / Plötzlich kommt dein Untergang, / und du hast nichts davon geahnt." },
      { number: 12, text: "Versuch es nur mit der Beschwörungskunst! / Los! Wende deine Zaubereien an! / Du hast dich ja von Jugend an darum gemüht. / Vielleicht schaffst du Hilfe herbei, / vielleicht wendest du das Unheil ja ab?" },
      { number: 13, text: "Deine vielen Beratungen haben dich müde gemacht. / Ja, ruf doch deine Astrologen, / deine Himmelszerleger, / die dich jeden Neumond wissen lassen, was über dich kommt. / Sollen sie dich doch retten!" },
      { number: 14, text: "Seht, wie Stroh hat sie das Feuer verbrannt! / Keiner kann sein Leben retten vor dem Feuersturm. / Das ist keine Glut, an der man sich wärmt, / kein Feuerchen, an dem man sitzt." },
      { number: 15, text: "Das ist alles, was sie für dich tun – die, für die du dich gemüht, / mit denen du von Jugend auf gehandelt hast. / Jeder taumelt seines Weges fort, / niemand rettet dich.\"" },
    ] },
    { number: 48, verses: [
      { number: 1, text: "Hört her, ihr Nachkommen Jakobs, / die ihr den Namen Israels tragt, / aus Judas Stamm hervorgegangen seid! / Ihr schwört beim Namen Jahwes / und bekennt euch zu Israels Gott – / aber doch nicht aufrichtig und treu.", heading: "Verstocktes Israel" },
      { number: 2, text: "Ihr nennt euch nach der heiligen Stadt / und stützt euch auf Israels Gott, / der Jahwe, der Allmächtige, heißt." },
      { number: 3, text: "\"Was früher geschah, hatte ich lange vorher gesagt. / Es kam aus meinem Mund, / ich ließ es hören, / und plötzlich tat ich es, und es trat ein." },
      { number: 4, text: "Weil ich wusste, dass du starrsinnig bist, / dein Nacken wie aus Eisen ist / und deine Stirn wie aus Erz," },
      { number: 5, text: "so habe ich dir alles vorher schon gesagt. / Bevor es eintraf, hast du es gehört, – sonst sagst du noch: 'Mein Götze hat es getan. / Das hat mein Schnitz- oder Gussbild befohlen.'" },
      { number: 6, text: "Du hast es gehört, nun schau dir alles an! / Wollt ihr das nicht weitersagen? / Von jetzt an lasse ich dich Neues hören; / bisher war es verborgen, / du hast nichts davon gewusst." },
      { number: 7, text: "Jetzt erst habe ich es geschaffen / und nicht schon früher. / Vor dem heutigen Tag hast du nichts davon gehört, / damit du nicht sagen kannst: 'Ich habe es ja schon lange gewusst!'" },
      { number: 8, text: "Nein, du hast nichts davon gewusst / und noch nie etwas davon gehört! / Denn ich wusste, dass du völlig treulos bist / und dass man dich nicht umsonst nennt: / 'aufsässig von Mutterleib an'." },
      { number: 9, text: "Doch weil es um meinen Namen geht, / bezwinge ich meinen Zorn, / nur wegen meiner Ehre bezähme ich mich und vernichte dich nicht!" },
      { number: 10, text: "Seht, ich habe euch geläutert, / im Schmelzofen des Elends habe ich euch geprüft, / aber ich fand kein Silber darin." },
      { number: 11, text: "Nur um meinetwillen handle ich jetzt, / denn sonst würde mein Name entweiht. / Meine Ehre gebe ich keinem anderen preis!" },
      { number: 12, text: "\"Jakob, hör auf mich! / Höre mich, Israel, den ich berief! / Ich bin es, ich, der Erste und auch der Letzte.", heading: "Israel durch Kyrus befreit" },
      { number: 13, text: "Mit meiner Hand habe ich die Erde gegründet, / mit meiner Rechten den Himmel ausgespannt. / Ich rief ihnen zu, schon standen sie da." },
      { number: 14, text: "Kommt alle her und hört zu! / Wer von den Göttern hat so etwas jemals gesagt? / Der, den Jahwe liebt, vollstreckt seinen Willen an Babylon, / die Chaldäer spüren seine Macht." },
      { number: 15, text: "Ich selbst, ich habe es gesagt, / und ich habe ihn gerufen! / Ich ließ ihn kommen, damit sein Vorhaben gelingt." },
      { number: 16, text: "Kommt her und hört zu! / Von Anfang an habe ich dies öffentlich gesagt, / und seit es geschieht, bin ich dabei.\" / Und nun hat Jahwe, der Herr, mich und seinen Geist gesandt." },
      { number: 17, text: "So spricht Jahwe, dein Erlöser, Israels heiliger Gott: / \"Ich bin Jahwe, dein Gott, / der dich zu deinem Nutzen belehrt, / der dich auf den Weg führt, den du gehen sollst." },
      { number: 18, text: "Hättest du doch auf meine Gebote gehört! / Dann wäre jetzt dein Frieden wie ein Strom, / deine Gerechtigkeit wie die Wogen im Meer." },
      { number: 19, text: "Die Menge deiner Nachkommen wäre wie Sand / und wie Sandkörner deine Sprösslinge. / Ihr Name würde nie beseitigt, / nie ausgelöscht vor mir." },
      { number: 20, text: "Zieht aus Babel fort, / rennt mit Jubel aus Chaldäa heraus! / Macht es bekannt bis an das Ende der Erde: / 'Jahwe hat Jakob, seinen Diener, erlöst!'" },
      { number: 21, text: "Er führt sie durch Wüsten, doch sie leiden keinen Durst. / Er sorgt, dass Wasser aus dem Felsen rinnt, / er spaltet Gestein, damit das Wasser fließt." },
      { number: 22, text: "Doch für Gottlose gibt es keinen Frieden\", spricht Jahwe." },
    ] },
    { number: 49, verses: [
      { number: 1, text: "Hört mir zu, ihr Meeresländer, / horcht auf, ihr Völker in der Ferne! / Schon im Mutterleib berief mich Jahwe, / von Mutterschoß an hat er meinen Namen genannt.", heading: "Gottes Diener bringt die Erlösung (49-57)\nZweites Lied vom Diener Gottes" },
      { number: 2, text: "Er machte meinen Mund zu einem scharfen Schwert / und versteckte mich im Schatten seiner Hand. / Er machte mich zu einem sicher treffenden Pfeil / und hat mich in seinem Köcher verwahrt." },
      { number: 3, text: "Er sagte zu mir: / \"Du bist mein Diener, Israel, / an dir zeige ich meine Herrlichkeit!\"" },
      { number: 4, text: "Ich aber dachte: \"Vergeblich habe ich mich gemüht, / umsonst und nutzlos meine Kraft vertan. / Doch Jahwe sorgt für mein Recht, / er verhilft mir zu meinem Lohn.\"" },
      { number: 5, text: "Jetzt hat Jahwe gesprochen, / der mich schon im Mutterleib zu seinem Diener ausgebildet hat, / damit Jakob zurückgebracht und Israel zu ihm heimgeführt werde. / Bei Jahwe bin ich angesehen, / meine Stärke liegt in meinem Gott." },
      { number: 6, text: "Er sagte: \"Es ist zu wenig, dass du nur mein Diener bist, / um die Stämme Jakobs aufzurichten, / zurückzuführen die Verschonten Israels. / Ich habe dich auch zum Licht der Nationen gemacht, / dass mein Heil das Ende der Erde erreicht.\"*", footnotes: ["Wird im Neuen Testament von Paulus und Barnabas zitiert: Apostelgeschichte 13,47."] },
      { number: 7, text: "Das sagt Jahwe, der Befreier Israels, / sein heiliger Gott, / zu dem, der ganz und gar verachtet ist, / der von den Völkern verabscheut wird, / der auch unter Gewaltherrschern dient: / \"Könige erheben sich, wenn sie das sehen, / und Fürsten werfen sich nieder. / Das geschieht, weil Jahwe sein Wort hält, / weil der Heilige Israels dich erwählt.\"" },
      { number: 8, text: "So spricht Jahwe: / \"Ich habe dich rechtzeitig erhört, / am Tag der Rettung habe ich dir geholfen.* / Ich habe dich vor Schaden bewahrt, / damit du dem Volk zum Mittler meines Bundes wirst, / um das Land wieder aufzurichten, / das verödete Erbe neu zu verteilen,", footnotes: ["Wird im Neuen Testament von Paulus zitiert: 2. Korinther 6,2."] },
      { number: 9, text: "um den Gefangenen zu sagen: / 'Ihr seid frei!', / denen in der Finsternis: 'Kommt ans Licht!'Gleich an den Wegen grasen sie, / auf kahlen Hängen finden sie Weide." },
      { number: 10, text: "Sie leiden weder Hunger noch Durst. / Hitze und Sonnenglut schaden ihnen nicht, / denn ihr Erbarmer leitet sie / und führt sie immer zur Quelle." },
      { number: 11, text: "Alle meine Berge mache ich zum Weg, / meine Straßen führen über die Höhen." },
      { number: 12, text: "Seht, da kommt mein Volk von ferne! / Die einen kommen vom Norden her, / die andern übers westliche Meer – und jene aus dem Lande Sewenim*.\"", footnotes: ["Mit Sewenim ist wahrscheinlich eine jüdische Kolonie bei Syene (Assuan) im südlichen Ägypten gemeint. Andere lesen Sinim und deuten es auf China."] },
      { number: 13, text: "Jubelt, ihr Himmel, / jauchze, du Erde! / Ihr Berge, brecht in Jubel aus! / Denn Jahwe hat sein Volk getröstet, / sich seiner Gebeugten erbarmt." },
      { number: 14, text: "Zion sagt: \"Jahwe hat mich verlassen, / vergessen hat mich der Herr!\"", heading: "Trost und Hoffnung für Zion" },
      { number: 15, text: "\"Kann eine Frau denn ihren Säugling vergessen, / eine Mutter ihren leiblichen Sohn? / Und selbst wenn sie ihn vergessen könnte, / ich vergesse euch nie!" },
      { number: 16, text: "In beide Handflächen habe ich dich eingraviert, / deine Mauern stehen immer vor mir." },
      { number: 17, text: "Schon eilen deine Söhne herbei, / und die dich zerstört und verwüstet haben, ziehen davon." },
      { number: 18, text: "Blick doch auf und schau dich um: / Alle versammeln sich und kommen zu dir! / So wahr ich lebe\", spricht Jahwe, / \"du wirst sie anlegen wie einen Schmuck, / wirst dich mit ihnen schmücken wie eine Braut." },
      { number: 19, text: "Denn deine Trümmerstätten und Einöden, / dein verwüstetes Land wird jetzt für seine Bewohner zu eng, / denn die dich vernichten wollten, sind weit weg." },
      { number: 20, text: "Ja, du warst kinderlos, / doch bald sagen deine Kinder zu dir: / 'Uns wird es hier zu eng. / Schaffe uns mehr Platz!'" },
      { number: 21, text: "Erstaunt wirst du dich fragen: / 'Wer hat mir diese Kinder geboren? / Man hat mir doch meine geraubt, / und ich konnte keine weiteren gebären! / Ich war verstoßen und verbannt. / Wer hat diese hier denn großgezogen? / Ich war doch ganz allein. / Wo kommen sie nur her?'\"" },
      { number: 22, text: "So spricht Jahwe, mein Herr: / \"Seht, ich hebe vor den Völkern die Hand / und stelle mein Feldzeichen für sie auf. / Und sie bringen auf den Armen deine Söhne herbei, / auf den Schultern tragen sie deine Töchter zu dir." },
      { number: 23, text: "Könige werden deine Betreuer sein / und Fürstinnen Ammen für dich. / Mit dem Gesicht auf der Erde ehren sie dich, / küssen den Staub deiner Füße. / Dann wirst du erkennen, dass ich, Jahwe, es bin. / Niemand wird enttäuscht, der mir vertraut.\"" },
      { number: 24, text: "\"Kann man dem Starken die Beute wegnehmen?\", / fragst du. \"Kann der Fang eines Tyrannen entkommen?\"" },
      { number: 25, text: "Ja, denn so spricht Jahwe: / \"Auch einem Starken nimmt man den Gefangenen weg, / und die Beute des Tyrannen entkommt. / Wer dich angreift, den greife ich an, / und deine Kinder rette ich." },
      { number: 26, text: "Deine Peiniger speise ich mit ihrem eigenen Fleisch / und mache sie betrunken mit dem eigenen Blut. / Dann werden alle Menschen erkennen, dass ich, Jahwe, dein Retter bin, / der mächtige Gott Jakobs, / der dich befreit.\"" },
    ] },
    { number: 50, verses: [
      { number: 1, text: "So spricht Jahwe: / \"Ihr sagt, ich hätte eure Mutter fortgeschickt? / Wo ist denn dann ihr Scheidebrief? / Ihr sagt, ich hätte euch als Sklaven verkauft? / Wem hätte ich denn so meine Schulden bezahlt? / Nein, wegen eurer Sünden wurdet ihr verkauft, / wegen eurer Vergehen wurde eure Mutter fortgeschickt.", heading: "Israels Schuld" },
      { number: 2, text: "Weshalb war kein Mensch da, als ich kam? / Weshalb gab keiner Antwort, als ich rief? / Ist denn mein Arm zu kurz, um euch zu befreien? / Fehlt mir vielleicht die Retterkraft? / Durch mein Drohwort vertrocknet das Meer, / versiegen die Ströme; / die Fische sterben vor Durst und stinken, weil kein Wasser mehr ist." },
      { number: 3, text: "Ich kleide den Himmel in Schwarz, / bedecke ihn mit einem Trauersack.\"" },
      { number: 4, text: "Jahwe, mein Herr, gab mir die Zunge von eifrigen Schülern, / denn er zeigt mir, was ich sagen soll, / um Erschöpfte aufzurichten. / Er weckt mich jeden Morgen, / er weckt mir auch das Ohr, / dass ich voll Verlangen höre, was er mir sagen will.", heading: "Drittes Lied vom Diener Gottes" },
      { number: 5, text: "Jahwe, mein Herr, hat mich bereit gemacht, / er öffnete mein Ohr. / Ich habe mich nicht widersetzt / und bin nicht zurückgescheut." },
      { number: 6, text: "Ich hielt meinen Rücken den Schlägern hin, / meine Wangen denen, die mich am Bart gezerrt. / Mein Gesicht habe ich nicht vor Schimpf und Speichel versteckt." },
      { number: 7, text: "Aber Jahwe, mein Herr, steht mir bei. / Darum werde ich doch nicht beschämt. / Darum konnte ich mein Gesicht hart wie einen Kieselstein machen, / denn ich wusste, ich werde nicht enttäuscht." },
      { number: 8, text: "Ich habe einen Beistand, der meine Unschuld beweist. / Wer tritt da im Prozess gegen mich an? / Treten wir zusammen vor den Richter hin! / Wer bringt nun etwas gegen mich vor? / Er stelle sich mir!" },
      { number: 9, text: "Seht, Jahwe, mein Herr, hilft mir! / Wer beschuldigt mich da noch? / Jeder, der das tut, wird zerfallen wie ein von Motten zerfressenes Kleid." },
      { number: 10, text: "Wer von euch hat Ehrfurcht vor Jahwe? / Wer hört auf seinen Diener? / Der kann auch im Finstern gehen, / wo er keinen Lichtstrahl sieht, / denn er vertraut auf den Namen Jahwes / und stützt sich auf seinen Gott.", heading: "Gottes Erlösung für Israel" },
      { number: 11, text: "Doch ihr, die ihr das Feuer schürt / und euch mit Brandpfeilen rüstet, / lauft nur in eure eigene Glut, / geratet zwischen die Pfeile, die ihr angezündet habt! / Ihr bekommt es mit mir zu tun, sodass ihr euch in Qualen winden müsst!" },
    ] },
    { number: 51, verses: [
      { number: 1, text: "\"Hört auf mich, die ihr nach Gerechtigkeit fragt, / die ihr nach Jahwe sucht! / Schaut zu dem Felsen hin, aus dem ihr gehauen seid, / auf den Brunnenschacht, aus dem man euch gegraben hat." },
      { number: 2, text: "Seht auf euren Vater Abraham / und auf Sara, die euch unter Schmerzen gebar! / Als Einzelnen berief ich ihn. / Doch ich habe ihn gesegnet und ihm viele Nachkommen geschenkt.\"" },
      { number: 3, text: "Seid gewiss! Jahwe tröstet Zion und auch alle seine Trümmer! / Das verwüstete Land macht er zu einem Paradies, / die Steppe wie den Garten Jahwes. Freude und Fröhlichkeit findet man dort, / Lobpreis und Gesang." },
      { number: 4, text: "\"Merke auf, mein Volk und höre auf mich! / Denn von mir geht die Weisung aus / und mein Recht wird den Völkern zum Licht." },
      { number: 5, text: "Meine Wahrheit ist nah, / mein Heil tritt hervor, / mein Arm verschafft den Völkern ihr Recht. / Die Meeresländer hoffen auf mich, / auf meinen Beistand warten sie." },
      { number: 6, text: "Blickt zum Himmel hoch: / Er wird sich auflösen wie Rauch. / Schaut auf die Erde unter euch: / Sie wird zerfallen wie ein altes Gewand, / und ihre Bewohner werden sterben wie die Fliegen. / Doch mein Heil wird ewig bleiben, / und meine Gerechtigkeit zerbricht nie." },
      { number: 7, text: "Hört auf mich, die ihr Gerechtigkeit kennt, / du Volk, das meine Weisung in sich trägt: / Fürchtet nicht den Hohn von Menschen, / erschreckt doch nicht vor ihrem Spott!" },
      { number: 8, text: "Denn wie die Motte ein Kleid zerfrisst, so wird es ihnen ergehen, / wie Wolle, die von der Schabe gefressen wird. / Doch meine Gerechtigkeit wird ewig bestehen / und mein Heil in jeder Generation.\"" },
      { number: 9, text: "\"Wach auf, Jahwe, wach auf! / Umkleide dich mit Kraft! / Zeig deine Macht, wie du sie in den Tagen der Vorzeit erwiesen hast! / Warst du es nicht, der Rahab* zerhieb, / der das Ungetüm im Meer erstach?", footnotes: ["Rahab steht für ein Seeungeheuer und ist hier ein sinnbildlicher Name für Ägypten (nicht zu verwechseln mit der Rahab in Josua 2, die im Hebräischen anders geschrieben wird)."] },
      { number: 10, text: "Hast du nicht das Meer trockengelegt, / das Wasser der großen Flut? / Hast du nicht den Meeresgrund zu einem Weg gemacht, / auf dem hindurchzog dein befreites Volk?\"" },
      { number: 11, text: "So kehren die von Jahwe Befreiten zurück, / voll Jubel kommen sie wieder nach Zion, / bleibende Freude wird um sie her sein; / ja, Wonne und Glück stellen sich ein, / und Kummer und Seufzen sind für immer vorbei." },
      { number: 12, text: "\"Ich, ich bin es, der euch tröstet! / Wie kommst du dazu, dich vor Sterblichen zu fürchten, / vor Menschen, die vergehen wie Gras," },
      { number: 13, text: "und Jahwe zu vergessen, der dich gemacht hat, / der den Himmel ausgespannt und die Erde gegründet hat? / Warum zitterst du den ganzen Tag vor dem Zorn deines Unterdrückers, / wenn er sich rüstet, um dich zu vernichten? / Wo bleibt denn die Wut des Bedrückers?" },
      { number: 14, text: "Bald werden die Gefesselten befreit, / keiner wird durch Hunger sterben, / für alle ist genug zu essen da." },
      { number: 15, text: "Ich bin doch Jahwe, dein Gott, / der das Meer aufwühlt, so dass die Wogen tosen, / Jahwe, der allmächtige Gott, bin ich." },
      { number: 16, text: "Meine Worte gab ich in deinen Mund, / und mit dem Schatten meiner Hand hüllte ich dich ein, / als ich den Himmel ausspannte und die Erde gründete, / als ich zu Zion sagte: 'Du bist mein Volk.'\"" },
      { number: 17, text: "Raff dich auf, Jerusalem! / Erhebe dich, steh auf! / Jahwe ließ dich trinken den Becher seines Zorns. / Du hast ihn bis zur Neige ausgeschlürft, / den Trank, der jeden taumeln macht.", heading: "Der Zornbecher Gottes" },
      { number: 18, text: "Und von all den Söhnen, die Jerusalem gebar, / war keiner, der sie bei der Hand nahm, / von allen, die sie aufzog, / niemand, der sie führte." },
      { number: 19, text: "Doppelt hat es dich getroffen, / doch wer zeigt dir schon sein Mitgefühl? / Verwüstung und Zusammenbruch, / Hungersnot und Schwert – und niemand tröstet dich." },
      { number: 20, text: "Ohnmächtig sanken deine Kinder hin, / an den Ecken aller Gassen lagen sie wie die Antilope im Netz, / getroffen vom Zorn Jahwes, / von Gottes Schelte und Grimm." },
      { number: 21, text: "Darum höre doch, gebeugte Stadt, / die taumelt und doch nicht betrunken ist!" },
      { number: 22, text: "So spricht Jahwe, dein Herr und dein Gott, / der den Prozess seines Volkes führt: / 'Ich nehme dir den Becher aus der Hand, / den Trank des Zornes, der dich taumeln macht, / du musst ihn nicht mehr trinken." },
      { number: 23, text: "Ich drück ihn denen in die Hand, / die dich gepeinigt haben, / denen, die dir sagten: / 'Wirf dich nieder, wir schreiten über dich!' / So musstest du deinen Rücken zum Fußboden machen, / zum Weg für die, / die über dich hinweggeschritten sind.\"" },
    ] },
    { number: 52, verses: [
      { number: 1, text: "Wach auf, Jerusalem, / Zion, wach auf! / Erhebe dich und zieh dich an! / Kleide dich in deine Prachtgewänder, du heilige Stadt! Künftig darf dich keiner mehr betreten, / der unbeschnitten* oder unrein* ist.", heading: "Jerusalem im kommenden Reich", footnotes: ["unbeschnitten. Verächtlicher Ausdruck für Menschen, die nicht zum Bund Gottes gehörten. Siehe 1. Mose 17,9-14!", "Unrein waren grundsätzlich alle Ausländer, aber auch die Israeliten, die die Reinheitsgebote des mosaischen Gesetzes nicht beachteten."] },
      { number: 2, text: "Schüttle den Staub von dir ab! / Steh auf, gefangenes Jerusalem! / Zion, wirf die Halsfesseln ab!" },
      { number: 3, text: "Denn so spricht Jahwe: / \"Für euren Verkauf bekam ich kein Geld, / darum werdet ihr auch ohne Silber ausgelöst.\"" },
      { number: 4, text: "Denn so spricht Jahwe, der Herr: / \"Am Anfang zog mein Volk nach Ägypten hinab. / Als Fremde lebten sie dort. / Dann hat Assyrien es grundlos bedrückt." },
      { number: 5, text: "Und wie steht es jetzt?\", sagt Jahwe. / \"Man nahm mein Volk und hat nichts bezahlt. / Und sie johlten über ihren guten Fang. / Ununterbrochen schmähen sie mich / und ziehen meine Ehre in den Dreck\", sagt Jahwe.*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 2,24."] },
      { number: 6, text: "Darum greife ich ein, / und dann wird auch mein Volk erkennen, / dass ich es bin, der spricht: 'Hier bin ich!'\"" },
      { number: 7, text: "Hoch willkommen ist der Freudenbote, / der mit guter Botschaft über die Berge kommt, / der Frieden verkündet und Rettung verheißt,* / der zu Zion sagt: \"Dein Gott herrscht als König!\"", footnotes: ["Wird ebenso wie Nahum 2,1 im Neuen Testament von Paulus zitiert:Römer 10,15."] },
      { number: 8, text: "Hört! Eure Wächter rufen laut, / und sie jubeln allesamt. / Denn sie sehen mit eigenen Augen / wie Jahwe wieder nach Zion kommt." },
      { number: 9, text: "Ihr Trümmer Jerusalems, / brecht in Jubel aus! Denn Jahwe tröstet sein Volk, / er hat Jerusalem befreit." },
      { number: 10, text: "Bloßgestreift hat Jahwe seinen heiligen Arm, / vor den Augen aller Völker greift er ein. / Er rettet sein Volk, / und die ganze Welt sieht zu." },
      { number: 11, text: "Fort, fort! Zieht weg von dort! / Fasst nichts Besudeltes an!* / Zieht weg aus Babylon! / Haltet euch rein! / Denn ihr tragt die Gegenstände für den Tempel Jahwes.", footnotes: ["Wird im Neuen Testament von Paulus zitiert: 2. Korinther 6,17."] },
      { number: 12, text: "Ihr müsst jedoch nicht ängstlich eilen, / denn ihr geht nicht als Flüchtlinge weg. / Jahwe selbst zieht vor euch her, / und Israels Gott wird auch hinter euch sein." },
      { number: 13, text: "Seht, mein Diener wird erfolgreich sein! / Er wird sich erheben, / wird emporgetragen / und zu höchsten Ehren gelangen.", heading: "Das vierte Lied vom Diener Gottes" },
      { number: 14, text: "Viele haben sich über sein Aussehen entsetzt, / denn er war völlig entstellt / und kaum noch als Mensch zu erkennen." },
      { number: 15, text: "Doch nun sind viele Völker überrascht, / selbst Könige halten die Hand vor den Mund. / Denn auf einmal sehen sie, was ihnen nie erzählt worden war, / wovon sie nie etwas hörten, verstehen sie jetzt.*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 15,21."] },
    ] },
    { number: 53, verses: [
      { number: 1, text: "Wer hat denn unserer Botschaft geglaubt? / Und an wem hat sich Jahwes Macht auf diese Weise gezeigt?*", footnotes: ["Wird im Neuen Testament von Johannes und Paulus zitiert: Johannes 12,38; Römer 10,16."] },
      { number: 2, text: "Wie ein kümmerlicher Spross wuchs er vor ihm auf, / wie ein Trieb aus dürrem Boden. / Er war weder stattlich noch schön. / Er war unansehnlich, / und er gefiel uns nicht." },
      { number: 3, text: "Er wurde verachtet, / und alle mieden ihn. / Er war voller Schmerzen, / mit Leiden vertraut, / wie einer, dessen Anblick man nicht mehr erträgt. / Er wurde verabscheut, / und auch wir verachteten ihn." },
      { number: 4, text: "Doch unsere Krankheit, / er hat sie getragen, / und unsere Schmerzen, / er lud sie auf sich. / Wir dachten, er wäre von Gott gestraft, / von ihm geschlagen und niedergebeugt." },
      { number: 5, text: "Doch man hat ihn durchbohrt wegen unserer Schuld, / ihn wegen unserer Sünden gequält.* / Für unseren Frieden ertrug er den Schmerz, / und wir sind durch seine Striemen geheilt.", footnotes: ["Wird im Neuen Testament von Matthäus zitiert: Matthäus 8,17."] },
      { number: 6, text: "Wie Schafe hatten wir uns alle verirrt; / jeder ging seinen eigenen Weg. / Doch ihm lud Jahwe unsere ganze Schuld auf." },
      { number: 7, text: "Er wurde misshandelt, / doch er, er beugte sich / und machte seinen Mund nicht auf. / Wie ein Lamm, das zum Schlachten geführt wird, / wie ein Schaf, das vor den Scherern verstummt, / so ertrug er alles ohne Widerspruch." },
      { number: 8, text: "Durch Bedrückung und Gericht wurde er dahingerafft, / doch wer von seinen Zeitgenossen dachte darüber nach? / Man hat sein Leben auf der Erde ausgelöscht. / Die Strafe für die Schuld meines Volkes traf ihn.*", footnotes: ["Wird im Neuen Testament von einem Äthiopier nach der LXX gelesen und von Philippus erklärt: Apostelgeschichte 8,32-33."] },
      { number: 9, text: "Bei Gottlosen sollte er liegen im Tod, / doch ins Steingrab eines Reichen kam er, / weil er kein Unrecht beging / und kein unwahres Wort aus seinem Mund kam.*", footnotes: ["Wird im Neuen Testament von Petrus zitiert: 1. Petrus 2,22."] },
      { number: 10, text: "Doch Jahwe wollte ihn zerschlagen. / Er war es, der ihn leiden ließ. / Und wenn er sein Leben als Schuldopfer eingesetzt hat, / wird er leben und Nachkommen haben. / Durch ihn gelingt der Plan Jahwes." },
      { number: 11, text: "Nach seiner Seelenqual sieht er das Licht / und wird für sein Leiden belohnt. / Durch seine Erkenntnis wird mein Diener, der Gerechte, / den Vielen Gerechtigkeit bringen; / und ihre Vergehen lädt er auf sich." },
      { number: 12, text: "Darum teile ich die Vielen ihm zu, / und die Starken werden seine Beute sein, / weil er sein Leben dem Tod preisgegeben hat / und sich unter die Verbrecher rechnen ließ.* / Dabei war er es doch, der die Sünden der Vielen trug / und fürbittend für Verbrecher eintrat.", footnotes: ["Wird im Neuen Testament von Jesus Christus zitiert: Lukas 22,37."] },
    ] },
    { number: 54, verses: [
      { number: 1, text: "\"Freue dich, du Unfruchtbare, die noch nie geboren hat; / du, die nie in Wehen lag, brich in Jubel aus! / Denn die Verlassene wird viel mehr Söhne haben als die Frau, die verheiratet war\",* sagt Jahwe.", heading: "Zions künftige Herrlichkeit", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Galater 4,27."] },
      { number: 2, text: "\"Vergrößere dein Zelt, spann deine Zeltdecken aus, spare nicht! / Mach deine Seile lang und schlage die Pflöcke fest ein!" },
      { number: 3, text: "Denn nach rechts und links breitest du dich künftig aus. / Deine Nachkommen werden ganze Völker beerben, / und verödete Städte besiedeln sie neu." },
      { number: 4, text: "Hab keine Angst, du wirst nicht wieder enttäuscht; / schäme dich nicht, du wirst nicht wieder beschämt! / Denn die Schande deiner Jugendzeit wirst du vergessen, / wirst nicht mehr an die Schmach deiner Witwenschaft denken." },
      { number: 5, text: "Denn dein Schöpfer ist dein Ehemann, / es ist Jahwe, der allmächtige Gott, dein Befreier; / es ist der heilige Gott Israels, / der Gott, dem die ganze Erde gehört." },
      { number: 6, text: "Denn wie eine verstoßene und tiefgekränkte Frau rief Jahwe dich zurück. / Wie kann man denn seine Jugendliebe verstoßen?\", sagt dein Gott." },
      { number: 7, text: "\"Für eine kleine Weile habe ich dich verlassen, / aber mit großem Erbarmen hole ich dich wieder heim." },
      { number: 8, text: "Als mein Zorn aufwallte, habe ich mich für einen Augenblick von dir abgewandt, / aber mit ewig währender Gnade erbarme ich mich jetzt über dich, / spricht Jahwe, der dich befreit." },
      { number: 9, text: "Wie in Noahs Zeit soll es für mich sein, / als ich schwor, dass Noahs Flut die Erde nie mehr überschwemmen wird, / so schwöre ich jetzt: 'Ich werde nie mehr zornig auf dich sein / und schreie dich niemals mehr an!'" },
      { number: 10, text: "Eher weichen die Berge von ihrem Platz und die Hügel stürzen um, / als dass meine Gnade von dir weicht und mein Friedensbund wankt, / spricht Jahwe, dein Erbarmer.\"" },
      { number: 11, text: "\"Du leidgeprüfte, verwüstete und preisgegebene Stadt! / Ich lege deine Steine in besten Mörtel ein / und gründe deine Mauern auf Saphir*.", heading: "Das neue Jerusalem", footnotes: ["Saphir ist ein blauer, wie Diamant glänzender Edelstein, siehe 2. Mose 24,10."] },
      { number: 12, text: "Deine Zinnen werden Rubine sein / und deine Tore aus Karfunkeln* bestehen, / die gesamte Umfassung aus teurem Gestein.", footnotes: ["Karfunkel ist ein blutroter Edelstein, ein besonders edler Granat."] },
      { number: 13, text: "Deine Kinder werden von mir selbst belehrt,* / sie werden in Frieden leben und ungestörtem Glück.", footnotes: ["Wird im Neuen Testament von Jesus Christus zitiert: Johannes 6,45."] },
      { number: 14, text: "Du wirst auf Gerechtigkeit gegründet sein, / weißt dich fern von jeder Not, / weil du sie nicht mehr fürchten musst, / fern von Schrecken und Angst, / denn sie kommen nicht an dich heran." },
      { number: 15, text: "Und wenn dich jemand angreifen will, / dann geschieht es ohne mich, / er kommt an dir zu Fall." },
      { number: 16, text: "Seht, ich selber schuf den Schmied, / der das Kohlenfeuer entfacht und Waffen erzeugt. / Ich habe auch den gemacht, / der mit dieser Waffe Tod und Verderben bringt." },
      { number: 17, text: "Deshalb wird dir keine Waffe etwas tun, die gegen dich geschmiedet ist. / Und jeder, der dich vor Gericht anklagt, / wird von dir als Schuldiger entlarvt. / Das ist das Vorrecht der Diener Jahwes, / so sieht ihre Gerechtigkeit aus!\", spricht Jahwe." },
    ] },
    { number: 55, verses: [
      { number: 1, text: "\"He, ihr Durstigen alle, / kommt her zum Wasser! Kommt her, auch wenn ihr kein Geld habt! / Kauft und esst! / Ja, kommt, kauft ohne Geld, / kauft Wein und Milch! / Es kostet nichts.", heading: "An alle, die Durst haben" },
      { number: 2, text: "Warum gebt ihr Geld aus für Brot, das gar keins ist, / den Lohn eurer Mühe für das, was niemand satt machen kann? / Hört doch auf mich, dann bekommt ihr das Beste, / dann esst ihr euch an Köstlichkeiten satt!" },
      { number: 3, text: "Hört auf mich und kommt zu mir! / Dann lebt eure Seele auf, und ich schließe einen ewigen Bund mit euch. / Ich erfülle, was ich schon David versprach.*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Apostelgeschichte 13,34."] },
      { number: 4, text: "Ihn habe ich zum Zeugen für die Völker bestimmt, / zum Herrscher und Gebieter vieler Nationen." },
      { number: 5, text: "Pass auf, auch du rufst künftig manches Volk herbei, das du nicht kennst! / Und mancher Stamm, der dich nicht kannte, wird schnell zu dir kommen, wenn er mich bei dir sieht, / Jahwe, den heiligen Gott Israels, / denn ich habe dich herrlich gemacht!\"" },
      { number: 6, text: "Sucht Jahwe, solange er sich finden lässt! / Ruft ihn an, solange er euch nahe ist!" },
      { number: 7, text: "Der Gottlose verlasse seinen Weg, / der Schurke seine schlimmen Gedanken! / Er kehre um zu Jahwe, damit er sich seiner erbarmt, / zu unserem Gott, denn er ist im Verzeihen groß!" },
      { number: 8, text: "\"Meine Gedanken sind nicht wie eure Gedanken, / und eure Wege nicht wie meine Wege!\", spricht Jahwe." },
      { number: 9, text: "\"Denn so hoch der Himmel über der Erde ist, / so weit reichen meine Gedanken über alles hinaus, was ihr euch denkt, / und meine Möglichkeiten über alles, was für euch machbar ist." },
      { number: 10, text: "Und wie Regen oder Schnee vom Himmel fällt / und nicht dorthin zurückkehrt, ohne dass er die Erde tränkt, / sie fruchtbar macht, dass alles sprießt, / dass Brot zum Essen da ist und Saatgut für die nächste Saat," },
      { number: 11, text: "so ist es auch mit meinem Wort: / Es kehrt nicht leer zu mir zurück, sondern bewirkt, was ich will, / und führt aus, was ich ihm aufgetragen habe." },
      { number: 12, text: "Voll Freude zieht ihr in die Freiheit aus, / kehrt heim mit sicherem Geleit. / Berge und Hügel brechen in Jubel aus, wenn sie euch sehen, / Beifall klatschen die Bäume im Feld." },
      { number: 13, text: "Statt Kameldorn schießt Wacholder auf, / statt Brennnesseln sprießen Myrten hoch. / Das wird zum Ruhm für Jahwe sein, / ein Denkmal, das alle Zeiten übersteht." },
    ] },
    { number: 56, verses: [
      { number: 1, text: "So spricht Jahwe: / \"Wahrt das Recht und sorgt für Gerechtigkeit! / Denn nah ist meine Rettung, sie kommt bald, / und meine Gerechtigkeit, sie wird bald offenbar.", heading: "Auch Fremde werden gerettet" },
      { number: 2, text: "Glücklich der Mensch, der sich daran hält, / der meine Gebote befolgt, / der auf den Sabbat achtet und ihn nicht entweiht, / auf seine Hand und mit ihr nichts Böses tut!\"" },
      { number: 3, text: "Der Fremde, der sich Jahwe anschloss, sage nicht: / \"Jahwe schließt mich sicher aus seinem Volk aus!\" / Und der Eunuch soll nicht denken: / \"Ich bin doch nur ein dürrer Baum.\"" },
      { number: 4, text: "Denn so spricht Jahwe: / \"Wenn ein Eunuch meinen Sabbat beachtet, / wenn er gerne tut, was mir gefällt, und sich an meinen Bund hält," },
      { number: 5, text: "dann gebe ich ihm Raum in meinem Haus / und einen Namen, der nicht in Vergessenheit gerät, / der besser bewahrt wird als durch Söhne und Töchter." },
      { number: 6, text: "Und wenn sich Fremde Jahwe angeschlossen haben, / ihm dienen und ihn lieben, / seinen Sabbat halten und ihn nicht entweihen / und festhalten an seinem Bund," },
      { number: 7, text: "die lasse ich kommen auf meinen heiligen Berg, / die dürfen sich freuen im Haus des Gebets. / Ihre Brand- und Schlachtopfer auf meinem Altar gefallen mir wohl. / Denn mein Tempel soll ein Bethaus für alle Völker sein.\"*", footnotes: ["Wird im Neuen Testament von Jesus Christus zusammen mit Jeremia 7,11 zitiert: Matthäus 21,13; Markus 11,17; Lukas 19,46"] },
      { number: 8, text: "So spricht Jahwe, der Herr, der Israels zerstreutes Volk gesammelt hat: / \"Ich werde noch mehr sammeln zu denen, die schon versammelt sind.\"" },
      { number: 9, text: "\"Ihr wilden Tiere aus Wald und Feld, / kommt und fresst mein Volk!", heading: "Gottlosigkeit in Gottes Volk" },
      { number: 10, text: "Seine Hirten sind blind, sie sehen nicht die Gefahr. / Sie sind wie stumme Hunde, die nicht bellen. / Sie liegen und japsen und schlafen gern." },
      { number: 11, text: "Aber gefräßig sind diese Hunde, / sie kennen kein Maß. / Und das wollen Hirten sein! / Vom Aufpassen halten sie nichts, / eigenen Geschäften gehen sie nach. / Jeder sorgt sich nur um seinen Gewinn." },
      { number: 12, text: "'Kommt her', sagt einer, 'ich hole Wein, / und dann besaufen wir uns! / Und morgen geht es wie heute, / da feiern wir noch mehr!'\"" },
    ] },
    { number: 57, verses: [
      { number: 1, text: "\"Der Gerechte kommt um, und niemand macht sich etwas daraus. / Die treuen Männer werden weggerafft und niemand kümmert sich darum. / Weil die Bosheit herrscht, wird der Gerechte weggerafft." },
      { number: 2, text: "Doch er geht in meinen Frieden ein, / wie jeder, der geradeaus geht." },
      { number: 3, text: "Doch ihr, ihr Hexenkinder, / Brut von Ehebrechern, / ihr Hurenböcke, kommt her!" },
      { number: 4, text: "Über wen macht ihr euch lustig? / Über wen reißt ihr das Maul auf und streckt die Zunge weit heraus? / Verbrecherisches und verlogenes Pack!" },
      { number: 5, text: "Unter Terebinthen werdet ihr brünstig, / hurt unter jedem dichtbelaubten Baum, / und schlachtet eure Kinder unter hängendem Fels unten im Tal!*", footnotes: ["hurt ... im Tal. Jesaja spielt auf Prostitution im Zusammenhang mit Fruchtbarkeitskulten an. Die dabei gezeugten Kinder wurden dann den Götzen geopfert."] },
      { number: 6, text: "Die Steine im Bachtal sind jetzt euer Los, / denn ihnen habt ihr Speis- und Trankopfer gebracht. / Meint ihr denn, ich ließe mir das alles gefallen?" },
      { number: 7, text: "Auf jedem hohen Berg schlägst du dein Hurenlager auf, / du steigst hinauf und feierst Opferfeste." },
      { number: 8, text: "Und hinter Tür und Pfosten bringst du magische Zeichen an. / Denn von mir hast du dich abgewandt. / Für sie hast du dein Lager aufgedeckt, / hast es bestiegen und es breit gemacht. / Hast dir erhandelt, wer mit dir schläft. / Du hattest auch noch Spaß daran / und hast seine Blöße beschaut." },
      { number: 9, text: "Zum König* zogst du mit kostbarem Öl, / verschwendetest eine Menge duftender Salben. / Schicktest deine Boten in die Ferne, / stiegst bis zum Totenreich hinab.", footnotes: ["König (Hebräisch: Melech) klingt an Moloch an, einen kanaanitischen Götzen. Es kann hier aber auch der König von Assyrien oder Ägypten gemeint sein, dessen Beistand man suchte."] },
      { number: 10, text: "Du wurdest müde auf deinem weiten Weg, / doch sagtest du nicht: 'Es ist umsonst!' Immer noch fandest du Leben in dir / und wurdest deshalb nicht schwach." },
      { number: 11, text: "Vor wem hast du denn solche Angst, / dass du mich betrogen hast, / dass du nicht an mich dachtest, / es dir nicht zu Herzen nahmst? / Nicht wahr, weil ich so lange schwieg, / hast du mich nicht mehr gefürchtet?" },
      { number: 12, text: "Doch ich werde dir zeigen, was deine Taten wert sind! / Da nützen dir all deine Machwerke nichts." },
      { number: 13, text: "Wenn du dann um Hilfe schreist, / soll doch der Haufen von Götzen dich retten! / Aber ein Wind weht sie alle davon, / ein Lufthauch trägt sie weg. / Doch wer bei mir seine Zuflucht sucht, / wird das Land zum Erbe bekommen / und wohnen auf meinem heiligen Berg.\"" },
      { number: 14, text: "\"Schüttet eine Straße auf, bahnt einen Weg! / Beseitigt jedes Hindernis vor meinem Volk!\"", heading: "Wem Gott nahe ist" },
      { number: 15, text: "Denn so spricht der hohe und erhabene Gott, / der ewig lebt und dessen Name 'der Heilige' ist: / \"Ich wohne in der Höhe, / in unnahbarer Heiligkeit, / doch bin ich auch den Zerschlagenen nah, / deren Geist niedergedrückt ist, / und belebe den Geist dieser Gedemütigten neu, / richte das Herz der Zerschlagenen auf." },
      { number: 16, text: "Denn ich klage nicht für immer an / und werde nicht auf Dauer zornig sein. / Sonst müsste ihr Atem vor mir vergehen / und ihr Geist, den ich ja erschuf." },
      { number: 17, text: "Zornig war ich wegen ihrer Sünde, / wegen ihrer Habsucht schlug ich mein Volk. / Ich wandte mich von ihnen ab und brachte Unheil über sie. / Und sie gingen weg, ihren eigenen Weg." },
      { number: 18, text: "Ja, ich sah, welche Wege mein Volk ging, / dennoch werde ich sie heilen. / Ich führe sie und gewähre ihnen Trost. / Seinen Trauernden" },
      { number: 19, text: "schaffe ich Lob auf den Lippen. / Frieden denen, die fern von Jerusalem sind, / und Frieden den Nahen, spricht Jahwe. / Ich heile mein Volk!" },
      { number: 20, text: "Aber die Gottlosen sind wie das aufgewühlte Meer, / das nicht zur Ruhe kommt. / Schlamm und Dreck wühlen seine Wellen auf." },
      { number: 21, text: "Für Gottlose gibt es keinen Frieden!\", spricht mein Gott." },
    ] },
    { number: 58, verses: [
      { number: 1, text: "\"Ruf aus voller Kehle! Rufe so laut du kannst! / Lass deine Stimme schmettern wie eine Trompete / und halte meinem Volk seine Vergehen vor, / den Nachkommen Jakobs ihre Schuld!", heading: "Gottes Plan für den Frieden (58-66)\nEchtes Fasten" },
      { number: 2, text: "Zwar befragen sie mich Tag für Tag / und wollen zu gern meine Wege erkennen. / Wie ein Volk, das recht vor mir lebt / und auch meine Gebote hält, / fordern sie von mir gerechtes Gericht / und begehren Gottes Nähe." },
      { number: 3, text: "'Warum fasten wir, und du siehst es nicht? / Warum demütigen wir uns, und du merkst es nicht einmal?' – Seht doch, was ihr an euren Fastentagen tut! / Ihr geht euren Geschäften nach und beutet eure Arbeiter aus." },
      { number: 4, text: "Ihr fastet zwar, / aber gleichzeitig zankt und streitet ihr euch / und schlagt gleich mit gottloser Faust zu. / So wie ihr jetzt fastet, / verschafft ihr eurer Stimme droben kein Gehör." },
      { number: 5, text: "Soll das vielleicht ein Fasttag sein, der mir gefällt, / der Tag, an dem ein Mensch sich wirklich beugt, / dass er den Kopf wie eine Binse hängen lässt, / sich in den Trauersack hüllt und sich in die Asche setzt? / Nennst du das ein Fasten, / soll das ein Tag sein, der Jahwe gut gefällt?" },
      { number: 6, text: "Nein, ein Fasten, das mir gefällt, ist so: / Löst die Fesseln der Ungerechtigkeit, / knotet die Jochstricke auf, / gebt Misshandelten die Freiheit, / schafft jede Art von Unterdrückung ab!" },
      { number: 7, text: "Ladet Hungernde an euren Tisch, / nehmt Obdachlose bei euch auf! / Wenn du jemand halbnackt und zerlumpt herumlaufen siehst, / dann gib ihm etwas anzuziehen! / Hilf dem in deinem Volk, der deine Hilfe braucht!" },
      { number: 8, text: "Dann strahlt dein Licht wie die Morgenröte auf, / und deine Wunden heilen schnell. / Dann zieht die Gerechtigkeit vor dir her, / und die Herrlichkeit Jahwes wird deine Nachhut sein." },
      { number: 9, text: "Wenn du dann zu Jahwe rufst, wird er dir Antwort geben; / wenn du um Hilfe schreist, wird er sagen: 'Ja, hier bin ich!' / Wenn du aufhörst, andere zu unterdrücken, / nicht verächtlich mit dem Finger zeigst / und niemand mehr verleumdest," },
      { number: 10, text: "wenn du Hungernden das gibst, wonach du selbst Verlangen hast, / und so einen Darbenden satt machst, / dann strahlt dein Licht in der Finsternis auf, / die Nacht um dich wird wie der helle Tag," },
      { number: 11, text: "dann wird Jahwe dich immer führen – auch im dürren Land macht er dich satt, / gibt dir die nötige Kraft –, dann wirst du wie ein Garten sein, der immer genug Wasser hat, / und wie eine Quelle, die niemals versiegt." },
      { number: 12, text: "Die uralten Trümmerstätten bauen deine Leute wieder auf, / die Grundmauern vergangener Generationen stellst du wieder her. / Man wird dich den Maurer nennen, der die Lücken schließt, / der Straßenzüge wieder bewohnbar macht." },
      { number: 13, text: "Wenn du dich am Sabbat zurückhältst, / wenn du nicht dein Vergnügen suchst an meinem heiligen Tag, / wenn dir der Sabbat eine Freude ist, / ein Ehrentag, ein heiliger Tag Jahwes, / wenn du ihn ehrst, und nicht deine Wege erledigst, / Geschäfte betreibst und viele Worte machst," },
      { number: 14, text: "dann wird Jahwe die Quelle deiner Freude sein. / Er wird dich über die Höhen des Landes führen / und lässt dich genießen das Erbe deines Stammvaters Jakob.\" / Ja, das hat Jahwe gesagt." },
    ] },
    { number: 59, verses: [
      { number: 1, text: "Seht es doch: Jahwes Arm ist zum Helfen nicht zu kurz, / sein Ohr ist zum Hören nicht zu taub!", heading: "Sünde, Buße und Verheißung" },
      { number: 2, text: "Nein, eure Vergehen haben die Mauer gebaut, / die zwischen euch und eurem Gott steht. / Eure Sünden verhüllten sein Gesicht, / dass er euch auch nicht anhören will." },
      { number: 3, text: "Eure Hände sind mit Blut befleckt, / Unrecht klebt an euren Fingern. / Eure Lippen lügen, / und eure Zunge zischt Boshaftigkeit." },
      { number: 4, text: "Keiner bringt gerechte Klagen vor, / keiner hält ehrlich Gericht. / Man vertraut auf Nichtigkeiten, / redet gehaltloses Zeug, / geht mit Unheil schwanger / und bringt Unrecht zur Welt." },
      { number: 5, text: "Schlangeneier brüten sie aus, / und Spinngewebe weben sie. / Wer von den Eiern isst, wird sterben; / und wenn man eins zerdrückt, fährt eine Giftschlange heraus." },
      { number: 6, text: "Ihre Fäden werden nie zum Gewand, / und ihr Gewebe deckt keinen Menschen zu. / Ihre Werke sind Handlungen des Unrechts, / und ihre Hände sind voller Gewalt." },
      { number: 7, text: "Ihre Füße laufen dem Bösen nach, / schnell vergießen sie unschuldiges Blut. / Ihre Pläne sind von Unheil erfüllt, / nur Scherben und Verderben sind auf ihren Straßen." },
      { number: 8, text: "Was zum Frieden führt, kennen sie nicht; / in ihren Spuren zeigt sich kein Recht. / Bewusst schlagen sie krumme Wege ein. / Wer ihnen folgt, kennt den Frieden nicht mehr.*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 3,15-17."] },
      { number: 9, text: "Darum gibt es bei uns kein Recht, / und Gerechtigkeit erreicht uns nicht. / Wir hoffen auf Licht und bekommen Finsternis; / wir warten darauf, dass es hell wird, doch uns umgibt finstere Nacht." },
      { number: 10, text: "Wie Blinde tasten wir uns an der Wand entlang, / wie Augenlose tappen wir herum. / Am hellen Mittag stolpern wir wie in der Dämmerung, / wie Tote sind wir mitten im Leben." },
      { number: 11, text: "Wie aufgeschreckte Bären brummen wir, / und gurren wie klagende Tauben. / Wir hoffen auf das Recht, aber nichts geschieht, / auf die Rettung, doch sie bleibt fern von uns." },
      { number: 12, text: "Denn vielfach haben wir uns gegen dich vergangen, / unsere Sünden klagen uns an! / Ja, unsere Vergehen sind uns bewusst, / wir kennen unsere Schuld:" },
      { number: 13, text: "Untreue und Verleugnung Jahwes, / Abkehr von unserem Gott, / Reden von Gewalttat und Aufruhr, / mit Lügenworten schwanger gehen / und sie dann aus dem Herzen hervorstoßen." },
      { number: 14, text: "So wurde das Recht verdrängt, / und die Gerechtigkeit zog sich zurück. / Die Wahrheit kommt auf dem Marktplatz zu Fall, / die Redlichkeit ist nicht mehr gefragt." },
      { number: 15, text: "So wird die Wahrheit bei uns vermisst, / und wer das Böse meidet, wird ausgeraubt.Das alles hat Jahwe gesehen, / und ihm missfällt, dass es kein Recht mehr gibt." },
      { number: 16, text: "Er sieht, dass niemand sich regt, / und wundert sich, dass keiner dazwischentritt. / Da greift er mit eigener Hand ein, / von eigener Wahrhaftigkeit unterstützt." },
      { number: 17, text: "Er zieht die Gerechtigkeit wie einen Panzer an / und hat aufgesetzt den Helm des Heils. / Mit Vergeltung kleidet er sich, / er hat den Mantel der Entschlossenheit an." },
      { number: 18, text: "Jedem zahlt er es nach seinen Taten heim: / seinen Gegnern Zorn, / seinen Feinden Vergeltung. / Auch den Meeresländern zahlt er den verdienten Lohn." },
      { number: 19, text: "Dann fürchtet man im Westen den Namen Jahwes / und im Osten seine Herrlichkeit. / Denn er kommt wie ein eingezwängter reißender Strom, / den sein Atem vorwärtstreibt." },
      { number: 20, text: "Doch für Zion kommt er als Erlöser, / und auch für die in Jakobs Nachkommenschaft, / die umkehren von ihrer Abtrünnigkeit. / Das sagt Jahwe." },
      { number: 21, text: "\"Ich schließe einen Bund mit ihnen\",* sagt Jahwe. \"Mein Geist, der auf dir ruht, und die Worte, die ich dir anvertraut habe, sollen immer in dir bleiben, und genauso auch in deinen Nachkommen und in den Nachkommen deiner Nachkommen. Das gilt von jetzt an bis in Ewigkeit! Ich, Jahwe, habe es gesagt.\"", footnotes: ["Wird im Neuen Testament von Paulus zusammen mit Jesaja 27,9 zitiert: Römer 11,26-27."] },
    ] },
    { number: 60, verses: [
      { number: 1, text: "Steh auf, Jerusalem, und werde licht! / Denn dein Licht ist gekommen, / und die Herrlichkeit Jahwes strahlt über dir!", heading: "Jerusalems künftige Herrlichkeit" },
      { number: 2, text: "Noch hüllt Finsternis die Erde ein, / tiefes Dunkel alle Völker. / Doch über dir strahlt Jahwe auf, / seine Herrlichkeit erscheint über dir." },
      { number: 3, text: "Ganze Völker ziehen zu deinem Licht hin, / Könige zu deinem strahlenden Glanz." },
      { number: 4, text: "Schau dich um und sieh es dir an! / Sie strömen von allen Seiten zu dir. / Deine Söhne kommen von fern, / deine Töchter trägt man auf den Armen herbei." },
      { number: 5, text: "Du wirst es sehen und strahlen vor Glück, / dein Herz bebt vor Freude und öffnet sich weit. / Die Schätze der Völker werden zu dir gebracht, / der Reichtum des Meeres strömt dir zu." },
      { number: 6, text: "Kamelkarawanen bedecken dein Land, / junge Dromedare von Efa und Midian*. / Von Saba* kommen sie mit Weihrauch und Gold / und verkündigen mit Freude das Lob Jahwes.", footnotes: ["Efa war ein Sohn Midians und stammte auch von Abraham ab, siehe 1. Mose 25,2-3. Das Volk der Midianiter hatte Israel einst verwüstet, siehe Richter 6,1-6. Sie zogen als Nomaden durch die transjordanischen Wüsten.", "Saba war ein reiches Land im südlichen Arabien. Es entspricht vielleicht dem heutigen Jemen."] },
      { number: 7, text: "Alle Schafherden Kedars* sammeln sich bei dir, / die Schafböcke von Nebajot* stehen in deinem Dienst. / Als angenehme Opfer kommen sie auf meinen Altar. / So ehre ich mein herrliches Haus.", footnotes: ["Kedar. Siehe Jesaja 21,16!", "Nebajot war der älteste Sohn Ismaëls (1. Mose 25,13). Der Name steht hier vielleicht für das Reich der Nabatäer, östlich des Toten Meeres."] },
      { number: 8, text: "Was kommt da wie eine Wolke geflogen, / wie Tauben zu ihren Löchern in der steilen Wand?" },
      { number: 9, text: "Ja, die Meeresländer hoffen auf mich, / die Hochseeschiffe fahren voran / und bringen deine Kinder von ferne herbei, / und mit ihnen ihr Silber und Gold. / Das alles geschieht zur Ehre Jahwes / und weil der heilige Gott Israels dich herrlich gemacht hat." },
      { number: 10, text: "Fremde werden deine Mauern wieder bauen, / und ihre Könige werden dir dienstbar sein. / In meinem Zorn habe ich dich zwar gestraft, / doch in Gnade erbarme ich mich über dich." },
      { number: 11, text: "Stets hält man deine Tore offen, / Tag und Nacht sind sie nicht zu. / Den Reichtum der Völker bringt man zu dir, / und ihre Könige treibt man voran." },
      { number: 12, text: "Denn jedes Volk und jedes Reich, das dir nicht dient, wird bald zugrundegehen. / Diese Stämme werden völlig verheert." },
      { number: 13, text: "Die Pracht des Libanon wird zu dir gebracht, / Zypressen, Platanen und Wacholderbäume. / Den Ort meines Heiligtums sollen sie schmücken, / sollen den Platz für meine Füße zieren." },
      { number: 14, text: "Die Söhne derer, die dich beugten, / kommen nun gebückt zu dir. / Die dich verspottet haben, / bücken sich nun zu deinen Fußsohlen hin. / Sie nennen dich \"Zion Jahwes\", / Stadt, die dem heiligen Gott Israels gehört!" },
      { number: 15, text: "Du bist nicht mehr verlassen und verhasst, / eine Stadt, die von allen gemieden wird. / Ich mache dich zu einer ewigen Pracht, / zur Freude kommender Generationen." },
      { number: 16, text: "Du wirst die Milch der Völker saugen, / wirst trinken an der Brust von Königen. / Du wirst erkennen, dass ich, Jahwe, dein Retter bin, / dass der starke Gott Jakobs dein Befreier ist." },
      { number: 17, text: "Anstelle von Bronze bring ich dir Gold, / statt des Eisens bringe ich Silber herbei, / statt der Hölzer Erz, / und Eisen anstelle der Steine. / Deine Verwaltung wird Frieden sein / und deine Regierung Gerechtigkeit." },
      { number: 18, text: "Man hört nichts mehr von Gewalt in deinem Land, / von Verwüstung und Zerstörung in deinem Gebiet. / Du wirst deine Mauern \"Rettung\" nennen / und deine Tore \"Lob\"." },
      { number: 19, text: "Das Licht der Sonne wirst du künftig nicht mehr brauchen, / auch nicht mehr den Mondschein in der Nacht, / denn dein ewiges Licht wird Jahwe sein, / dein Gott leuchtet dir in herrlichem Glanz." },
      { number: 20, text: "Darum wird deine Sonne niemals mehr untergehen, / dein Mond nimmt niemals ab, / denn Jahwe ist dann dein ewiges Licht. / Und deine Trauerzeit ist für immer vorbei." },
      { number: 21, text: "Dein Volk wird nur aus Gerechten bestehen, / und das Land wird für immer ihr Eigentum sein; / ein blühender Garten, von Jahwe angelegt, / ein Werk seiner Hände zu seinem Ruhm." },
      { number: 22, text: "Die kleinste Sippe wird eine Tausendschaft sein, / der geringste ein gewaltiger Stamm. / Wenn die Zeit dafür gekommen ist, / führe ich, Jahwe, es ganz schnell herbei." },
    ] },
    { number: 61, verses: [
      { number: 1, text: "Der Geist von Jahwe ruht auf mir, / denn Jahwe hat mich gesalbt*. / Er hat mich gesandt, den Elenden gute Botschaft zu bringen / und zerbrochene Herzen zu verbinden; / den Gefangenen zu verkünden: \"Ihr seid frei!\" / und den Gefesselten: \"Ihr seid los!\";", heading: "Die Botschaft des Messias", footnotes: ["Gesalbt (Hebräisch: maschah) ist die Wurzel von maschiah, der Messias, der Gesalbte. Damit werden hier alle Personenausprägungen des dreieinigen Gottes erwähnt."] },
      { number: 2, text: "um auszurufen das Gnadenjahr Jahwes* / und den Tag der Rache für unseren Gott, / um alle Trauernden zu trösten", footnotes: ["Wird im Neuen Testament von Jesus Christus zitiert: Lukas 4,18-19."] },
      { number: 3, text: "und den Trauernden Zions Freude zu bringen. / Schmuck bekommen sie anstelle von Schmutz, / Freudenöl statt Trauersack, / Jubellieder statt Mutlosigkeit. / Man nennt sie \"Terebinthen der Gerechtigkeit\", / eine Pflanzung Jahwes, die seine Herrlichkeit zeigt." },
      { number: 4, text: "Die uralten Trümmerstätten bauen sie dann auf, / stellen die wüsten Orte wieder her. / Die zertrümmerten Städte bauen sie neu, / alles, was Generationen lang Ruine war." },
      { number: 5, text: "Dann nehmen Fremde euch die Arbeit ab, / sie weiden eure Herden, / bestellen euer Land / und werden eure Weingärtner sein." },
      { number: 6, text: "Und euch wird man \"Priester Jahwes\" nennen, / \"Diener unseres Gottes\" sagt man zu euch. / Ihr werdet genießen, was die Völker besitzen, / denn ihre Schätze gehören jetzt euch." },
      { number: 7, text: "Statt des Doppelmaßes eurer Schmach, / statt der Schande, die als euer Anteil galt, / wird euer Teil am Land nun doppelt so groß; / ewige Freude wird euch geschenkt." },
      { number: 8, text: "\"Denn ich, Jahwe, ich liebe das Recht / und hasse den gemeinen Raub. / Weil ich treu bin, belohne ich sie / und schließe mit ihnen einen ewigen Bund." },
      { number: 9, text: "Ihre Nachkommen sind unter den Stämmen bekannt, / ihre Sprösslinge unter den Völkern. / Wer sie sieht, erkennt gleich: / Das sind die, die Jahwe gesegnet hat.\"" },
      { number: 10, text: "Überaus freue ich mich über Jahwe! / Meine Seele jubelt über meinen Gott! / Er kleidet mich in Gewänder des Heils / und legt mir den Mantel der Gerechtigkeit um. / Wie ein Bräutigam bin ich festlich geschmückt, / wie eine Braut, die ihr Geschmeide anlegt." },
      { number: 11, text: "Denn wie die Erde Pflanzen hervortreibt, / wie ein Garten die Saat wachsen lässt, / so bringt Jahwe, der Herr, unsere Gerechtigkeit hervor, / unser Lob bei allen Völkern." },
    ] },
    { number: 62, verses: [
      { number: 1, text: "Um Zions willen darf ich nicht schweigen, / um Jerusalems willen will ich nicht ruhen, / bis das Recht in ihm aufstrahlt wie das Morgenlicht, / und seine Rettung wie eine Fackel in der Nacht.", heading: "Die Herrlichkeit Jerusalems" },
      { number: 2, text: "Die Völker werden deine Gerechtigkeit sehen / und alle Könige deine strahlende Pracht. / Man legt dir einen neuen Namen bei, / den Jahwe selbst für dich bestimmt." },
      { number: 3, text: "Du wirst ein Schmuckstück sein in Jahwes Hand, / ein königliches Diadem*, gehalten von deinem Gott.", footnotes: ["Ein Diadem ist keine Krone, sondern ein schmales Band aus Seide, Leinen oder Edelmetall, das oft mit Perlen oder Edelsteinen besetzt ist. Es symbolisiert königliche Würde und Macht."] },
      { number: 4, text: "Du wirst nicht länger \"die Verstoßene\" genannt, / dein Land wird nicht mehr \"Ödland\" heißen, / sondern \"Gottes Liebling\" nennt man dich / und dein Land \"Regenland\". / Denn Jahwe hat seine Freude an dir / und vermählt sich mit deinem Land." },
      { number: 5, text: "Denn wie der junge Mann sein Mädchen heiratet, / so vermählen sich deine Söhne mit dir. / Und wie der Bräutigam sich an seiner Braut freut, / so hat dein Gott Freude an dir." },
      { number: 6, text: "Ich habe Wächter auf deine Mauern gestellt, Jerusalem! / Ihr Rufen verstummt nicht einen Augenblick, / weder am Tag noch in der Nacht. / Ihr Wächter sollt Jahwe an Jerusalem erinnern! / Gönnt euch keine Rast," },
      { number: 7, text: "und lasst ihm keine Ruhe, / bis er Jerusalem wieder so hergestellt hat, / dass alle Welt die Stadt rühmt." },
      { number: 8, text: "Jahwe hat geschworen bei seiner rechten Hand / und seinem Siegesarm: \"Nie mehr wird dein Korn die Speise deiner Feinde sein, / nie mehr trinken Fremde den Wein, / für den du so hart gearbeitet hast." },
      { number: 9, text: "Nein, wer das Korn einbringt, soll davon essen und Jahwe loben. / Wer den Wein liest, soll davon trinken im Vorhof meines Heiligtums.\"" },
      { number: 10, text: "Zieht durch die Tore ein und aus / und bahnt dem Volk einen Weg! Baut, ja, baut die Straße und räumt die Steine aus dem Weg! / Stellt ein Zeichen für die Völker auf!" },
      { number: 11, text: "Seht, Jahwe lässt es hören bis ans Ende der Welt: / \"Sagt der Zionsstadt: 'Pass auf, dein Retter kommt! / Schau, er bringt den Siegespreis mit! / Das Volk, das er befreite, zieht vor ihm her.'\"" },
      { number: 12, text: "Man wird es nennen \"das heilige Volk\" und \"die Erlösten Jahwes\". / Und dich wird man nennen \"die Begehrte\" und \"die nie mehr verlassene Stadt\"." },
    ] },
    { number: 63, verses: [
      { number: 1, text: "\"Wer kommt da vom Edomiterland, / aus Bozra mit grellrotem Gewand? / Er schreitet in prächtigen Kleidern daher, / stolz in seiner gewaltigen Kraft.\" / \"Ich bin es, der Gerechtigkeit verkündet / und der die Macht zum Retten hat!\"", heading: "Gericht über Völker" },
      { number: 2, text: "\"Warum ist dein Gewand so rot? / Hast du Trauben in der Kelter zerstampft?\"" },
      { number: 3, text: "\"Ja, ich trat die Kelter ganz allein, / von den Völkern war niemand dabei. / Ich trat sie zusammen in meinem Zorn, / zerstampfte sie in meinem Grimm. / Ihr Saft ist an meine Kleidung gespritzt, / ich besudelte mein ganzes Gewand." },
      { number: 4, text: "Ein Tag der Rache lag mir im Sinn, / und das Jahr der Erlösung war gekommen." },
      { number: 5, text: "Ich blickte umher, doch niemand half. / Ich wunderte mich sehr, doch keiner unterstützte mich. / Da half mir mein eigener Arm, / und mein Zorn gab mir die Kraft." },
      { number: 6, text: "Ich zertrat die Völker in meinem Zorn, / zerstampfte sie in meinem Grimm / und ließ ihren Saft im Boden versickern.\"" },
      { number: 7, text: "Ich will daran erinnern, wie Jahwe uns seine Gnade erwies, / will denken an die Ruhmestaten des Herrn, / an alles, was Jahwe für uns tat, / an seine große Güte, die er dem Volk Israel erwies, / und zwar aus seinem Erbarmen heraus / und seiner übergroßen Freundlichkeit.", heading: "Gebet und Erhörung" },
      { number: 8, text: "Er sagte: \"Gewiss sind sie mein Volk, / Kinder, die nicht enttäuschen!\" Und so wurde er ihr Befreier" },
      { number: 9, text: "aus all ihrer Not. / Kein Bote und kein Engel – er selbst hat sie befreit! / Aus Liebe und Erbarmen hat er sie erlöst, / sie aufgehoben und getragen in all den Tagen der frühen Zeit." },
      { number: 10, text: "Doch sie lehnten sich gegen ihn auf, / betrübten seinen Heiligen Geist. / Da wandelte er sich und wurde ihr Feind / und kämpfte nun selbst gegen sie." },
      { number: 11, text: "Da dachten sie wieder an die vorige Zeit, / als Mose noch in ihrer Mitte war: / \"Wo ist der Gott, der den Hirten seiner Schafe aus dem Meer herausgezogen hat?* / Wo ist der, der ihm den Heiligen Geist ins Innerste gab,", footnotes: ["herausgezogen hat. Das erinnert an 2. Mose 2,10."] },
      { number: 12, text: "der ihm beistand mit seinem gewaltigen Arm, / der das Meer zerteilte vor seinem Volk / und sich so einen ewigen Namen erschuf?" },
      { number: 13, text: "Wo ist der, der sie durch die Fluten führte, / wie Pferde durch die Steppe, / sodass niemand ins Stolpern geriet?" },
      { number: 14, text: "Wie das Vieh, das ins Tal hinabzieht, / brachte der Geist Jahwes sie zum Ruheplatz. / So hast du dein Volk geführt / und dir einen ruhmvollen Namen gemacht.\"" },
      { number: 15, text: "Blick doch vom Himmel herab! / Sieh her vom Wohnort deiner Majestät und Heiligkeit! / Wo ist dein Liebeseifer für uns, / wo deine unvergleichliche Macht? / Warum hältst du dein Mitleid, dein Erbarmen gegen uns zurück?" },
      { number: 16, text: "Du bist doch unser Vater! / Abraham weiß nichts von uns, / und Israel* würde uns nicht einmal kennen. / Du bist unser Vater, Jahwe! / \"Unser Erlöser von jeher\" wirst du genannt.", footnotes: ["Israel. Gemeint ist Jakob, der von Gott den Namen Israel erhielt."] },
      { number: 17, text: "Warum, Jahwe, hast du uns abirren lassen? / Warum hast du uns so starrsinnig gemacht? / Warum sind wir ohne Ehrfurcht vor dir? / Kehr doch bitte wieder um! / Wir sind doch deine Diener und das Volk, das dir gehört!" },
      { number: 18, text: "Vor kurzem erst vertrieben unsere Feinde dein heiliges Volk / und zertrampelten dein Heiligtum." },
      { number: 19, text: "Es ist, als hättest du nie über uns geherrscht, / als hättest du uns nie zu deinem Eigentum gemacht! / O reiß doch den Himmel auf und komm zu uns herab, / dass die Berge vor dir erbeben; /" },
    ] },
    { number: 64, verses: [
      { number: 1, text: "wie das Feuer Reisig entfacht / und wie es Wasser wallen macht; / dass deine Feinde merken, wer du bist, / dass die Völker vor Angst vergehen," },
      { number: 2, text: "wenn du furchterregende Taten vollbringst, / die niemand von dir erwartet hat! / Ja, führest du doch herab, dass die Berge erbebten vor dir!" },
      { number: 3, text: "Noch nie hat man so etwas gehört, / noch niemals so etwas erlauscht, / noch nie hat ein Auge einen Gott gesehen wie dich, / der an denen, die auf ihn hoffen, so gewaltige Dinge tut!*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: 1. Korinther 2,9."] },
      { number: 4, text: "Ach, kämst du doch dem entgegen, / der freudig tut, was recht vor dir ist, / und bei seinem Tun an dich denkt! / Nun aber traf uns dein Zorn, / denn wir haben uns versündigt an dir. / Seit jeher sind wir treulos gewesen!" },
      { number: 5, text: "Wir alle sind von Unrecht befleckt, / selbst unsere gerechten Taten sind besudelt wie ein schmutziges Gewand. / Wie Laub sind wir alle verwelkt, / unsere Schuld trägt uns fort wie der Wind." },
      { number: 6, text: "Es gab niemand, der deinen Namen anrief, / der sich aufraffte, um festzuhalten an dir. / Denn du hattest dich verborgen vor uns, / uns preisgegeben unserer Schuld." },
      { number: 7, text: "Trotzdem bist du unser Vater, Jahwe! / Du bist der Töpfer, wir sind der Ton; / wir alle sind Gefäße deiner Hand." },
      { number: 8, text: "O Jahwe, zürne nicht so sehr, / denk nicht für immer an unsere Schuld! / Schau bitte her, wir sind doch dein Volk!" },
      { number: 9, text: "Die Städte deines heiligen Landes sind zerstört, / Zion ist verwüstet, / Jerusalem ein Trümmerberg." },
      { number: 10, text: "Unser heiliges und herrliches Haus, in dem unsere Väter dich lobten, ist ein Raub der Flammen geworden. / Alles, was uns lieb und wert war, ist zerstört." },
      { number: 11, text: "Kannst du dabei noch an dich halten, Jahwe? / Schaust du all dem schweigend zu? / Erniedrigst du uns ganz und gar?" },
    ] },
    { number: 65, verses: [
      { number: 1, text: "\"Ich war zu erreichen für die, die nicht nach mir fragten. / Ich war zu finden für die, die nicht nach mir suchten. / Ich sagte zu einem Volk, das gar nicht zu mir rief: / 'Hier bin ich! Hier bin ich!'", heading: "Gericht und Errettung" },
      { number: 2, text: "Den ganzen Tag streckte ich meine Hände aus nach einem widerspenstigen Volk, / das den eigenen Gedanken nachläuft auf einem unguten Weg.*", footnotes: ["Wird im Neuen Testament von Paulus zitiert: Römer 10,20-21."] },
      { number: 3, text: "Fortwährend beleidigen sie mich und fordern mich heraus. / In Götzengärten schlachten sie, verbrennen Rauchopfer auf Ziegeln." },
      { number: 4, text: "Sie hocken in Kammern von Gräbern, / verbringen in Höhlen die Nächte, / sie essen Fleisch von Schweinen / und haben gräuliche Brühe in ihren Gefäßen." },
      { number: 5, text: "Sie sagen: 'Bleib, wo du bist und komm mir nicht nahe, / ich bin zu heilig für dich!'* – Diese Leute sind wie Rauch in meiner Nase, / wie ein Feuer, das den ganzen Tag brennt.", footnotes: ["zu heilig für dich. Das heißt: Ich bin mit heiligen Dingen in Berührung gekommen, und wenn du mich anfasst, bist du auch geweiht!"] },
      { number: 6, text: "Seht her, alles ist aufgeschrieben vor mir. / Und ich werde nicht schweigen, sondern ich zahle es ihnen heim. / Ich zahle ihnen den Lohn aus" },
      { number: 7, text: "für ihre Schuld / und die Schuld ihrer Väter\", sagt Jahwe. / \"Weil sie auf den Bergen Weihrauch verbrannten und mich auf den Hügeln verhöhnten, / zahle ich ihnen den Lohn für ihr Tun; / was sie verdienen, messe ich ihnen zu.\"" },
      { number: 8, text: "So spricht Jahwe: / \"Wie man von einer Traube sagt, in der noch Saft enthalten ist: / 'Wirf sie nicht weg, ein Segen ist in ihr!', / so will ich um meiner Diener willen tun, / und nicht das Ganze verwerfen." },
      { number: 9, text: "Auch künftig wird Jakob Nachkommen haben / und Juda Erben für mein Bergland. / Die von mir Erwählten sollen es erben, / und die mir dienen, wohnen dort." },
      { number: 10, text: "Schafe weiden wieder in der Ebene Scharon / und Rinder lagern im Tal Achor* / für mein Volk, das wieder nach mir fragt.", footnotes: ["Scharon ist eine fruchtbare Ebene am Mittelmeer, Achor ein unfruchtbares Tal in der Nähe von Jericho (siehe Josua 7,26). Sie repräsentieren hier vielleicht die West- und Ostgrenze des ganzen Landes."] },
      { number: 11, text: "Doch ihr, die ihr Jahwe verlasst, / den Berg meines Heiligtums vergesst, / die ihr einen Tisch für Gad, den Glücksgott, deckt, / und der Schicksalsgöttin Meni* den Krug mit Würzwein füllt:", footnotes: ["Gad und Meni stehen auch für die Planeten Jupiter und Venus."] },
      { number: 12, text: "Das Schwert ist euch als Schicksal bestimmt; / kniet euch nur zum Abschlachten hin! / Denn ich hatte gerufen, aber ihr gabt keine Antwort, / ich hatte geredet, aber ihr habt nicht gehört, / sondern habt gerade das getan, was vor mir böse ist, / habt gerade das erwählt, was mir missfällt.\"" },
      { number: 13, text: "Darum spricht Jahwe, der Herr: / \"Meine Diener bekommen zu essen, doch ihr müsst hungern; / meine Diener haben zu trinken, doch ihr werdet durstig sein; / meine Diener werden glücklich sein, doch ihr werdet beschämt;" },
      { number: 14, text: "meine Diener werden jubeln vor Freude, / doch ihr werdet schreien vor Qual und heulen vor lauter Verzweiflung." },
      { number: 15, text: "Nur als Fluchwort werden eure Namen bleiben, / wenn die Erwählten schwören: 'So wird Jahwe, der Herr, dich töten!' / Doch sie bekommen Ehrennamen," },
      { number: 16, text: "dass dann, wenn man sich Segen wünscht, / man sich segnet bei dem treuen Gott; / und wenn man im Land schwört, / schwört man bei Gott, der die Wahrheit ist. / Dann werden die früheren Nöte vergessen und meinen Augen entschwunden sein." },
      { number: 17, text: "Denn wisst: Ich werde einen neuen Himmel und eine neue Erde erschaffen.* / Dann sehnt sich keiner mehr zurück nach dem, was früher war, / keinem mehr kommt das noch in den Sinn.", footnotes: ["Dieser Vers oder der die Parallele Jesaja 66,22 wird im Neuen Testament von Petrus zitiert: 2. Petrus 3,13."] },
      { number: 18, text: "Freut euch vielmehr und jubelt ohne Ende / über das, was ich nun erschaffe. / Zur Stadt der Freude mache ich Jerusalem, / und seine Bewohner erfülle ich mit Glück." },
      { number: 19, text: "Und auch ich will über Jerusalem jubeln, / will mich freuen über mein Volk. / Dann wird kein Weinen mehr zu hören sein, / kein Wehgeschrei mehr in der Stadt." },
      { number: 20, text: "Es wird dort keinen Säugling geben, der nur wenige Tage erlebt, / keinen Greis, der nicht das volle Alter erreicht. / Wer als Hundertjähriger stirbt, gilt noch als jung, / und wer nicht hundert Jahre alt wird, gilt als Sünder, der vom Fluch getroffen ist." },
      { number: 21, text: "Sie bauen Häuser und wohnen auch darin, / pflanzen Weinberge und genießen auch ihren Ertrag." },
      { number: 22, text: "Sie bauen nicht, damit ein anderer in ihrem Haus wohnt; / sie pflanzen nicht, damit ein anderer die Früchte genießt. / Die Menschen meines Volkes sollen alt wie Bäume werden, / meine Auserwählten sollen die Frucht ihrer Arbeit genießen." },
      { number: 23, text: "Ihre Arbeit wird nicht mehr vergeblich sein, / nicht für einen jähen Tod bringen sie Kinder zur Welt. / Denn sie sind die Nachkommen der Gesegneten Jahwes, / und ihre Sprösslinge werden bei ihnen sein." },
      { number: 24, text: "Schon ehe sie rufen, gebe ich ihnen Antwort, / während sie noch reden, erhöre ich sie." },
      { number: 25, text: "Wolf und Lamm weiden zusammen, / der Löwe frisst Stroh wie das Rind / und die Schlange wirklich nur Staub: / Sie werden nichts Böses mehr tun / und niemand mehr schaden auf meinem heiligen Berg\", spricht Jahwe." },
    ] },
    { number: 66, verses: [
      { number: 1, text: "So spricht Jahwe: / \"Der Himmel ist mein Thron und die Erde der Schemel, auf den ich meine Füße stelle. / Was für ein Haus wollt ihr da für mich bauen? / Welcher Ort könnte dort mein Ruheplatz sein?", heading: "Gericht und Hoffnung" },
      { number: 2, text: "Ich habe das alles doch selber gemacht, / alles entstand durch mich\", sagt Jahwe.* / \"Doch auf den will ich blicken, / der gebeugt und zerknirscht meinem Wort entgegenbebt.", footnotes: ["Wird im Neuen Testament von Stephanus zitiert: Apostelgeschichte 7,49-50."] },
      { number: 3, text: "Da schlachtet jemand ein Rind – erschlägt aber auch einen Menschen –, / da opfert einer ein Schaf – bricht aber auch einem Hund das Genick –, / da bringt einer Speisopfer dar – und versprengt Schweineblut dabei –, / da verbrennt er Weihrauch für mich – und segnet einen Götzen. / Sie haben ihre eigenen Wege gewählt, / an ihren Scheusalen Gefallen gefunden;" },
      { number: 4, text: "deshalb wähle ich nun auch Misshandlungen für sie, / lasse über sie kommen, wovor ihnen graut. / Denn ich habe gerufen, doch keiner gab mir Antwort; / ich habe geredet, doch sie haben nicht darauf gehört, / sondern gerade das getan, was vor mir böse ist, / gerade das erwählt, was mir missfällt.\"" },
      { number: 5, text: "Hört die Rede Jahwes, die ihr seinem Wort entgegenbebt: / \"Es höhnen eure Brüder, die euch hassen, / die euch verstoßen, weil ihr zu mir steht: / 'Soll Jahwe doch seine Ehre zeigen, / dann sehen wir, wie ihr euch freut!'\" / Doch sie werden zuschanden." },
      { number: 6, text: "Hört ihr den Lärm in der Stadt, / das Kampfgetümmel im Tempel? / Das ist die Stimme Jahwes, / der heimzahlt, was seine Feinde verdienen." },
      { number: 7, text: "Noch ehe die Frau ihre Wehen bekam, hatte sie schon geboren, / noch ehe sie Geburtsschmerzen empfand, hatte sie einen Jungen entbunden." },
      { number: 8, text: "Wer hat so etwas je gehört, / wer hat dergleichen je gesehen? / Wird denn ein Volk auf einen Schlag geboren, / wird ein Land bevölkert an einem einzigen Tag? / Doch so wird es Zion ergehen. / Kaum spürt sie die Wehen, schon sind ihre Kinder da." },
      { number: 9, text: "\"Sollte ich denn die Geburt einleiten und das Kind dann stecken lassen?\", spricht Jahwe. / \"Ich bin es doch, der gebären lässt, sollte ich die Geburt verhindern?\", spricht dein Gott." },
      { number: 10, text: "Freut euch mit Jerusalem, / jubelt über die Stadt, die ihr sie liebt! / Teilt nun auch ihre Freude mit ihr, / die ihr über sie getrauert habt." },
      { number: 11, text: "Saugt euch satt an ihrer tröstenden Brust, / trinkt und labt euch an der Fülle ihrer Herrlichkeit!" },
      { number: 12, text: "Denn so spricht Jahwe: / \"Seht, wie einen Strom leite ich den Frieden zu ihr, / den Reichtum der Völker wie einen überfließenden Bach. / Trinkt euch an dieser Fülle satt! / Auf den Armen werdet ihr getragen, und auf den Knien wird man euch wiegen." },
      { number: 13, text: "Ich will euch trösten, wie nur eine Mutter trösten kann. / Und an Jerusalem findet ihr Trost." },
      { number: 14, text: "Wenn ihr das erlebt, werdet ihr voll Freude sein, / wie frisches Gras sprosst euer Lebensmut.\"Seinen Dienern offenbart Jahwe seine Macht, / aber seine Feinde sind von ihm bedroht." },
      { number: 15, text: "Denn Jahwe wird im Feuer kommen, / und seine Streitwagen werden wie ein Sturmwind sein. / Er glüht vor Zorn und lässt ihm freien Lauf, / sein Drohen flammt im Feuer auf." },
      { number: 16, text: "Denn mit Feuer und Schwert hält Jahwe Gericht. / Es werden viele sein, die Jahwe erschlägt." },
      { number: 17, text: "\"Die sich den Götzengärten weihen, / sich reinigen, wie es der in ihrer Mitte zeigt, / die Schweinefleisch, gräuliches Zeug und Feldmäuse essen, / werden miteinander weggerafft\", spricht Jahwe." },
      { number: 18, text: "\"Denn ich kenne ihr ganzes Tun und ihre Gedanken, und ich komme, um die Völker aller Sprachen zusammenzurufen. Sie werden auch kommen und meine Herrlichkeit sehen." },
      { number: 19, text: "Das wird für sie ein warnendes Zeichen sein. Von den Überlebenden werde ich Boten zu den Völkern schicken, die noch nichts von mir gehört und meine Herrlichkeit nicht gesehen haben: nach Spanien, Libyen und Lydien, nach Meschesch, Tubal und Jawan*. Sie sollen dort meine Herrlichkeit bekannt machen.", footnotes: ["Lydien ... Jawan. Völker Kleinasiens, Jawan ist Ionien, das von den Griechen besiedelte Kleinasien."] },
      { number: 20, text: "Sie werden alle eure Brüder zurückbringen auf Pferden, Maultieren und Dromedaren, in Wagen und in Sänften als eine Opfergabe der Völker für Jahwe. Sie bringen sie zu meinem heiligen Berg nach Jerusalem\", spricht Jahwe, \"so wie die Israeliten Speisopfer in reinen Gefäßen zum Tempel Jahwes bringen." },
      { number: 21, text: "Auch von ihnen werde ich einige zu Priestern und Leviten machen\", spricht Jahwe." },
      { number: 22, text: "\"Und so wie der neue Himmel, den ich schaffen werde, und die neue Erde* für immer bestehen bleiben\", spricht Jahwe, \"so werdet auch ihr als Volk nie untergehen und vergessen sein.", footnotes: ["Oder die Parallele Jesaja 65,17 wird im Neuen Testament von Petrus zitiert: 2. Petrus 3,13."] },
      { number: 23, text: "Es wird kommen, dass an jedem Neumondstag und Sabbat sich alle Menschen vor mir einfinden und mich anbeten\", spricht Jahwe." },
      { number: 24, text: "\"Dann gehen sie hinaus und sehen die Leichen der Menschen, die von mir abgefallen sind. Denn der Wurm in jenen wird nicht sterben und das Feuer in ihnen niemals erlöschen. Sie werden ein Ekel für alle Menschen sein.\"" },
    ] },
  ],
};